INSERT INTO spells (id, name, school, subschool, descriptor, level, type, class_lists, casting_time, range, target, area, effect, duration, saving_throw, spell_resistance, description, material, arcane_focus, divine_focus, costly_components)
VALUES
  ('geas_quest', 'Geas/Quest', 'enchantment', 'compulsion', 'curse, language-dependent, mind-affecting', 5, 'both', 'bard 6, cleric/oracle 6, inquisitor 5, sorcerer/wizard 6, witch 6; Domain charm 6, nobility 6; Subdomain ancestors 6, honor 6', '10 minutes', NULL, 'one living creature', NULL, NULL, NULL, 'none', 'yes', 'This spell functions similarly to lesser geas, except that it affects a creature of any HD and allows no saving throw.', NULL, NULL, false, false),
  ('genesis', 'Genesis', 'conjuration', 'creation', NULL, 9, 'arcane', 'artifice 9', '1 week (8 hours/day)', '180 ft.', NULL, NULL, 'a demiplane on the Ethereal Plane centered on you', 'instantaneous', 'none', 'no', 'You create an immobile, finite demiplane with limited access. Demiplanes created by this spell are very small. At first, the demiplane grows at a rate of 1-foot-radius per day, up to a 180-foot radius. You determine the environment in the demiplane, reflecting most any desire you can visualize, such as atmosphere, water, temperature, and the shape of the terrain. The spell cannot create life, nor can it create buildings. If desired, these must be brought in by some other fashion.', 'small crystalline sphere worth 25,000 gp', NULL, false, true),
  ('geniekind', 'Geniekind', 'transmutation', 'polymorph', NULL, 5, 'both', 'cleric 5, druid 5, sorcerer/wizard 5, summoner 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon casting this spell, you must choose one type of genie to transform into, selecting from djinni, efreeti, marid, or shaitan. You retain your basic physical appearance but shift in some way to become more akin to the genie type you chose. While under the effects of geniekind, you gain a +2 racial bonus on all saving throws against paralysis, poison, sleep, and stunning effects, and a +4 enhancement bonus to your natural armor bonus. You also gain a +2 enhancement bonus to Constitution and a +5 bonus on all Diplomacy checks made when interacting with creatures of the same elemental subtype as your chosen genie. In addition, you gain other abilities depending upon the type of genie you choose to assume the form of, as detailed below.', 'a pinch of dust, embers, wind-blown sand or drops of water, depending on the genie type', NULL, false, false),
  ('genius_avaricious', 'Genius Avaricious', 'conjuration', 'creation', 'evil', 6, 'both', 'cleric 6, sorcerer/wizard 6', '10 minutes', 'touch', NULL, NULL, 'a vestige of the archdevil Mammon imbues a coin with a negotiable degree of power', 'instantaneous (see text)', 'none', 'no', 'Casting this spell constitutes performing a rite of sacrifice to the archdevil Mammon, making an offering to the Lord of Erebus and channeling a measure of his disembodied might into a single coin. The power and abilities of this vestige correspond directly to the value of the offering, allowing for three distinct effects.', 'valuable offerings; see text', 'one gold coin', false, false),
  ('gentle_breeze', 'Gentle Breeze', 'evocation', 'air', NULL, 1, 'both', 'druid 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object', NULL, NULL, '1 hour (D)', 'Will negates (harmless)', 'yes (harmless)', 'You create a light wind that blows only against the target, from a direction of your choice. The breeze grants the target a +2 circumstance bonus on saves against very hot conditions, severe heat, and saves against clouds, vapors, and gases (such as cloudkill, stinking cloud, and inhaled poisons). There must be air present to use this spell.', NULL, NULL, false, false),
  ('gentle_repose', 'Gentle Repose', 'necromancy', NULL, NULL, 2, 'both', 'cleric/oracle 2, shaman 2, sorcerer/wizard 3, witch 2; Domain repose 2; Mystery time 2', '1 standard action', 'touch', 'corpse touched', NULL, NULL, '1 day/level', 'Will negates (object)', 'yes (object)', 'You preserve the remains of a dead creature so that they do not decay. Doing so effectively extends the time limit on raising that creature from the dead (see raise dead). Days spent under the influence of this spell don’t count against the time limit. Additionally, this spell makes transporting a slain (and thus decaying) comrade less unpleasant.', 'salt and a copper piece for each of the corpse’s eyes', NULL, true, false),
  ('geomessage', 'Geomessage', 'illusion', 'figment', NULL, 3, 'both', 'arcanist 4, bard 3, hunter 3, medium 3, occultist 3, ranger 3, skald 3, sorcerer/wizard 4', '1 minute', 'touch', 'surface touched', NULL, NULL, '1 day/level', 'none', 'no', 'You create a written message of 50 words or fewer, or else an image, a drawing, or a similar diagram. The figment hangs invisible and obscured upon the target surface for the duration of the spell. Another casting of geomessage is needed to cause the figment to arrange itself into the intended message.', 'a scrap of vellum', NULL, false, false),
  ('getaway', 'Getaway', 'conjuration', NULL, 'teleportation', 6, 'arcane', 'bard 6, sorcerer/wizard 6; Mystery streets 6', '1 minute', 'unlimited', NULL, NULL, NULL, '1 hour/level', 'none', 'no', 'Getaway teleports you and allies you designate at the time of casting to a predetermined location. You must initially cast the spell at that location-all creatures affected by the spell must be present at that time and within 30 feet of you. At any time before the spell’s duration expires, you may trigger the spell as a swift action. At this time, all affected creatures (or their remains and gear) within 30 feet of you are teleported to the location where you first cast the spell. Creatures more than 30 feet away from you are left behind. Selected creatures within 30 feet of you who do not wish to travel with you at that time can simply choose not to go. You can be transported any distance within a plane but cannot travel between planes.', 'a brass doorknob', NULL, false, false),
  ('geyser', 'Geyser', 'conjuration', 'creation', 'fire, water', 4, 'both', 'druid 4, magus 5, sorcerer/wizard 5; Bloodline aquatic 4; Elemental School fire 5, water 5; Mystery volcano 5, waves 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'spout of boiling water filling a 5 ft. square and spraying upward 10 ft./2 levels', 'concentration + 1 round/level', 'Reflex partial (see below)', 'no', 'You cause a column of boiling water to spring forth from any horizontal surface, knocking over creatures directly over it and exposing nearby creatures to searing droplets as its spray falls back to the ground.', 'a piece of lava rock', NULL, true, false),
  ('ghost_brand', 'Ghost Brand', 'transmutation', NULL, 'shadow', 3, 'arcane', 'bard 4, occultist 3, spiritualist 4, witch 4', '10 minutes', 'touch', 'one willing creature and one object touched', NULL, NULL, '1 day/level (D)', 'none', 'no', 'You alter the fundamental substance of a single object up to 2 cubic feet per level in size and at least one size category smaller than the target creature, causing it to become shadowy and intangible, as though made out of quasi-real shadowstuff. You link the intangible item to the target’s flesh by making a brand shaped like the item on the target’s skin. The intangible item merges with the target’s flesh and is contained within the target’s body, moving with the target wherever it goes. The creature can retrieve the item or reabsorb it as a full-round action, and can do so as many times as it wants. When worn or wielded by the target, the item regains its solidity and functions normally, though the target can’t drop or remove the item (other than by using the full-round action), nor can it be disarmed or stolen. If the item is destroyed, the spell ends. If the ghost brand spell is dispelled while the object is inside the target’s body, the object bursts out of the target’s flesh, dealing 3d6 points of piercing and slashing damage to the target that bypasses DR, as well as 1d6 points of bleed damage.', 'a branding iron and a strip of white silk worth 10 gp', NULL, false, true),
  ('ghost_sound', 'Ghost Sound', 'illusion', 'figment', NULL, 0, 'arcane', 'bard 0, magus 0, psychic 0, sorcerer/wizard 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'illusory sounds', '1 round/level (D)', 'Will disbelief', 'no', 'Ghost sound allows you to create a volume of sound that rises, recedes, approaches, or remains at a fixed place. You choose what type of sound ghost sound creates when casting it and cannot thereafter change the sound’s basic character.', 'a bit of wool or a small lump of wax', NULL, false, false),
  ('ghost_whip', 'Ghost Whip', 'evocation', NULL, NULL, 2, 'both', 'cleric 2, inquisitor 2, magus 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, witch 2; Bloodline ectoplasm 2', '1 standard action', '0 ft.', NULL, NULL, 'whip of flexible ectoplasm', '1 round/level (D)', 'none', 'yes', 'A white, 15-foot-long lash of ghostly evanescence appears from your hand. This weapon is treated as a ghost touch whip with no enhancement bonus. You can wield it as a whip as if you were proficient. Attacks with a ghost whip are resolved as incorporeal touch attacks. The whip affects only creatures you attack with it, passing through objects and other creatures in its path and thereby allowing you to ignore cover between you and your target. When a ghost whip attack passes through total cover, the target is treated as having total concealment (50% miss chance). Against incorporeal and undead creatures, a ghost whip deals lethal damage and can be used to perform drag or reposition combat maneuvers (in addition to a whip’s normal disarm and trip maneuvers). A ghost whip cannot be disarmed or sundered.', NULL, NULL, false, false),
  ('ghost_wolf', 'Ghost Wolf', 'conjuration', 'creation', NULL, 2, 'arcane', 'bloodrager 4, sorcerer/wizard 4, summoner 2', '10 minutes', '0 ft.', 'one quasi-real wolflike creature', NULL, NULL, '1 hour/level (D) or 1 round/level; see text', 'none (see description)', 'no', 'This spell conjures a Large, quasi-real, wolflike creature made of roiling black smoke. It functions as phantom steed, except as noted above. In addition, the creature radiates an aura of fear. Any creature with fewer than 6 Hit Dice within 30 feet (except the ghost wolf‘s rider) must make a Will save or become shaken for 1d4 rounds (this is a mind-affecting fear effect). A creature that makes its Will save is unaffected by the steed’s fear aura for 24 hours.', NULL, 'dire wolf tooth', false, false),
  ('ghostbane_dirge', 'Ghostbane Dirge', 'transmutation', NULL, NULL, 1, 'both', 'bard 2, cleric/oracle 2, inquisitor 2, paladin 1, shaman 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates', 'yes', 'The target coalesces into a semi-physical form for a short period of time. While subject to the spell, the incorporeal creature takes half damage (50%) from nonmagical attack forms, and full damage from magic weapons, spells, spell-like effects, and supernatural effects.', 'an old reed from a wind instrument', NULL, true, false),
  ('ghostly_disguise', 'Ghostly Disguise', 'illusion', 'glamer', NULL, 2, 'both', 'alchemist 2, bard 2, inquisitor 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minute/level (D)', NULL, NULL, 'You make yourself—including clothing, armor, weapons, and equipment—appear translucent like a ghost. Any mundane or magical disguise on you is affected by this illusion as well; for example, if you are disguised as the king or a sahuagin, you look like a ghostly version of the king or a sahuagin. Your ghostly form may have a pale green, blue, or violet coloration, or a muted version of your normal appearance.', NULL, NULL, false, false),
  ('ghoul_army', 'Ghoul Army', 'necromancy', NULL, 'evil', 5, 'both', 'cleric 5, sorcerer/wizard 5, witch 5', '1 standard action', '5 feet', NULL, NULL, NULL, '1 round/level', 'Fortitude half (see text)', 'no', 'By scattering a handful of ghoul’s teeth across the ground, you cause 1d4+1 ghouls led by a single ghast to rise up from the ground around you. The ghouls and their ghast leader must appear in squares adjacent to you, but after that they follow your spoken commands unerringly.', 'a handful of ghoul’s teeth', NULL, true, false),
  ('ghoul_hunger', 'Ghoul Hunger', 'necromancy', NULL, 'evil, mind-affecting', 2, 'both', 'antipaladin 2, cleric/oracle 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 round/level; see text', 'Will negates; see text', 'yes', 'You awaken an unnatural hunger in the target, compelling it to fall upon a nearby helpless or dead humanoid creature and begin eating its flesh. The target defends itself normally but takes no other actions while eating. The target does not take extraordinary risks to satisfy this urge (it wouldn’t jump over a pit or swim through lava to reach a suitable victim). If the target can’t fulfill this urge on its next turn, the spell fails. Each round on its turn, the target can attempt a new saving throw to end the effect.', NULL, NULL, false, false),
  ('ghoul_touch', 'Ghoul Touch', 'necromancy', 'stench aspect only', 'poison', 2, 'arcane', 'bloodrager 2, sorcerer/wizard 2; Subdomain undead 2', '1 standard action', 'touch', 'living humanoid touched', NULL, NULL, '1d6+2 rounds', 'Fortitude negates', 'yes', 'Imbuing you with negative energy, this spell allows you to paralyze a single living humanoid for the duration of the spell with a successful melee touch attack.', 'cloth from a ghoul or earth from a ghoul’s lair', NULL, false, false),
  ('giant_form', 'Giant Form', 'transmutation', 'polymorph', NULL, 6, 'arcane', 'alchemist 6, sorcerer/wizard 7; Bloodline boreal 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'When you cast this spell you can assume the form of any Large humanoid creature of the giant subtype (those are: frost giant, fire giant, cyclops, ettin, hill giant, ogre, stone giant, or troll). Once you assume your new form, you gain the following abilities:', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('giant_vermin', 'Giant Vermin', 'transmutation', NULL, NULL, 4, 'divine', 'cleric/oracle 4, druid 4, shaman 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 min./level', 'none', 'yes', 'You turn a number of normal-sized centipedes, scorpions, or spiders into their giant counterparts. Only one type of vermin can be transmuted (so a single casting cannot affect both a centipede and a spider). The number of vermin which can be affected by this spell depends on your caster level, as noted on the table below.', NULL, NULL, true, false),
  ('gift_of_the_deep', 'Gift of the Deep', 'transmutation', 'polymorph', NULL, 4, 'both', 'cleric 4, sorcerer/ wizard 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one non-mutated sahuagin/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 minute/level (D)', 'Fortitude negate (harmless)', 'yes (harmless)', 'You give the targets the appearance and many of the abilities of sahuagin mutants, with effects as described below. Choose one benefit for all targets of this spell. This spell has no effect on sahuagin that are already mutants or already under the effects of gift of the deep.---', NULL, NULL, true, false),
  ('gilded_whispers', 'Gilded Whispers', 'divination', NULL, NULL, 3, 'both', 'cleric 4, sorcerer/wizard 3', '1 round', 'touch', 'a gold or platinum coin', NULL, NULL, '1 day/level (D)', 'Will negates (object)', 'yes (object)', 'Developed by priests to catch thieves and skimmers, gilded whispers later spread to other faiths and was adapted to the arcane arts. This spell is most commonly used to track bribes and illicit purchases back to their ultimate source.', '100 gp of powdered gemstones', NULL, false, true),
  ('gird_ally', 'Gird Ally', 'abjuration', NULL, NULL, 2, 'both', 'cleric 2, druid 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one summoned creature you control/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You create a magical field around summoned creatures you control that deflects attacks made against them. The targets gain a deflection bonus to their AC equal to 1 + 1 for every 6 caster levels you possess (maximum +4 deflection bonus at 18th level). A summoner can target his eidolon with this spell.', NULL, NULL, false, false),
  ('glibness', 'Glibness', 'transmutation', NULL, NULL, 3, 'arcane', 'bard 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level (D)', NULL, NULL, 'Your speech becomes fluent and more believable, causing those who hear you to believe every word you say. You gain a +20 bonus on Bluff checks made to convince another of the truth of your words. This bonus doesn’t apply to other uses of the Bluff skill, such as feinting in combat, creating a diversion to hide, or communicating a hidden message via innuendo.', NULL, NULL, false, false),
  ('glide', 'Glide', 'transmutation', NULL, NULL, 1, 'both', 'druid 2, psychic 2, ranger 1, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2; Elemental School air 2; Mystery ascetic 2', '1 standard action', 'personal', NULL, NULL, NULL, 'until landing or 1 minute/level (D)', NULL, NULL, 'You take no damage from falls (as if from feather fall). In addition, you can move up to 5 feet in any horizontal direction for every 1 foot you fall, at a speed of 60 feet per round. You cannot use this spell to actually gain height, merely coast in other directions as you fall. If subjected to a strong wind or any other effect that causes you to rise you can take advantage of it in order to increase the distance you can glide. The spell ends as soon as your feet touch the ground regardless of its remaining duration. If the spell expires while you are still in the air you fall the remaining distance as normal.', 'a leaf', NULL, true, false),
  ('glimpse_of_the_akashic', 'Glimpse of The Akashic', 'divination', NULL, NULL, 8, 'arcane', 'psychic 8', '1 full-round action', 'personal', 'you', NULL, NULL, '1 day or until discharged (see text)', NULL, NULL, 'You expand your consciousness in an attempt to tap into the perfect knowledge contained within the Akashic Record.', NULL, NULL, false, false),
  ('glimpse_of_truth', 'Glimpse of Truth', 'divination', NULL, NULL, 3, 'both', 'alchemist 5, cleric 4, druid 5, inquisitor 4, magus 5, medium 3, occultist 4, psychic 4, shaman 4, sorcerer/wizard 5, spiritualist 5, witch 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'This spell functions like true seeing, except as noted above.', 'a tourmaline costing 50 gp', NULL, false, true),
  ('glimpse_the_hidden', 'Glimpse the Hidden', 'divination', NULL, NULL, 3, 'both', 'alchemist 3, inquisitor 3, sorcerer/wizard 3, summoner/unchained summoner 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions as see invisibility, except as noted here. This spell cannot be made permanent.', 'a pinch of magnesium and platinum', NULL, false, false),
  ('glitterdust', 'Glitterdust', 'conjuration', 'creation', NULL, 2, 'arcane', 'bard 2, bloodrager 2, magus 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2; Elemental School earth 2, metal 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'creatures and objects within 10-ft.-radius spread', NULL, '1 round/level', 'Will negates (blinding only)', 'no', 'A cloud of golden particles covers everyone and everything in the area, causing creatures to become blinded and visibly outlining invisible things for the duration of the spell. All within the area are covered by the dust, which cannot be removed and continues to sparkle until it fades. Each round at the end of their turn blinded creatures may attempt new saving throws to end the blindness effect.', 'ground mica', NULL, false, false),
  ('globe_of_invulnerability', 'Globe of Invulnerability', 'abjuration', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6', '1 standard action', '10 ft.', NULL, '10-ft.-radius spherical emanation, centered on you', NULL, '1 round/level (D)', 'none', 'no', 'This spell functions like lesser globe of invulnerability, except that it also excludes 4th-level spells and spell-like effects.', 'a glass or crystal bead', NULL, false, false),
  ('globe_of_tranquil_water', 'Globe of Tranquil Water', 'abjuration', NULL, NULL, 4, 'both', 'cleric 4, druid 4, shaman 4, sorcerer/wizard 5, witch 4', '1 standard action', '20 ft.', NULL, '20-ft.-radius emanation, centered on you', NULL, '1 minute/level (D)', 'none', 'no', 'Upon casting this spell, a rippling bubble of calm water extends outward from you to a radius of 20 feet and remains centered on you when you move. The bubble blocks all natural and magical precipitation such as rain, snow, and hail (including spells such as ice storm). This bubble also pushes out any fog or mist within the area, though it does not affect temperature and can’t block natural or magical lightning.', 'a glass globe', NULL, true, false),
  ('gloomblind_bolts', 'Gloomblind Bolts', 'conjuration', 'creation', 'shadow', 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one or more bolts of energy', 'instantaneous', 'Reflex negates; see text', 'yes', 'You create one or more bolts of negative energy infused with shadow pulled from the Shadow Plane. You can fire one bolt, plus one for every four levels beyond 5th (to a maximum of three bolts at 13th level) at the same or different targets, but all bolts must be aimed at targets within 30 feet of each other and require a ranged touch attack to hit. Each bolt deals 4d6 points of damage to a living creature or heals 4d6 points of damage to an undead creature. Furthermore, the bolt’s energy spreads over the skin of creature, possibly blinding it for a short time. Any creature struck by a bolt must succeed at a Reflex saving throw or become blinded for 1 round.', NULL, NULL, false, false),
  ('glue_seal', 'Glue Seal', 'conjuration', 'creation', NULL, 1, 'arcane', 'bard 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one object or one 5-ft. square', NULL, NULL, '1 minute/level (D)', 'see text', 'no', 'You cover a solid surface with a layer of sticky glue. Anyone in the area when the spell is cast must attempt a Reflex save. Those who fail become entangled, but can break free by succeeding at a combat maneuver check or an Escape Artist check as a standard action against the DC of this spell. The area of the spell is considered difficult terrain. A creature moving through the glue must succeed at a combat maneuver check or an Escape Artist check as part of its move action (DC = the spell’s DC). Creatures that fail lose their movement and become entangled in the first square they enter.', NULL, NULL, false, false),
  ('glyph_of_warding', 'Glyph of Warding', 'abjuration', NULL, NULL, 3, 'divine', 'cleric/oracle 3, inquisitor 3, witch 3; Domain rune 3; Subdomain home 3; Mystery streets 3', '10 minutes', 'touch', 'or', 'object touched or up to 5 sq. ft./level', NULL, 'permanent until discharged (D)', 'see text', 'no (object) and yes; see text', 'This powerful inscription harms those who enter, pass, or open the warded area or object. A glyph of warding can guard a bridge or passage, ward a portal, trap a chest or box, and so on.', 'powdered diamond worth 200 gp', NULL, false, true),
  ('golden_guise', 'Golden Guise', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one object weighing no more than 5 lbs./level', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes', 'You cause an object to briefly transform into gold. Affected items gain the properties of gold until the spell expires. Weapons reduce their hardness by half and gain the fragile quality, while piercing and slashing weapons take a –2 penalty on damage rolls (minimum 1 damage). This spell increases the affected item’s armor check penalty by 2 and decreases its armor or shield bonus by 2. Gold armor has hardness 5.', '10 gold pieces', NULL, false, false),
  ('good_hope', 'Good Hope', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'bard 3; Subdomain revelry 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'This spell instills powerful hope in the subjects. Each affected creature gains a +2 morale bonus on saving throws, attack rolls, ability checks, skill checks, and weapon damage rolls.', NULL, NULL, false, false),
  ('goodberry', 'Goodberry', 'transmutation', NULL, NULL, 1, 'divine', 'druid 1, shaman 1; Subdomain seasons 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 day/level', 'none', 'yes', 'Casting goodberry makes 2d4 freshly picked berries magical. You (as well as any other druid of 3rd or higher level) can immediately discern which berries are affected. Each transmuted berry provides nourishment as if it were a normal meal for a Medium creature. The berry also cures 1 point of damage when eaten, subject to a maximum of 8 points of such curing in any 24-hour period.', NULL, NULL, true, false),
  ('grace', 'Grace', 'abjuration', NULL, NULL, 1, 'divine', 'cleric/oracle 2, paladin 1', '1 swift action', 'personal', NULL, NULL, NULL, 'see text', NULL, NULL, 'Until the end of your turn, your movement does not provoke attacks of opportunity.', NULL, NULL, false, false),
  ('grand_destiny', 'Grand Destiny', 'enchantment', 'compulsion', 'mind-affecting', 4, 'arcane', 'alchemist 5, bard 4, medium 4, mesmerist 5, sorcerer/wizard 5, summoner 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one willing creature', '10 minutes/level or until discharged', 'none (harmless)', 'yes (harmless)', 'You inspire the target with the power to seize a grand destiny. The target gains a +4 competence bonus that it can choose to apply before rolling any attack roll, caster level check, saving throw, or skill check. The spell ends once the bonus has been applied to two rolls. At 12th level and 15th level, the bonus can be applied an additional time before the spell is discharged. A subject can be under the effect of only one grand destiny spell at a time.', NULL, NULL, false, false),
  ('grappling_scarf', 'Grappling Scarf', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, inquisitor 1, occultist 1, skald 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', 'none', 'no', 'A scarf you are wearing frays at the end into hook-like shapes and can extend to incredible lengths. Although your scarf retains its weight, its frayed ends function as a grappling hook that can be thrown with a range increment of 20 feet. Your scarf elongates to 100 feet the first time it is thrown during the spell duration.', NULL, 'scarf', false, false),
  ('grasp', 'Grasp', 'divination', NULL, NULL, 0, 'both', 'arcanist 0, bard 0, cleric/oracle 0, druid 0, hunter 0, magus 0, psychic 0, skald 0, sorcerer/wizard 0, warpriest 0, witch 0', '1 immediate action', 'personal', 'you', NULL, NULL, 'instantaneous', 'none', 'no', 'You can cast this spell as an immediate action when you fail a Climb check and would fall. You can immediately attempt another Climb check as a free action at a –2 penalty. Each successive use of this spell in a particular situation increases the penalty by 2. If successful, you don’t fall, but you don’t progress at climbing.', NULL, NULL, false, false),
  ('grasping_corpse', 'Grasping Corpse', 'necromancy', NULL, 'evil', 1, 'both', 'antipaladin 1, cleric 1, occultist 1, shaman 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one corpse', NULL, NULL, 'instantaneous', 'none', 'no', 'You can cause one nearby corpse to animate for a brief moment.', 'pinch of powdered onyx worth 1 gp', NULL, false, true),
  ('grasping_depths', 'Grasping Depths', 'necromancy', 'haunted', 'emotion, fear, mind-affecting', 5, 'both', 'cleric 5, inquisitor 6, shaman 6, spiritualist 5, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, 'see text', 'Will partial; see text', 'yes', 'You call upon the restless souls of those who died at sea. This spell can be cast only on an area of deep water. When a creature enters the area, the haunt manifests, automatically grabbing the creature and dragging it under the water on initiative count 10. Each round, the haunt deals 1d6 points of nonlethal damage as it drags its victim down 10 feet; a successful DC 15 Swim check reduces the descent to 5 feet and negates the nonlethal damage.', 'a vial of sea water', NULL, true, false),
  ('grasping_hand', 'Grasping Hand', 'evocation', NULL, 'force', 7, 'arcane', 'sorcerer/wizard 7; Domain strength 7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as interposing hand, except that it can also grapple one opponent you select. The grasping hand gets one grapple attack per round. This attack does not provoke an attack of opportunity. Its CMB and CMD for grapple checks use your caster level in place of its base attack bonus, with a +10 bonus for its Strength (31) score and a +1 bonus for being Large (its Dexterity is 10, granting no bonus on the Combat Maneuver Defense). The hand holds but does not harm creatures that it grapples. Directing the spell to a new target is a move action. The grasping hand can instead be directed to bull rush a target, using the same bonuses outlined above, or it can be directed to interpose itself, as interposing hand does.', NULL, NULL, false, false),
  ('grasping_tentacles', 'Grasping Tentacles', 'conjuration', 'creation', NULL, 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3, summoner 3, witch 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as black tentacles, except the tentacles blindly grasp at the targets’ eyes and ears, and tug at their hair, clothes, and equipment. Instead of grapple attempts, the tentacles attempt dirty trick combat maneuver checks (CMB = your caster level + 4 [the tentacles’ Strength bonus] + 1 [the tentacles’ size bonus]). Roll on the following table to determine the effect of a successful dirty trick combat maneuver check.', NULL, NULL, false, false),
  ('grasping_vine', 'Grasping Vine', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, druid 2, occultist 2, ranger 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You cause a long, thin vine to sprout from your body—typically from the center of your chest or from the palm of an outstretched hand. As a standard action, you can direct the end of the vine to move to any square within 20 feet of you and perform one of the following tasks: deliver a touch spell that you cast after the vine has grown, pick up an unattended object weighing 20 pounds or less, give a held object to another creature, attempt to disable a trap or lock using your Disable Device modifier with a –2 penalty, or perform any other task that the GM deems reasonable. the vine does not threaten squares and cannot make attacks of opportunity, nor can it wield weapons.', NULL, NULL, false, false),
  ('grave_words', 'Grave Words', 'necromancy', NULL, 'language-dependent', 0, 'arcane', 'medium 0, occultist 0, psychic 0, spiritualist 0', '1 minute', 'touch', 'one dead creature', NULL, NULL, '1 round', NULL, NULL, 'With this spell and a touch, you can force a corpse talk to you, but you can’t ask it specific questions or communicate with it at all. The corpse will start babbling for 1 round, spitting out random sentences. There is a 10% chance this information is of some use to the caster, but it is difficult to distinguish whether the information is useful (the GM makes the percentile roll in secret).', NULL, NULL, false, false),
  ('gravel_vortex', 'Gravel Vortex', 'conjuration', 'creation', 'earth', 4, 'both', 'arcanist 4, druid 4, hunter 4, sorcerer/wizard 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cylinder (20-ft. radius, 40 ft. high)', NULL, '1 round/level (D)', 'none', 'yes', 'You create a hail of tiny pieces of rock and dust that batter and scrape against all things in the area, dealing 5d6 points of bludgeoning damage. This damage is dealt only once, on the round the spell is cast. For the remaining duration of the spell, fine dust rains down in the area. Creatures other than stone giants inside this area take a –4 penalty on Perception skill checks, and the entire area is treated as difficult terrain. At the end of the spell’s duration, the gravel and dust disappear, leaving no trace of their presence.', 'handful of pebbles', NULL, false, false),
  ('gravity_bow', 'Gravity Bow', 'transmutation', NULL, NULL, 1, 'both', 'ranger 1, sorcerer/wizard 1; Elemental School metal 1, void 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Gravity bow significantly increases the weight and density of arrows or bolts fired from your bow or crossbow the instant before they strike their target and then return them to normal a few moments later. Any arrow fired from a bow or crossbow you are carrying when the spell is cast deals damage as if one size larger than it actually is. For instance, an arrow fired from a Medium longbow normally deals 1d8 points of damage, but it would instead deal 2d6 points of damage if fired from a gravity bow (see table on this page for associated increase/decrease in damage due to size change). Only you can benefit from this spell. If anyone else uses your bow to make an attack the arrows deal damage as normal for their size.', NULL, NULL, false, false),
  ('gravity_sphere', 'Gravity Sphere', 'transmutation', NULL, NULL, 5, 'both', 'druid 6, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '30-ft.-radius sphere of altered gravity', '1 round/level (D)', 'none (see text)', 'no', 'You affect the local gravity field in a 30-foot-radius sphere around the spell’s designated point of origin. Creatures in the affected area can be weighed down by high gravity, lightened by low gravity, or left to float in an area with no gravity, depending on the effect you choose for your gravity sphere.', 'a marble', NULL, false, false),
  ('gravity_well', 'Gravity Well', 'transmutation', NULL, NULL, 5, 'both', 'druid 6, sorcerer/wizard 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You bring into being a localized region of increased gravity that crushes a creature to the ground.', 'a small lead weight', NULL, false, false),
  ('grease', 'Grease', 'conjuration', 'creation', NULL, 1, 'arcane', 'bard 1, magus 1, sorcerer/wizard 1, summoner/unchained summoner 1; Elemental School earth 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one object or 10-ft. square', NULL, NULL, '1 min./level (D)', 'see text', 'no', 'A grease spell covers a solid surface with a layer of slippery grease. Any creature in the area when the spell is cast must make a successful Reflex save or fall. A creature can walk within or through the area of grease at half normal speed with a DC 10 Acrobatics check. Failure means it can’t move that round (and must then make a Reflex save or fall), while failure by 5 or more means it falls (see the Acrobatics skill for details). Creatures that do not move on their turn do not need to make this check and are not considered flat-footed.', 'butter', NULL, false, false),
  ('green_caress', 'Green Caress', 'transmutation', NULL, NULL, 4, 'both', 'druid 6, ranger 4, shaman 6, witch 6', '1 standard action', 'touch', 'one living creature', NULL, NULL, '7 days (see text)', 'Fortitude partial (see text)', 'yes', 'You cause the target to transform into a plant over time. You must succeed at a melee touch attack to infect the target. If the target succeeds at its Fortitude saving throw, it takes 1d4 points of ability damage to each physical ability score (Strength, Dexterity, and Constitution) and the spell ends. If the target fails its saving throw, it takes 1d4 points of ability damage to each physical ability score immediately and continues to take 1d4 points of ability damage to each of its physical ability scores every day, until the spell expires.', 'pinch of moss or a kudzu leaf', NULL, false, false),
  ('greensight', 'Greensight', 'transmutation', NULL, NULL, 2, 'both', 'druid 2, ranger 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'no', 'The target of this spell gains the ability to see up to 60 feet through thick plant matter as though it were transparent. Greenery, leaves, and vines—even lichen, moss, and slime—offer no concealment to the recipient’s sight, though her vision still can be blocked by solid wood, such as trees or wooden structures. Undergrowth does not grant concealment to a creature against a target of the effects of greensight.', 'a leaf', NULL, false, false),
  ('grim_stalker', 'Grim Stalker', 'necromancy', 'haunted', 'death, emotion, fear, mind-affecting', 6, 'both', 'cleric 7, magus 6, shaman 7, sorcerer/ wizard 7, summoner 6, witch 7', '1 minute', 'touch', 'one object touched', NULL, NULL, '1 day/level (D)', 'Will negates (object); see text', 'yes (object)', 'You bind spirits of ill fate to an object, focusing their wrath onto the next creature that touches the object. When a creature touches the target object, it can attempt a Will save to negate the spell’s effect. Although a successful save prevents the creature from becoming haunted, the haunt still resides within the object, and targets either the next creature to touch the object or the same creature again if it still holds the object after 24 hours. The haunt remains within the object until a creature fails its save or the spell’s duration ends.', NULL, NULL, true, false),
  ('groundswell', 'Groundswell', 'transmutation', NULL, 'earth', 2, 'both', 'cleric 2, druid 2, magus 2, ranger 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'This spell allows the target to cause the ground to rise up beneath him. As a swift action, the target can cause the ground to rise 5 feet, while all adjacent squares are treated as steep slopes. The groundswell precludes flanking from creatures standing at lower elevations than the target. If the target moves after creating a groundswell, the ground returns to its normal elevation at the end of his turn; otherwise, it remains in place until the target moves or uses a swift action to return the ground to normal. A groundswell cannot increase elevation of the ground beyond 5 feet.', NULL, NULL, false, false),
  ('grove_of_respite', 'Grove of Respite', 'conjuration', 'creation', NULL, 4, 'divine', 'druid 4, ranger 4, shaman 5; Mystery nature 4', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '20-ft.-radius grove', '2 hours/level (D)', 'none', 'no', 'You conjure a sheltered grove of trees surrounding a shallow spring. The grove appears from nowhere even in the most barren, rocky soil regardless of season, but the spell must be cast outside on open ground.', 'a leaf or blade of grass and a drop of water', NULL, true, false),
  ('guardian_armor', 'Guardian Armor', 'conjuration', 'teleportation', NULL, 1, 'both', 'antipaladin 1, bloodrager 1, cleric 1, inquisitor 1, magus 1, occultist 1, paladin 1, sorcerer/wizard 1', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one willing creature; see below', NULL, NULL, 'instantaneous', 'none', 'yes', 'This spell teleports the suit of armor you are wearing off of your body and onto an ally within range; the target must be the same size and general shape as you. This armor appears on the target’s body fully formed and properly donned, granting the creature the immediate benefit of its protection. If the target of guardian armor was already wearing armor, the armor wearing it is removed from the target’s body and falls undamaged into an adjacent square.', NULL, 'armor worn', false, false),
  ('guardian_monument_lesser', 'Guardian Monument, Lesser', 'abjuration', NULL, NULL, 3, 'both', 'bard 3, inquisitor 3, magus 3, occultist 3, paladin 3, psychic 3, shaman 4, sorcerer/wizard 3, witch 3', '1 full round', 'touch', NULL, NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes', 'You touch an unattended, non-magical object to create a touchstone for humans defending the area. Such human defenders are protected by a shimmering aura as long as they are in the area.', NULL, 'an unattended, non-magical object', false, false),
  ('guardian_of_faith', 'Guardian of Faith', 'abjuration', NULL, 'see text', 4, 'divine', 'cleric 4, paladin 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one ally', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'no', 'The target gains the benefit of shield of faith and your choice of protection from chaos, evil, good, or law. As a move action, the target can transfer this spell to a touched ally, who becomes the new target of the spell.', 'parchment with a holy text written on it', NULL, false, false),
  ('guardian_wasps', 'Guardian Wasps', 'conjuration', 'summoning', NULL, 3, 'both', 'druid 3, psychic 3, ranger 3, sorcerer/wizard 3', '10 minutes; see text', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'swarm of wasps that builds a nest; see text', '1 day/level', 'none', 'no', 'You summon a wasp swarm that builds a 10-foot-by-10-foot nest in the place you designate—typically under the eaves of a house, amid the rafters of a tavern, or in another obscured place. The wasp swarm takes the spell’s casting time to build its nest; if the swarm is disrupted in any way (such as by being attacked) before you finish casting this spell, the wasps disappear and the spell fizzles.', 'a glob of spiced honey', NULL, false, false),
  ('guarding_knowledge', 'Guarding Knowledge', 'abjuration', NULL, NULL, 2, 'both', 'alchemist 3, arcanist 3, bard 3, cleric/oracle 3, inquisitor 2, investigator 3, occultist 3, psychic 3, skald 3, sorcerer/wizard 3, warpriest 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Upon casting this spell, choose a specific variety of monster (red dragon rather than dragon) and one of its special attacks that you have successfully identified with a Knowledge check or otherwise researched, such as a cockatrice’s petrification ability or a spider swarm’s poison.', 'see text', NULL, true, false),
  ('guards_and_wards', 'Guards and Wards', 'abjuration', NULL, NULL, 6, 'arcane', 'sorcerer/wizard 6, witch 6; Subdomain greed 6, home 7, wards 6', '30 minutes', 'anywhere within the area to be warded', NULL, 'up to 200 sq. ft./level (S)', NULL, '2 hours/level (D)', 'see text', 'see text', 'This powerful spell is primarily used to defend a stronghold or fortress by creating a number of magical wards and effects. The ward protects 200 square feet per caster level. The warded area can be as much as 20 feet high, and shaped as you desire. You can ward several stories of a stronghold by dividing the area among them; you must be somewhere within the area to be warded to cast the spell. The spell creates the following magical effects within the warded area.', 'burning incense, a small measure of brimstone and oil, a knotted string, and a small amount of blood', 'a small silver rod', false, false),
  ('guidance', 'Guidance', 'divination', NULL, NULL, 0, 'both', 'cleric/oracle 0, druid 0, inquisitor 0, summoner/unchained summoner 0, witch 0; Elemental School void 0', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute or until discharged', 'Will negates (harmless)', 'yes', 'This spell imbues the subject with a touch of divine guidance.', NULL, NULL, false, false),
  ('guiding_star', 'Guiding Star', 'divination', NULL, NULL, 2, 'both', 'cleric/oracle 3, psychic 3, ranger 2, shaman 2, witch 3', '1 minute', 'personal', NULL, NULL, NULL, '1 day/level (D)', NULL, NULL, 'You form a bond with your surroundings when you cast this spell. For the remaining duration of the spell you can always, as a standard action, determine your approximate distance from that area as well as the direction you must travel in order to reach it. You cannot determine the location of the area if you are on a different plane. The area counts as “very familiar” for the purposes of teleport or similar spells. You can only attune yourself to one location at a time. If you cast the spell at another spot you lose the ability to locate your original area.', 'a spool of thread or string', NULL, false, false),
  ('gullibility', 'Gullibility', 'enchantment', 'charm', 'mind-affecting', 3, 'both', 'antipaladin 3, bard 3, inquisitor 3, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./level)', 'one creature', NULL, NULL, '10 minutes/level (D)', 'Will negates', 'yes', 'You befuddle the target’s mind, making it more willing to believe even the most outlandish tales. The target takes a –10 penalty on Sense Motive checks for the spell’s duration. In addition, creatures that attempt to lie to or deceive the target gain a +10 bonus on their Bluff checks, as if the target wanted to believe them and was drunk or impaired simultaneously.', NULL, NULL, false, false),
  ('gust_of_wind', 'Gust of Wind', 'evocation', NULL, 'air', 2, 'both', 'bloodrager 2, druid 2, magus 2, sorcerer/wizard 2; Subdomain catastrophe 2; Elemental School air 2; Mystery wind 2', '1 standard action', '60 ft.', NULL, NULL, 'line-shaped gust of severe wind emanating out from you to the extreme of the range', '1 round', 'Fortitude negates', 'yes', 'This spell creates a severe blast of air (approximately 50 mph) that originates from you, affecting all creatures in its path. All flying creatures in this area take a -4 penalty on Fly skill checks. Tiny or smaller flying creatures must make a DC 25 Fly skill check or be blown back 2d6 x 10 feet and take 2d6 points of damage. Small or smaller flying creatures must make a DC 20 Fly skill check to move against the force of the wind.', NULL, NULL, false, false),
  ('gusting_sphere', 'Gusting Sphere', 'evocation', NULL, 'air', 2, 'both', 'bloodrager 2, druid 2, magus 2, sorcerer/wizard 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '5-ft.-diameter sphere of air', '1 round/level', 'Fort negates (object) or Reflex negates; see text', 'yes', 'A swirling ball of wind rolls in whichever direction you point, hurling those it strikes with great force. The sphere is treated in all ways as an area of severe wind, applying a –4 penalty on ranged weapon attacks that pass through it. The sphere moves 30 feet per round. As part of this movement, it can ascend or jump up to 30 feet to strike a target. If it enters a space containing a Medium or smaller creature, it stops moving for that round and generates a sharp thrust of wind to bull rush the creature. The sphere’s CMB for bull rush combat maneuvers uses your caster level in place of its base attack bonus, with a +2 bonus for its Strength score (14). Whether or not the bull rush is successful, the creature takes 1d6 points of nonlethal bludgeoning damage from the attack. If the bull rush fails, the creature is still subject to the severe winds from the sphere as long as they remain in the same square as it. A gusting sphere rolls over objects or barriers that are less than 4 feet tall.', NULL, NULL, false, false),
  ('hag_s_seasoning', 'Hag’s Seasoning', 'transmutation', NULL, 'curse', 2, 'both', 'antipaladin 2, bloodrager 2, druid 3, shaman 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent (D)', 'none', 'yes', 'You render the affected creature supernaturally delicious, making it the preferred target for animalistic monsters, as well as biting insects, stray animals, and vermin. A creature that makes a successful bite attack against or otherwise ingests a portion of the victim (such as with drain blood or swallow whole) gains a number of temporary hit points equal to half your caster level. These temporary hit points last for 1 hour. A creature cannot gain temporary hit points from this spell more than once per day, no matter how many times it bites your target or how many different cursed targets it bites.', 'a handful of spices', NULL, false, false),
  ('hairline_fractures', 'Hairline Fractures', 'transmutation', NULL, 'earth', 1, 'both', 'cleric/oracle 1, druid 1, shaman 1, witch 1', '1 standard action', 'touch', '5-foot-square section of stone or a creature with the earth subtype', NULL, NULL, '1 round/level', 'Fort negates (object)', 'yes (object)', 'With a single touch, you create temporary hairline fractures in a piece of stone or a creature with the earth subtype. If you cast this spell on a section of stone, you reduce its hardness to 5 and its hit points to 10/inch of thickness. If you cast this spell on a creature with the earth subtype, that creature takes a –2 penalty to AC for the spell’s duration. Make whole reverses this spell’s effect.', 'a broken twig', NULL, false, false),
  ('half_blood_extraction', 'Half-Blood Extraction', 'transmutation', NULL, NULL, 5, 'both', 'alchemist 5, cleric 5, druid 5, sorcerer/wizard 5, witch 5', '1 hour', 'touch', 'willing half-orc touched', NULL, NULL, 'instantaneous', 'none', 'no', 'You transform the target half-orc into a full-blooded orc. The target loses all of its half-orc racial traits and gains the orc racial traits.', 'oils and poisons worth 3,000 gp', NULL, true, true),
  ('halfling_vengeance', 'Halfling Vengeance', 'divination', NULL, NULL, 1, 'divine', 'antipaladin 1, cleric 2, inquisitor 2', '1 standard action', 'touch', 'one Small or smaller creature touched', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'You grant the touched target the ability to ascertain the weaknesses of foes. The target deals an additional 1d6 points of precision damage on successful attacks with daggers or slings against foes within 30 feet, as long as the attacked foe is denied its Dexterity bonus to Armor Class or is flanked by the target. This additional damage increases by 1d6 for every 4 caster levels you have beyond 3rd, to a maximum of 5d6 at 19th level. This bonus damage is precision damage and stacks with other sources of precision damage, such as sneak attack. This bonus damage is not multiplied on a critical hit.', NULL, NULL, false, false),
  ('hallow', 'Hallow', 'evocation', NULL, 'good', 5, 'divine', 'cleric/oracle 5, druid 5, inquisitor 5', '24 hours', 'touch', NULL, '40-ft. radius emanating from the touched point', NULL, 'instantaneous', 'see text', 'see text', 'Hallow makes a particular site, building, or structure a holy site. This has four major effects.', 'herbs, oils, and incense worth at least 1,000 gp, plus 1,000 gp per level of the spell to be included in the hallowed area', NULL, true, true),
  ('hallucinatory_decor', 'Hallucinatory Decor', 'illusion', 'glamer', NULL, 3, 'arcane', 'bard 3, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 minute', 'medium (100 ft. + 10 ft./level)', NULL, 'one 10-ft. cube/level (S)', NULL, '1 hour/level (D)', 'Will disbelief (if interacted with)', 'no', 'You transform the decor of a courtyard, structure, or other edifice to meet your highest standards and personal tastes.', NULL, NULL, false, false),
  ('hallucinatory_terrain', 'Hallucinatory Terrain', 'illusion', 'glamer', NULL, 4, 'arcane', 'bard 4, sorcerer/wizard 4; Elemental School wood 4', '10 minutes', 'long (400 ft. + 40 ft./level)', NULL, 'one 30-ft. cube/level (S)', NULL, '2 hours/level (D)', 'Will disbelief (if interacted with)', 'no', 'You make natural terrain look, sound, and smell like some other sort of natural terrain. Structures, equipment, and creatures within the area are not hidden or changed in appearance.', 'a stone, a twig, and a green leaf', NULL, false, false),
  ('hallucinogenic_smoke', 'Hallucinogenic Smoke', 'conjuration', NULL, 'poison', 4, 'both', 'cleric 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '3 rounds/level or until discharged; see text', 'Fortitude partial', 'yes', 'Dark gray smoke seeps from your eyes, ears, and mouth for the spell’s duration, though the smoke doesn’t significantly hamper your vision. Upon casting the spell, you may immediately exhale the smoke in a 30-foot cone or do so in a later round as a standard action, ending the spell. Each living creature caught within the cone must succeed at a Fortitude save or be nauseated for 1 round per caster level as it is wracked with waves of nausea and disorienting visions. If it succeeds at its Fortitude save, the creature is instead sickened for 1d4 rounds.', 'tobacco leaves, ingested', NULL, false, false),
  ('halt_undead', 'Halt Undead', 'necromancy', NULL, NULL, 3, 'both', 'inquisitor 3, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level', 'Will negates (see text)', 'yes', 'This spell renders as many as three undead creatures immobile. A non-intelligent undead creature gets no saving throw; an intelligent undead creature does. If the spell is successful, it renders the undead creature immobile for the duration of the spell (similar to the effect of hold person on a living creature). The effect is broken if the halted creatures are attacked or take damage.', 'a pinch of sulfur and powdered garlic', NULL, false, false),
  ('hammer_of_mending', 'Hammer of Mending', 'transmutation', NULL, NULL, 5, 'both', 'cleric/oracle 6, sorcerer/wizard 5, summoner 5', '1 standard action', NULL, NULL, '30-ft.-radius burst centered on you', NULL, 'instantaneous', 'Fort negates (harmless)', 'yes (harmless)', 'Upon striking a piece of solid ground with the spell’s focus or a holy symbol, you let out a wave of energy that repairs items within its burst.', NULL, NULL, true, true),
  ('handy_grapnel', 'Handy Grapnel', 'transmutation', NULL, NULL, 1, 'both', 'inquisitor 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'touch', 'one ropelike object, length up to 50 ft. + 5 ft./level', NULL, NULL, '1 minute/level (D)', 'Fort negates (object)', 'no', 'You cause the target rope to shrink and reshape itself into an arrow, bolt, or similar piece of ammunition, which you can shoot at any Medium or larger object. With a successful attack roll against an AC equal to 5 plus the hardness of the target object, the handy grapnel strikes and embeds itself in that object with the strength of an iron grappling hook.', 'an arrowhead', NULL, false, false),
  ('hardening', 'Hardening', 'transmutation', NULL, NULL, 6, 'arcane', 'artifice 7, sorcerer/wizard 6', '1 standard action', 'touch', 'one item of a volume no greater than 10 cu. ft./level', NULL, NULL, 'permanent', 'none', 'yes (object)', 'This spell increases the hardness of materials by 1 point per 2 caster levels. The hardening spell does not in any way affect resistance to other forms of transformation.', NULL, NULL, false, false),
  ('harm', 'Harm', 'necromancy', NULL, NULL, 6, 'divine', 'cleric/oracle 6, inquisitor 6, shaman 7, witch 7; Domain destruction 6; Subdomain decay 6', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will half; see text', 'yes', 'Harm charges a subject with negative energy that deals 10 points of damage per caster level (to a maximum of 150 points at 15th level). If the creature successfully saves, harm deals half this amount. Harm cannot reduce the target’s hit points to less than 1.', NULL, NULL, false, false),
  ('harmless_form', 'Harmless Form', 'transmutation', 'polymorph', NULL, 2, 'both', 'druid 2, ranger 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one willing animal companion, familiar, or spirit animal', NULL, NULL, '8 hours (D)', 'Fort negates (harmless)', 'yes (harmless)', 'You transform the target into a harmless animal of the same approximate body type. The form assumed must be one considered unobtrusive by local communities, such as a cat, a dog, a hunting hawk, a horse, or a rat. This transformation can reduce the target by up to two size categories, but cannot make an animal smaller than Tiny. It cannot increase the size of the target or give it new natural attacks or new forms of movement. The spell otherwise functions as beast shape II.', NULL, NULL, false, false),
  ('harrowing', 'Harrowing', 'divination', NULL, NULL, 3, 'both', 'bard 3, shaman 3, sorcerer/wizard 3, witch 3; Bloodline harrow 3', '10 minutes', 'touch', 'one creature', NULL, NULL, '1 day/level or until fulfilled', NULL, NULL, 'You use a Harrow deck to tell a fortune for yourself or someone else. If you cast harrowing on another creature, you must remain adjacent to the target for the duration of the casting time. A harrowing must describe one set of events or course of action (for example, “hunting down the pirate king,” or “traveling to Viperwall to search for a magic sword”) that the target of the spell intends to undertake at some point during the spell’s duration. If you have access to a Harrow deck, draw nine cards when this spell is cast. If you do not have a Harrow deck, you can simulate the draws by rolling a d6 and a d10 for each of the nine cards.', NULL, 'a Harrow deck', false, false),
  ('harvest_knowledge', 'Harvest Knowledge', 'divination', NULL, 'mind-affecting', 4, 'both', 'alchemist 4, antipaladin 4, bard 4, inquisitor 4, mesmerist 4, psychic 4, sorcerer/wizard 4, witch 4', '1 standard action', 'touch (see text)', 'one creature or object; see text', NULL, NULL, 'concentration, up to 1 minute/level', 'Will negates; see text', 'no', 'You touch a creature and temporarily absorb its knowledge for yourself. If the target fails its saving throw, you can sort through its lore and memories. You can retrieve one answer to a specific question per minute, as through sifting through the creature’s surface thoughts with detect thoughts. Alternatively, you can tap into the target’s learned experiences and attempt one Knowledge check in a skill in which the target has at least 1 rank, using the target’s total skill modifier. Each Knowledge check requires 1 minute and allows the target another Will save to resist the effect. If the target successfully resists, the spell does not end, but you are unable to attempt another Knowledge check for that skill using this spell. You can also use this spell against targets trapped in magic items or spells that hold their bodies or souls, such as an iron flask or the spell trap the soul, by touching the associated receptacle.', 'a piece of lodestone', NULL, false, false),
  ('harvest_season', 'Harvest Season', 'abjuration', NULL, NULL, 2, 'divine', 'druid 2, shaman 2', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one plant', NULL, NULL, 'instantaneous; see text', 'none', 'no', 'You cause an explosive burst of growth in a single plant, causing it to grow through a cycle of flower, fruit, or grain production as appropriate. If the plant is not one that normally produces food fit for humanoid consumption, it produces edible flowers under the effect of this spell. The plant produces enough food to nourish one Medium creature per caster level. Food harvested through this spell rots if not eaten within 24 hours. This spell nourishes, fertilizes, and pollinates the plant, and doesn’t harm the plant in any way. This spell has no effect on plant creatures.', NULL, NULL, false, false),
  ('haste', 'Haste', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 3, bard 3, bloodrager 3, magus 3, medium 2, occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, summoner 2, unchained summoner 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'The transmuted creatures move and act more quickly than normal. This extra speed has several effects.', 'a shaving of licorice root', NULL, false, false),
  ('hasten_judgment', 'Hasten Judgment', 'necromancy', 'curse', NULL, 4, 'both', 'antipaladin 4, cleric 5, druid 5, inquisitor 4, sorcerer/wizard 6, spiritualist 4, witch 5', '1 standard action', 'touch', 'one living or corporeal undead creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'This potent curse weighs upon the target’s soul, hastening a living creature’s journey to Purgatory upon death or weakening an undead creature’s animating force. A living creature that dies during the spell’s duration cannot be affected by breath of life or similar effects, and the period during which attempts to restore the target to life can succeed is reduced to 1 hour/level (for raise dead), 1 day/level (for resurrection), or 10 days/level (for true resurrection). Reincarnate and similar effects work normally on a creature killed under this spell’s effects.', '2 silver pieces', NULL, false, false),
  ('haunted_fey_aspect', 'Haunted Fey Aspect', 'illusion', 'glamer', NULL, 0, 'arcane', 'bard 0, psychic 0, sorcerer/wizard 0', '1 standard action', 'Personal', 'You', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You surround yourself with disturbing illusions, making you look and sound like a bizarre, insane fey creature. You gain DR 1/cold iron against a single opponent until the end of the spell, or until you take damage.', NULL, NULL, false, false),
  ('haunting_choir', 'Haunting Choir', 'necromancy', NULL, 'mind-affecting, pain', 3, 'arcane', 'bard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft.-radius emanation', NULL, 'concentration + 2 rounds', 'Will negates', 'yes', 'You create a spectral choir and conduct its tortured, ghostly moans, deluding listeners into believing they are suffering the torments of the dead. The transparent singers occupy a 10-foot cube, but they are intangible and do not interfere with creatures in any physical way, nor can they be attacked. Creatures within 30 feet of the choir experience wracking pain that causes them to take a –2 penalty on attack rolls, skill checks, and ability checks. Individuals who exit the area of effect take these penalties for an additional 2 rounds before the delusion wears off.', NULL, NULL, false, false),
  ('haunting_mists', 'Haunting Mists', 'illusion', 'figment', 'fear, shadow', 2, 'arcane', 'bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2; Elemental School void 2', '1 standard action', '20 ft.', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 minute/level (D)', 'Will partial (see text)', 'no', 'An illusion of misty vapor inhabited by shadowy shapes arises around you. It is stationary. The illusory mist obscures all sight, including darkvision, beyond 5 feet. A creature 5 feet away has concealment (attacks have a 20% miss chance). Creatures farther away have total concealment (50% miss chance, and the attacker cannot use sight to locate the target). All creatures within the mist must save or take 1d2 points of Wisdom damage and gain the shaken condition. The shaken condition lasts as long as the creature remains in the mist.', NULL, NULL, false, false),
  ('haunting_reminder', 'Haunting Reminder', 'enchantment', NULL, 'fear, mind-affecting', 1, 'both', 'antipaladin 1, bard 2, inquisitor 2, mesmerist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '12 hours + 2 hours/level or until triggered, then 1 day/level', 'Will negates', 'yes', 'As part of casting this spell, you can attempt a single Intimidate check to make the target act friendly to you. If you succeed, the target assists you normally, but it remains fearful of your retribution even after its attitude shifts to unfriendly. If the creature reports your coercion to authorities, attacks you, or otherwise acts in a purposeful way that threatens you or your objectives (at the GM’s discretion), the spell triggers, inflicting the creature with the unshakable certainty that you will find and punish it. This imposes the shaken condition on the creature for 1 day per caster level; during this time, the creature takes a -2 penalty on saving throws against spells you cast with the fear descriptor.', NULL, NULL, false, false),
  ('haze_of_dreams', 'Haze of Dreams', 'enchantment', 'charm', 'emotion, mind-affecting', 1, 'both', 'bard 1, cleric/oracle 1, inquisitor 1, paladin 1, shaman 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You fill an enemy’s head with waking dreams, a reminder of the pleasures, delights, and terrors to be found in the dream world. While in this strange dream state, the target moves at half its normal speed (round down to the next 5-foot increment), which affects the creature’s jumping distance as normal for decreased speed.', 'pinch of sand', NULL, false, false),
  ('heal', 'Heal', 'conjuration', 'healing', NULL, 6, 'both', 'alchemist 6, cleric/oracle 6, druid 7, inquisitor 6, shaman 7, witch 7; Domain healing 6; Mystery life 6', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'Heal enables you to channel positive energy into a creature to wipe away injury and afflictions. It immediately ends any and all of the following adverse conditions affecting the target: ability damage, blinded, confused, dazed, dazzled, deafened, diseased, exhausted, fatigued, feebleminded, insanity, nauseated, poisoned, sickened, and stunned. It also cures 10 hit points of damage per level of the caster, to a maximum of 150 points at 15th level.', NULL, NULL, false, false),
  ('heal_mount', 'Heal Mount', 'conjuration', 'healing', NULL, 3, 'divine', 'paladin 3', '1 standard action', 'touch', 'your mount touched', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions like heal, but it affects only the paladin’s special mount (typically a horse).', NULL, NULL, false, false),
  ('healing_flames', 'Healing Flames', 'conjuration', 'healing', 'fire, good', 4, 'divine', 'cleric/oracle 4, inquisitor 4, paladin 4, warpriest 4', '1 standard action', 'Area 10-ft.-radius burst, centered on you', NULL, '10-ft.-radius burst, centered on you', NULL, 'instantaneous', 'Reflex half; see text', 'yes', 'You unleash a blast of holy flames that washes over all creatures in the area in a glorious display of divine power. This deals damage to evil creatures and heals good creatures in the area. The amount of damage dealt and the number of hit points restored in each case is 1d8 points per 2 caster levels (maximum 5d8).', NULL, NULL, true, false),
  ('healing_leak', 'Healing Leak', 'necromancy', NULL, NULL, 2, 'both', 'antipaladin 2, cleric 3, paladin 2, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'Whenever the target is affected by a spell or effect that heals hit point damage through the use of positive or negative energy, it regains only half the number of hit points it normally would recover. If the target employs a spell or effect that heals itself or other creatures through the use of positive or negative energy, the target must succeed at a concentration check (DC = this spell’s save DC) or the effect restores only half of the normal number of hit points. Other forms of healing (such as from the Heal skill) are not affected by this spell.', 'a piece of muslin', NULL, true, false),
  ('healing_thief', 'Healing Thief', 'necromancy Level mesmerist 1, occultist 3, psychic 3, sorcerer/wizard 3, witch 3', NULL, NULL, 9, 'arcane', NULL, '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level or until discharged', 'none', 'yes', 'With this spell you can steal the healing of the target creature. You must succeed at a melee touch attack to strike the target. If you do, until the effect ends, whenever your target is subject to a healing spell or a supernatural effect that heals hit points, the target only receives half the healing (rounded down) and you receive the other half (also rounded down). You must remain within 25 feet (plus 5 feet per two caster levels) of the target to gain this benefit. If you move outside that range, the spell is discharged. Once you steal 5 hit points per your caster level (maximum 50 hit points) of healing from this spell’s effect, the spell is discharged.', 'a bit of sponge, damp with tears', NULL, false, false),
  ('healing_token', 'Healing Token', 'conjuration', 'healing', NULL, 2, 'divine', 'cleric/oracle 2, druid 2, hunter 2, inquisitor 2, paladin 2, ranger 2, shaman 2, warpriest 2', '1 standard action', 'touch', 'one touched holy symbol per 3 caster levels', NULL, NULL, '10 minutes/level', 'Will negates (object)', 'yes (object)', 'You imbue one touched holy symbol per 3 caster levels with a connection to your own divine power, turning the touched holy symbols into tokens of healing. Each of the targeted holy symbols can represent any deity regardless of the deity’s actual alignment.', NULL, NULL, true, false),
  ('healing_warmth', 'Healing Warmth', 'abjuration', NULL, NULL, 4, 'both', 'alchemist 4, cleric 4, druid 4, inquisitor 4, psychic 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell grants you temporary immunity to fire damage as protection from energy. As a standard action, you may sacrifice 12 points of remaining energy absorption from the spell to heal a touched creature of 1d8 points of damage. Healing a creature provokes an attack of opportunity. When the spell has absorbed 12 points of fire damage per caster level (to a maximum of 120 points at 10th level), it is discharged.', NULL, NULL, false, false),
  ('heart_of_the_mammoth', 'Heart of the Mammoth', 'transmutation', NULL, NULL, 8, 'both', 'cleric 8, druid 8, sorcerer/wizard 8, witch 8', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'The target creature becomes stronger, hardier, and imbued with the courage of the greatest megafauna of the tundra.', NULL, 'a fetish of mammoth hair soaked in dragon’s blood', false, false),
  ('heart_of_the_metal', 'Heart of The Metal', 'transmutation', NULL, 'earth', 3, 'arcane', 'magus 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level (see text)', 'none', 'no', 'You lend the nature of adamantine, cold iron, or silver depending on which component you used, to the targeted weapons, with the following effects:', 'a chunk of adamantine worth 100 gp, or a chunk of cold iron or silver worth 20 gp', NULL, false, true),
  ('heat_metal', 'Heat Metal', 'transmutation', NULL, 'fire', 2, 'divine', 'druid 2, occultist 2, psychic 2; Domain sun 2; Subdomain metal 2; Elemental School metal 3; Mystery metal 2, volcano 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'metal equipment of one creature per two levels, no two of which can be more than 30 ft. apart; or 25 lbs. of metal/level, all of which must be within a 30-ft. circle', NULL, NULL, '7 rounds', 'Will negates (object)', 'yes (object)', 'Heat metal causes metal objects to become red-hot. Unattended, non-magical metal gets no saving throw. Magical metal is allowed a saving throw against the spell. An item in a creature’s possession uses the creature’s saving throw bonus unless its own is higher.', NULL, NULL, true, false),
  ('heatstroke', 'Heatstroke', 'evocation', NULL, 'fire', 3, 'both', 'druid 3, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'ray', '1 minute/level', 'Fortitude partial, see text', 'yes', 'A wavering red ray projects from your finger. You must succeed on a ranged touch attack with the ray to hit your target. The ray inflicts 1d4 points of nonlethal damage, causing the target to suffer from heatstroke as its body temperature dramatically increases. Except as noted above, this spell otherwise functions as ray of exhaustion. Characters wearing heavy clothing or armor of any sort take a –4 penalty on their saves.', 'a drop of sweat', NULL, false, false),
  ('heavy_water', 'Heavy Water', 'transmutation', NULL, 'water', 4, 'divine', 'cleric 4, druid 4, ranger 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'cylinder of water (5-ft. radius/level, 30 ft. deep)', NULL, '1 minute/level (D)', 'none (see text)', 'no', 'You cause a volume of water to become heavier than normal.', NULL, NULL, true, false),
  ('heckle', 'Heckle', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'arcane', 'bard 2, bloodrager 2, magus 3, mesmerist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', '1 creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You badger and nitpick the subject of your spell until its mood sours. The target’s attitude shifts one category toward hostile regarding you and everyone within 30 feet of the target at the time the spell is cast. The target also takes a –2 penalty on attack rolls, on saving throws, and on ability and skill checks that rely on Intelligence, Wisdom, or Charisma.', 'a tomato', NULL, false, false),
  ('hedging_weapons', 'Hedging Weapons', 'abjuration', NULL, 'force', 1, 'divine', 'antipaladin 1, cleric 1, inquisitor 1, paladin 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'A weapon made from divine force appears and floats near you.', NULL, NULL, true, false),
  ('heightened_awareness', 'Heightened Awareness', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, druid 1, inquisitor 1, psychic 1, ranger 1, shaman 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'You enter a heightened state of awareness that allows you to notice more about your surroundings and recall information effortlessly. You gain a +2 competence bonus on Perception checks and on all Knowledge checks that you are trained in.', 'a coffee bean', NULL, true, false),
  ('heightened_reflexes', 'Heightened Reflexes', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2', '1 standard action', '30 ft.', NULL, 'allies within a 30-ft.-radius burst centered on you', NULL, '1 minute/level or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'You grant each of your allies within the area a +10 competence bonus on a single Reflex saving throw. Each ally must decide whether to use the bonus before making the roll to which it applies. When an ally uses the bonus, the spell ends for that individual.', NULL, NULL, false, false),
  ('hellfire_ray', 'Hellfire Ray', 'evocation', NULL, 'evil', 6, 'both', 'cleric 6, magus 6, sorcerer/wizard 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels);', NULL, NULL, 'ray', 'instantaneous', 'none (see text)', 'yes', 'A blast of hellfire blazes from your hands. You can fire one ray, plus one additional ray for every 4 caster levels beyond 11th (to a maximum of three rays at 19th level). Each ray requires a ranged touch attack to hit and deals 1d6 points of damage per caster level (maximum 15d6). Half the damage is fire damage, but the other half results directly from unholy power and is therefore not subject to being reduced by fire resistance. The rays can be fired at the same target or at different targets, but all rays must be fired simultaneously and aimed at targets within 30 feet of each other.', NULL, NULL, true, false),
  ('hellmouth_lash', 'Hellmouth Lash', 'transmutation', NULL, 'acid, electricity, or fire', 4, 'arcane', 'bloodrager 4, sorcerer/wizard 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon casting this spell, your tongue transforms into an energy whip weapon that can deal acid, electricity, or fire damage. You choose what type of energy damage the spell deals when you cast it. You attack with your tongue as if it were a whip, except you make touch attacks with it and it can harm creatures with armor or natural armor bonuses. You are considered proficient with this weapon. A successful touch attack with the tongue deals 1d8 points of energy damage per two caster levels (maximum of 5d8 points of damage at 10th level).', NULL, NULL, false, false),
  ('helping_hand', 'Helping Hand', 'evocation', NULL, NULL, 2, 'both', 'cleric/oracle 3, medium 2, psychic 3, spiritualist 3', '1 standard action', '5 miles', NULL, NULL, 'ghostly hand', '1 hour/level', 'none', 'no', 'You create the ghostly image of a hand, which you can send to find a creature within 5 miles. The hand then beckons to that creature and leads it to you if the creature is willing to follow.', NULL, NULL, true, false),
  ('hermean_potential', 'Hermean Potential', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'medium 1, mesmerist 1, psychic 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'no', 'You gift the target with the ability to perfect its actions via mental clarity. On the next attack roll, saving throw, ability check, or skill check the target attempts, it rolls twice and takes the more favorable result. For every 5 caster levels you have, the target can roll twice on an additional attack roll, saving throw, ability check, or skill check (to a maximum of 5 rolls at 20th level).', NULL, 'a gold dragon scale', false, false),
  ('hero_s_defiance', 'Hero’s Defiance', 'conjuration', NULL, 'healing', 1, 'divine', 'paladin 1', '1 immediate action', 'personal', NULL, NULL, NULL, 'instantaneous', NULL, NULL, 'The instant before you are reduced to 0 or fewer hit points, you can expend a use of your lay on hands ability to heal yourself as if you had used lay on hands, plus an additional 1d6 hit points.', NULL, NULL, false, false),
  ('heroes_feast', 'Heroes’ Feast', 'conjuration', 'creation', NULL, 6, 'both', 'bard 6, cleric/oracle 6, inquisitor 6; Domain community 6; Subdomain resolve 6, revelry 6', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'feast for one creature/level', '1 hour plus 12 hours; see text', 'none', 'no', 'You bring forth a great feast, including a magnificent table, chairs, service, and food and drink. The feast takes 1 hour to consume, and the beneficial effects do not set in until this hour is over. Every creature partaking of the feast is cured of all sickness and nausea, receives the benefits of both neutralize poison and remove disease, and gains 1d8 temporary hit points + 1 point per two caster levels (maximum +10) after imbibing the nectar-like beverage that is part of the feast. The ambrosial food grants each creature that partakes a +1 morale bonus on attack rolls and Will saves and a +4 morale bonus on saving throws against poison and fear effects for 12 hours.', NULL, NULL, true, false),
  ('heroic_finale', 'Heroic Finale', 'enchantment', 'compulsion', 'mind-affecting', 4, 'arcane', 'bard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'You must have a bardic performance in effect to cast this spell. With a flourish, you immediately end the performance, and one creature within range affected by your bardic performance can make a move action or a standard action of their choice.', NULL, NULL, false, false),
  ('heroic_fortune', 'Heroic Fortune', 'evocation', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, cleric/oracle 2, paladin 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'no', 'Note: This spell deals with hero points. See Hero Points for full details.', 'diamond dust worth 100 gp', NULL, true, true),
  ('heroic_invocation', 'Heroic Invocation', 'enchantment', 'compulsion', 'mind affecting', 9, 'arcane', 'sorcerer/wizard 9, witch 9', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', 'one or more creatures, no two of which can be more than 30 ft. apart', NULL, NULL, '10 minutes /level', 'Will negates (harmless)', 'yes (harmless)', 'Using worlds of ancient power, you bestow heroic powers on all creatures subject to this spell. They gain a +4 morale bonus on attack and damage rolls, gain 2d8+4 temporary hit points, and become immune to both fear and charm effects for the spell’s duration. At the end of the spell’s duration, the subjects become fatigued.', NULL, NULL, false, false),
  ('heroism', 'Heroism', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'alchemist 3, bard 2, bloodrager 3, inquisitor 3, medium 2, psychic 3, sorcerer/wizard 3, spiritualist 3, summoner/unchained summoner 3, witch 3; Domain charm 4; Subdomain heroism 3; Bloodline imperious 3; Mystery ancestor 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level', 'Will negates (harmless)', 'yes (harmless)', 'This spell imbues a single creature with great bravery and morale in battle. The target gains a +2 morale bonus on attack rolls, saves, and skill checks.', NULL, NULL, false, false),
  ('hex_glyph', 'Hex Glyph', 'abjuration', NULL, NULL, 3, 'divine', 'shaman 3, witch 3 Saving Throw see text; Spell Resistance no (object) and yes (see text)', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like the spell glyph version (see box at right) of glyph of warding, except you can store a hex you know (but not a major hex or a grand hex) instead of a spell. If the hex has a target, it targets the intruder. If the hex has an area or an amorphous effect, the area or effect is centered on the intruder. The triggered hex uses this spell’s caster level and DC.', NULL, NULL, false, false),
  ('hex_vulnerability', 'Hex Vulnerability', 'necromancy', NULL, 'curse', 1, 'both', 'shaman 1, witch 1', '1 standard action', 'close (25 ft. +5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'The targeted creature becomes susceptible to a repeat use of your harmful hexes, even if you could not otherwise target that creature with a particular hex for a certain time period. For example, normally after you target a creature with a charm hex, you cannot target it again for 1 day. But after casting this spell on a creature, you could try the charm hex repeatedly as long as the spell persists. The end of this spell has no effect on any active or ongoing hex on a creature. For example, if the creature failed its save against a second use of your charm hex, it remains charmed for the normal duration, even if the spell expires before the hex does.', 'a drop of your blood', NULL, false, false),
  ('hex_ward', 'Hex Ward', 'abjuration', NULL, NULL, 1, 'both', 'inquisitor 1, shaman 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'You give the target a +4 resistance bonus on saving throws against witch hexes.', NULL, NULL, false, false),
  ('hidden_blades', 'Hidden Blades', 'illusion', 'glamer', NULL, 2, 'both', 'alchemist 2, antipaladin 2, bard 2, inquisitor 2, magus 2, sorcerer/wizard 2, summoner 2', '1 standard action', 'touch', 'weapon or ammunition touched; see text', NULL, NULL, '10 minutes/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You render a target weapon or up to 50 pieces of ammunition invisible, granting the wielder a +20 bonus on Sleight of Hand checks made to conceal the weapon or ammunition and a +5 circumstance bonus on Bluff checks to feint with the weapon or ammunition.', 'a shard of glass', NULL, false, false),
  ('hidden_diplomacy', 'Hidden Diplomacy', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'bard 1, cleric 1, inquisitor 1, magus 1, mesmerist 1, psychic 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instant; see text', 'Will negates', 'yes', 'As part of casting this spell, you can attempt a single Intimidate skill check to make a target act friendly toward you. If you succeed, the target assists you normally, but hidden diplomacy clouds the memory of any threats or pressure you applied. The target remembers assisting you, but can’t remember why, and its attitude toward you doesn’t worsen as a result of being intimidated.', 'a bent coin', NULL, false, false),
  ('hidden_knowledge', 'Hidden Knowledge', 'transmutation', NULL, NULL, 2, 'arcane', 'bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2', '1 round', 'personal', 'you', NULL, NULL, 'up to 1 day/level (see text)', NULL, NULL, 'This subtle but useful spell allows you to safeguard important knowledge-even from yourself. While casting this spell, you recite one piece of knowledge (up to a maximum of 50 words). Upon completion of the spell’s casting, you transfer the knowledge from your mind to your skin in the form of an intricate, runic tattoo placed anywhere you choose on your body. The knowledge disappears utterly from your mind, and you might not realize you forgot something. The magic of the spell patches over gaps in your memory with recollections from the past. Until the spell’s duration ends, the knowledge is lost to you.', 'a drop of ink', NULL, false, false),
  ('hidden_presence', 'Hidden Presence', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'bard 2, inquisitor 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'up to one creature per 3 caster levels', NULL, NULL, '1 minute/level (D)', 'Will negates', 'yes', 'You prevent the targets from having conscious awareness of your presence. You make yourself completely undetectable to the subjects by erasing all awareness of your presence from their minds. The targets can’t see, hear, smell, feel, or taste you, including with extraordinary or supernatural senses such as blindsense, blindsight, scent, or tremorsense. They can’t pinpoint your location by any means, including detect spells.', 'eye drops made with extract of poppy', NULL, false, false),
  ('hidden_speech', 'Hidden Speech', 'transmutation  Level bard 2, inquisitor 3, medium 2, mesmerist 2, psychic 2, witch 2', NULL, 'language-dependent', 9, 'arcane', NULL, '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes', 'You greatly enhance the ability of the subjects to communicate hidden messages to each other. Each target gains a +10 competence bonus on Bluff checks to send secret messages to other recipients. Others using opposed Sense Motive checks to decipher these messages receive a -5 penalty. All subjects affected by the spell must share a language to be able to pass messages.', 'a cipher written on a piece of parchment', NULL, true, false),
  ('hidden_spring', 'Hidden Spring', 'transmutation', NULL, 'water', 1, 'both', 'cleric 1, druid 1, ranger 1, shaman 1, witch 1', '1 hour', 'touch Effects a spring of fresh water', NULL, NULL, NULL, '1 hour/level', 'none', 'no', 'You spend 1 hour in quiet meditation, holding the focus component in both hands and walking around a natural area. You are simultaneously drawn to areas of natural moisture while drawing that moisture closer. As the spell’s casting time concludes, you thrust the focus component into the ground. From that point, a fresh, clean water trickles forth at a rate of 1 gallon every 10 minutes. You cannot cast this spell inside a building or in an area of worked stone, but you can cast it underground. You cannot cast this spell within 1 mile of an existing hidden spring.', NULL, 'a Y-shaped wooden rod', false, false),
  ('hide_bruises', 'Hide Bruises', 'illusion', 'glamer', NULL, 1, 'both', 'antipaladin 1, arcanist 1, bard 1, inquisitor 1, mesmerist 1, occultist 1, psychic 1, skald 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one creature touched', NULL, NULL, '10 minutes/level (D)', 'none and Will disbelief (see text)', 'yes (harmless)', 'The target’s wounds to seem to disappear. A creature attempting a Heal check to tell the severity of the target’s injuries takes a –10 penalty on that check. A creature that physically touches the glamered areas can attempt a Will save to recognize it as an illusion.', 'drop of blood', NULL, false, false),
  ('hide_campsite', 'Hide Campsite', 'illusion', 'glamer', NULL, 2, 'divine', 'druid 3, ranger 2', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 20-ft. cube', NULL, '2 hours/level (D)', 'Will disbelief (if interacted with)', 'no', 'You make the area around a campsite appear to be a thicket of untouched and forbidding foliage, or some other unwelcoming feature matching the surrounding terrain. Creatures outside the area cannot sense any activity going on inside the area- they cannot smell campfires or cooking food, they cannot hear conversation, loud noises, or spells being cast, and they cannot even feel heat or a rush of wind coming from the area. Those inside the area can see out normally. Once a creature steps into the area of the spell, it can see everything in and around the area normally.', 'a sprig of mistletoe, and a vial of quicksilver', NULL, false, false),
  ('hide_from_animals', 'Hide from Animals', 'abjuration', NULL, NULL, 1, 'divine', 'druid 1, ranger 1, shaman 1', '1 standard action', 'touch', NULL, NULL, NULL, '10 min./level (D)', 'Will negates (harmless)', 'yes', 'Animals cannot sense the warded creatures. Even extraordinary or supernatural sensory capabilities, such as blindsense, blindsight, scent, and tremorsense, cannot detect or locate warded creatures. Animals simply act as though the warded creatures are not there. If a warded character touches an animal or attacks any creature, even with a spell, the spell ends for all recipients.', NULL, NULL, true, false),
  ('hide_from_undead', 'Hide from Undead', 'abjuration', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1', '1 standard action', 'touch', NULL, NULL, NULL, '10 min./level (D)', 'Will negates (harmless); see text', 'yes', 'Undead cannot see, hear, or smell creatures warded by this spell. Even extraordinary or supernatural sensory capabilities, such as blindsense, blindsight, scent, and tremorsense, cannot detect or locate warded creatures. Non-intelligent undead creatures (such as skeletons or zombies) are automatically affected and act as though the warded creatures are not there. An intelligent undead creature gets a single Will saving throw. If it fails, the subject can’t see any of the warded creatures. If it has reason to believe unseen opponents are present, however, it can attempt to find or strike them. If a warded creature attempts to channel positive energy, turn or command undead, touches an undead creature, or attacks any creature (even with a spell), the spell ends for all recipients.', NULL, NULL, true, false),
  ('hide_weapon', 'Hide Weapon', 'transmutation', NULL, NULL, 1, 'both', 'antipaladin 1, bloodrager 1, inquisitor 1, magus 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'Upon casting this spell, a light or one-handed melee weapon in your hand melds with your flesh, accompanied by a disgusting sucking sound. The weapon disappears completely inside your arm, and thereafter for the duration of the spell, you can extend and retract the weapon as a move action.', NULL, NULL, false, false),
  ('hideous_laughter', 'Hideous Laughter', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, medium 2, mesmerist 1, psychic 2, sorcerer/wizard 2; Subdomain revelry 2, whimsy 1; Bloodline fey 2; Mystery juju(PAP39/PZO9039) 2, juju(PZO9436) 2, whimsy 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature; see text', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell afflicts the subject with uncontrollable laughter. It collapses into gales of manic laughter, falling prone. The subject can take no actions while laughing, but is not considered helpless. After the spell ends, it can act normally. On the creature’s next turn, it may attempt a new saving throw to end the effect. This is a full round action that does not provoke attacks of opportunity. If this save is successful, the effect ends. If not, the creature continues laughing for the entire duration.', 'tiny fruit tarts and a feather', NULL, false, false),
  ('hobble', 'Hobble', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, bloodrager 1, inquisitor 1, magus 1, mesmerist 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level, no two of which can be more than 20 feet apart', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'This spell disrupts the method a target uses for movement. Creatures under the effects of this spell move at half their base speed (rounded down to the nearest 5-foot increment) but can still take 5-foot steps as normal. Incorporeal creatures and creatures flying with perfect maneuverability are immune to the effects of this spell. Each round, a target receives another save to end the effect.', 'a drop of glue', NULL, false, false),
  ('hobbling_bomb_admixture', 'Hobbling Bomb Admixture', 'transmutation', NULL, NULL, 4, 'arcane', 'alchemist 4', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Upon drinking an extract created with this formula, you make a significant change to your magical reserve that modifies the nature of all bombs you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can have only one admixture effect (formula with the words “bomb admixture” in its title) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and the new one becomes active.', NULL, NULL, false, false),
  ('hold_animal', 'Hold Animal', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'druid 2, mesmerist 2, psychic 2, ranger 2; Domain animal 2', NULL, NULL, 'one animal', NULL, NULL, NULL, NULL, NULL, 'This spell functions like hold person, except that it affects an animal instead of a humanoid.', NULL, NULL, false, false),
  ('hold_fey', 'Hold Fey', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'bard 2, cleric 2, inquisitor 2, sorcerer/wizard 3, witch 2', NULL, NULL, 'one fey creature', NULL, NULL, NULL, NULL, NULL, 'This spell functions as per hold person, except it affects a fey instead of a humanoid.', NULL, NULL, true, false),
  ('hold_monster', 'Hold Monster', 'enchantment', 'compulsion', 'mind-affecting', 4, 'both', 'bard 4, inquisitor 4, sorcerer/wizard 5, summoner 4, unchained summoner 5, witch 5; Domain law 6', NULL, NULL, 'one living creature', NULL, NULL, NULL, NULL, NULL, 'This spell functions like hold person, except that it affects any living creature that fails its Will save.', 'one hard metal bar or rod, which can be as small as a three-penny nail', NULL, true, false),
  ('hold_person', 'Hold Person', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'antipaladin 2, bard 2, bloodrager 3, cleric/oracle 2, inquisitor 2, shaman 2, sorcerer/wizard 3, medium 2, mesmerist 2, occultist 3, psychic 2, witch 2; Mystery godclaw 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one humanoid creature', NULL, NULL, '1 round/level (D); see text', 'Will negates; see text', 'yes', 'The subject becomes paralyzed and freezes in place. It is aware and breathes normally but cannot take any actions, even speech. Each round on its turn, the subject may attempt a new saving throw to end the effect. This is a full-round action that does not provoke attacks of opportunity. A winged creature who is paralyzed cannot flap its wings and falls. A swimmer can’t swim and may drown.', NULL, NULL, true, false),
  ('hold_portal', 'Hold Portal', 'abjuration', NULL, NULL, 1, 'arcane', 'psychic 1, sorcerer/wizard 1', '1 standard action Component V', 'medium (100 ft. + 10 ft./level)', 'one portal, up to 20 sq. ft./level', NULL, NULL, '1 min./level (D)', 'none', 'no', 'This spell magically holds shut a door, gate, window, or shutter of wood, metal, or stone. The magic affects the portal just as if it were securely closed and normally locked. A knock spell or a successful dispel magic spell can negate a hold portal spell.', NULL, NULL, false, false),
  ('hollow_blades', 'Hollow Blades', 'transmutation', NULL, NULL, 1, 'both', 'magus 2, ranger 1, shaman 3, sorcerer/wizard 3, witch 3', '1 round', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'All melee and natural attacks from the target deal damage as if the target were one size category smaller than it actually is. While the target is under the effects of this spell, weapons dropped by the target function normally for other creatures, while any melee weapons picked up by the target deal damage as if one size smaller. Ranged attacks and weapons are unaffected by this spell.', NULL, NULL, false, false),
  ('hollow_heroism', 'Hollow Heroism', 'enchantment', 'compulsion', 'mind-affecting, ruse', 3, 'both', 'bard 3, bloodrager 4, inquisitor 4, medium 3, psychic 4, sorcerer/wizard 4, spiritualist 4, summoner 4, witch 4', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions as heroism, except that you can reverse the spell by issuing a special command as a standard action if you are within medium range (100 feet + 10 feet per caster level) of the target. The target loses the bonuses and instead takes a –2 penalty on attack rolls, saving throws, and skill checks until the spell’s duration ends (no save).', NULL, NULL, false, false),
  ('holy_aura', 'Holy Aura', 'abjuration', NULL, 'good', 8, 'divine', 'cleric/oracle 8; Domain glory 8, good 8', '1 standard action', '20 ft.', NULL, NULL, NULL, '1 round/level (D)', 'see text', 'yes (harmless)', 'A brilliant divine radiance surrounds the subjects, protecting them from attacks, granting them resistance to spells cast by evil creatures, and causing evil creatures to become blinded when they strike the subjects. This abjuration has four effects.', NULL, 'a tiny reliquary worth 500 gp', false, true),
  ('holy_ice', 'Holy Ice', 'transmutation', NULL, 'cold, good, water', 5, 'divine', 'cleric/oracle 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall of ice or flying ice javelins (see text)', '1 minute/level, instantaneous, or until expended (see text)', 'Reflex negates or none (see text)', 'yes', 'This spell creates a large mass of frozen holy water that can be used for one of two effects.', 'a flask of holy water or 5 pounds of powdered silver worth 25 gp', NULL, false, true),
  ('holy_ice_weapon', 'Holy Ice Weapon', 'transmutation', NULL, 'cold, good, water', 2, 'divine', 'cleric 2, inquisitor 2', '1 standard action', '0 ft.', NULL, NULL, 'one ice weapon', '1 minute/level (D)', 'none', 'no', 'You create a masterwork weapon that has the qualities of ice and holy water. This weapon must be a simple weapon or your deity’s favored weapon. The weapon deals normal damage for a weapon of that type, plus 1 point of cold damage per caster level (maximum 10). In addition, any creature struck by the weapon is also hit by holy water, dealing 1d4 points of damage if the creature is susceptible to holy water. If the weapon leaves your hands for more than 1 round, it melts and the spell ends.', 'a flask of holy water, or 5 pounds of powdered silver worth 25 gp', NULL, false, true),
  ('holy_javelin', 'Holy Javelin', 'conjuration', 'creation', 'good', 2, 'divine', 'cleric 3, inquisitor 3, paladin 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'javelin of divine energy', '1 round + 1 round/4 levels', 'none', 'yes', 'You create a shimmering javelin of holy energy to hurl at an enemy as a ranged touched attack. The javelin deals 1d6 points of damage to an evil creature on a successful attack; it dissipates harmlessly against creatures of any other alignment. Each time a creature starts its turn while impaled by the javelin, it takes another 1d6 points of damage. For every 4 caster levels you have, the javelin remains in the creature for an additional round (to a maximum of 5 rounds at 18th level). While the creature remains impaled, it takes a –2 penalty on attack rolls and skill checks.', NULL, NULL, true, false),
  ('holy_shield', 'Holy Shield', 'abjuration', NULL, NULL, 2, 'divine', 'paladin 2', '1 standard action component V, S', 'personal', 'you', NULL, NULL, '10 minutes/level', 'none', 'no', 'You gain the ability to magically project the defense of your shield to protect another creature at a distance. As a swift action, you designate one target within 30 feet. The target gains your shield’s shield bonus and enhancement bonus to Armor Class until your next turn; you gain no benefit from the shield’s shield bonus or enhancement bonus while using this spell and cannot use any of the shield’s other properties or abilities (such as magical abilities, making a shield bash, or providing cover with a tower shield). As a swift action, you may move the protection to another target (including yourself); if you move the protection to yourself, you may use any of the shield’s properties or abilities as normal. If the shielded creature exceeds the 30-foot range, your shield’s protection automatically reverts to you. Any circumstance that would make you lose your shield bonus (such as an enemy breaking the shield, you dropping the shield, or you becoming helpless or unconscious) means the protected creature loses the shield’s benefit.', NULL, NULL, false, false),
  ('holy_smite', 'Holy Smite', 'evocation', NULL, 'good', 4, 'divine', 'cleric/oracle 4, inquisitor 4; Domain glory 4, good 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius burst', NULL, 'instantaneous (1 round); see text', 'Will partial; see text', 'yes', 'You draw down holy power to smite your enemies. Only evil and neutral creatures are harmed by the spell; good creatures are unaffected.', NULL, NULL, false, false),
  ('holy_sword', 'Holy Sword', 'evocation', NULL, 'good', 7, 'arcane', 'paladin 4; Domain glory 7', '1 standard action', 'touch', 'melee weapon touched', NULL, NULL, '1 round/level', 'none', 'no', 'This spell allows you to channel holy power into your sword, or any other melee weapon you choose. The weapon acts as a +5 holy weapon (+5 enhancement bonus on attack and damage rolls, extra 2d6 damage against evil opponents). It also emits a magic circle against evil effect (as the spell). If the magic circle ends, the sword creates a new one on your turn as a free action. The spell is automatically canceled 1 round after the weapon leaves your hand. You cannot have more than one holy sword at a time.', NULL, NULL, false, false),
  ('holy_whisper', 'Holy Whisper', 'evocation', NULL, 'good', 3, 'divine', 'paladin 3', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'Fortitude negates; see text', 'yes', 'You whisper a single word in the primordial language of good that is anathema to the minions of evil and strengthens the resolve of good creatures. Evil creatures within the burst must make a Fortitude Saving Throw or become sickened for 1 round/ level. Evil outsiders with the evil subtype, evil-aligned dragons, and undead in the burst also take 2d8 points of damage if they fail their saves. Good-aligned creatures in the burst gain a +2 sacred bonus on attack and damage rolls for 1 round.', NULL, NULL, false, false),
  ('holy_word', 'Holy Word', 'evocation', NULL, 'good, sonic', 7, 'divine', 'cleric/oracle 7, inquisitor 6; Domain good 7', '1 standard action', '40 ft.', NULL, 'nongood creatures in a 40-ft.-radius spread centered on you', NULL, 'instantaneous', 'Will partial', 'yes', 'Any non-good creature within the area of a holy word spell suffers the following ill effects.', NULL, NULL, false, false),
  ('homeward_bound', 'Homeward Bound', 'abjuration', NULL, NULL, 3, 'both', 'cleric 3, sorcerer/wizard 4', '1 minute', 'touch', 'one willing extraplanar creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes', 'This spell functions as dismissal, except as noted above.', NULL, NULL, false, false),
  ('honeyed_tongue', 'Honeyed Tongue', 'transmutation', NULL, NULL, 1, 'both', 'bard 2, inquisitor 2, paladin 1', '1 standard action', 'personal', NULL, NULL, NULL, '10 minutes/level', NULL, NULL, 'This spell augments your diplomacies. While under the effects of spell, you roll two dice each time you make a Diplomacy check to change a creature’s attitude, taking the highest roll.', 'a drop of honey', NULL, true, false),
  ('hoodwink', 'Hoodwink', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'arcanist 2, bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, skald 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'up to one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You befuddle the targets’ senses, preventing the targets from clearly perceiving their surroundings. Instead, hoodwinked creatures see only the roughest shapes and details and hear only muffled noises. However, targets can clearly hear verbal communication from the spell’s caster. This spell does not impart understanding of the caster’s language if the creature can’t already understand it. Other than to hear the caster speak, targets automatically fail Perception checks with DCs greater than 5, and they are too disoriented by the spell to accurately remember the path they took while under its effects.', 'small piece of black cloth', NULL, false, false),
  ('horn_of_pursuit', 'Horn of Pursuit', 'evocation', NULL, 'sonic', 1, 'both', 'bard 1, inquisitor 1, paladin 1, ranger 1', '1 standard action component S', 'personal', NULL, NULL, '3 peals of a horn', '1 round', 'none', 'no', 'You create the sound of a large hunting horn, blowing up to three notes as loud as a roaring dragon. These notes can be heard up to 2 miles away in typical outdoor conditions. You can make these sounds at any point during the spell’s duration as a free action, and each sounding can be short or long, allowing you to send very simple coded messages.', NULL, NULL, false, false),
  ('horrid_wilting', 'Horrid Wilting', 'necromancy', NULL, NULL, 8, 'both', 'sorcerer/wizard 8, shaman 8, witch 8; Domain water 8; Subdomain radiation 8; Elemental School water 8; Bloodline daemon 8; Mystery bones 8, reaper 8', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, 'instantaneous', 'Fortitude half', 'yes', 'This spell evaporates moisture from the body of each subject living creature, causing flesh to wither and crack and crumble to dust. This deals 1d6 points of damage per caster level (maximum 20d6). This spell is especially devastating to water elementals and plant creatures, which instead take 1d8 points of damage per caster level (maximum 20d8).', 'a bit of sponge', NULL, true, false),
  ('horrific_doubles', 'Horrific Doubles', 'illusion', 'figment', NULL, 3, 'arcane', 'bard 4, bloodrager 4, medium 3, mesmerist 4, psychic 4, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You create several illusory doubles of yourself, where you and each image all seem slightly off or wrong in appearance. Treat this spell as mirror image, except as noted.', NULL, NULL, false, false),
  ('horrifying_visage', 'Horrifying Visage', 'necromancy', 'haunted', 'emotion, fear, mind-affecting', 3, 'both', 'bard 3, cleric 3, inquisitor 3, magus 3, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, '1 day/level (D)', 'Will negates', 'yes', 'You channel residual feelings of terror into the minds of creatures within the area, causing those fears to manifest when confronted with a specific object. All creatures in the area must succeed at a Will save or acquire a phobia for the spell’s duration. You choose one kind of creature, object, or image within the area of the spell when it is cast that triggers the phobia. The kind of creature, object, or image that triggers the phobia must be named specifically. A creature type or subtype is not specific enough.', 'a live spider', NULL, false, false),
  ('hostile_juxtaposition', 'Hostile Juxtaposition', 'conjuration', 'teleportation', NULL, 4, 'arcane', 'sorcerer/wizard 5, summoner 4, unchained summoner 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature of your size or smaller', NULL, NULL, '1 round/level or until discharged', 'Will negates', 'yes', 'You create a dimensional link to the target creature. When attacked or the subject of a spell that deals damage to you, you can spend an immediate action to cause yourself and the target creature to teleport and switch places. The target then becomes the target of the triggering attack or spell instead of you. If you fail to teleport out of the area of an effect, that effect might still affect you. If the target creature cannot fit safely into the new space without squeezing, or you try to teleport the target into an occupied space or a space it could not normally stand within, the juxtaposition fails. Further, if the target is unconscious or dead when you attempt to switch places, the juxtaposition fails. Once you have used it to teleport once, this spell is discharged.', 'a coin', NULL, false, false),
  ('hostile_levitation', 'Hostile Levitation', 'transmutation', NULL, NULL, 2, 'arcane', 'bloodrager 3, medium 2, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You levitate the target a few inches off the ground, removing solid footing and halving the target’s speed. The target also takes a –4 penalty to CMD against bull rush, drag, and reposition attempts. A targeted creature that attacks with a melee or ranged weapon finds itself increasingly unstable; the first attack has a –1 penalty on attack rolls, the second –2, and so on, to a maximum penalty of –5. A full-round action spent stabilizing allows the creature to begin again at –1. This spell fails if cast on a flying creature.', 'a leather loop studded with lodestones', NULL, false, false),
  ('howling_agony', 'Howling Agony', 'necromancy', NULL, 'death, pain', 2, 'both', 'bloodrager 3, inquisitor 2, mesmerist 2, psychic 2, sorcerer/ wizard 3, spiritualist 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 round/level', 'Fortitude negates', 'yes', 'You send wracking pains through the targets’ bodies. Because of the pain, affected creatures take a –2 penalty to AC, attacks, melee damage rolls, and Reflex saving throws, and must succeed at a concentration check (DC equal to the DC of this spell) to cast spells. However, if an affected creature spends a move action screaming as loudly as possible, it can act without any other penalties for the remainder of its turn. “Screaming,” for the purposes of this spell, includes any vocalization of pain or its telepathic equivalent; creatures that cannot scream (such as creatures without the natural ability to communicate or vocalize) suffer the full effect of the spell.', 'a needle and a dried eyeball', NULL, false, false),
  ('human_potential', 'Human Potential', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, medium 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes', 'The target chooses one ability score and gains a +2 enhancement bonus to that ability score. The bonus confers the usual benefit to skills and abilities based on the ability enhanced, but does not affect bonus spells or skill ranks.', 'a human hair', NULL, false, false),
  ('hunger_for_flesh', 'Hunger for Flesh', 'necromancy', NULL, 'evil, mind-affecting', 3, 'both', 'antipaladin 3, cleric 4, psychic 4, shaman 4, sorcerer/wizard 4, spiritualist 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid, magical beast, or monstrous humanoid', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'Your target’s belly distends and its front teeth grow longer and sharper. The creature ravenously craves the flesh of its own kind, gaining the staggered condition as hunger pangs rack its altered body. The target gains a bite attack as a primary natural attack that deals damage appropriate for its size (1d6 if Medium, 1d4 if Small). There’s a 25% chance on each of the creature’s turns that it can’t overcome its hunger. If so, it must move directly toward the nearest corporeal creature of its type and subtype (if applicable) and make a bite attack against it. If the target lacks enough actions to attack on that turn, it moves as close to the creature as it can, but on its next turn, if the percentile dice indicate it overcomes its hunger, the target is not forced to pursue or attack further.', 'a ghoul fang', NULL, true, false),
  ('hungry_darkness', 'Hungry Darkness', 'evocation', NULL, 'darkness, force', 7, 'arcane', 'sorcerer/wizard 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '60-ft.-radius spread', NULL, '1 round/level (D)', 'none', 'yes (see text)', 'This spell creates an area of intense blackness, as deeper darkness, but filled with unseen chewing teeth and ravenous maws. Any creatures beginning its turn within the hungry darkness is gnawed and slashed by these unseen fangs of force, dealing 3d6 points of force damage and 2 points of Constitution damage per round. Once a creature leaves the cloud, it continues to take 1d6 points of bleed damage each round until it receives magical healing or enters an area of bright light. Spell Resistance can prevent damage from the hungry darkness but not against the darkness it creates.', 'a bat’s tooth', NULL, false, false),
  ('hungry_earth', 'Hungry Earth', 'transmutation', NULL, NULL, 5, 'both', 'druid 5, sorcerer/wizard 5, witch 5; Bloodline ghoul 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-foot-radius spread', NULL, '1 round/level', 'none', 'no', 'The ground attempts to pull creatures beneath its surface as if hungry for the flesh of mortals.', NULL, NULL, false, false),
  ('hungry_pit', 'Hungry Pit', 'conjuration', 'creation', NULL, 5, 'arcane', 'sorcerer/wizard 5, summoner/unchained summoner 5; Subdomain caves 5; Elemental School earth 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-by-10-ft. hole, 10 ft. deep/2 levels', '1 round + 1 round/level', 'Reflex negates; Reflex half; see text', 'no', 'This spell functions as create pit, except that the pit has the ability to squeeze and crush any creature trapped within it and has a maximum depth of 100 feet. Creatures who fall into the hole take falling damage as normal. In addition, anyone within the pit, not just those on the bottom, takes 4d6 points of bludgeoning damage each round as the pit contracts and then returns to its normal size (a successful Reflex save halves this damage). The ever-shifting walls of the pit are quite difficult to scale and have a Climb DC of 35.', NULL, 'miniature shovel costing 10 gp', false, true),
  ('hunter_s_blessing', 'Hunter’s Blessing', 'transmutation', NULL, NULL, 5, 'divine', 'cleric/oracle 5, druid 5, inquisitor 5, shaman 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'When casting this spell, you designate a type or type and subtype of creature (using the ranger’s favored enemy categories and a type of terrain (using the list of ranger’s favored terrain categories).', NULL, NULL, true, false),
  ('hunter_s_eye', 'Hunter’s Eye', 'divination', NULL, NULL, 2, 'divine', 'inquisitor 3, ranger 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 minute/level', 'none', 'yes', 'Sharpening your perceptive abilities and tuning them against obfuscating effects, hunter’s eye greatly enhances your senses against the target creature. You gain the ability to perceive the target when it is invisible or ethereal as though using the see invisibility spell, and receive a +20 competence bonus on Perception checks to locate the target.', NULL, NULL, true, false),
  ('hunter_s_friend', 'Hunter’s Friend', 'transmutation', NULL, NULL, 2, 'divine', 'druid 3, ranger 2', '1 standard action', 'touch', 'your animal companion', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'no', 'Your animal companion works in perfect harmony with your mastery of nature.', NULL, NULL, true, false),
  ('hunter_s_howl', 'Hunter’s Howl', 'necromancy', NULL, 'emotion, fear, mind-affecting', 1, 'divine', 'ranger 1', '1 standard action', '20 ft.', NULL, '20-ft.-radius burst', NULL, '1 round/level', 'Will negates', 'none', 'With a single primal howl, you strike fear in your opponents. Until the end of the spell’s duration, you treat those affected by it as if they were your favored enemy, gaining a +2 bonus on weapon attack and damage rolls against them, and a +2 bonus on Bluff, Knowledge, Perception, Sense Motive, and Survival checks against them. If an affected creature is already one of your favored enemies, it is shaken instead. This is a mind-affecting fear effect.', NULL, NULL, false, false),
  ('hunter_s_lore', 'Hunter’s Lore', 'divination', NULL, NULL, 2, 'divine', 'inquisitor 2, ranger 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'Inquisitors and rangers alike learned long ago that knowledge of an enemy grants power over that enemy. This spell was created so that almost any enemy could have its vulnerabilities known and exploited.', 'a scrap of paper torn from a book about monsters', NULL, false, false),
  ('huntmaster_s_spear', 'Huntmaster’s Spear', 'transmutation', NULL, NULL, 1, 'both', 'antipaladin 1, bloodrager 2, druid 2, hunter 1, inquisitor 2, magus 2, occultist 2, paladin 1, ranger 1, shaman 2', '10 minutes', 'touch', 'non-magical spear touched', NULL, NULL, '24 hours or until discharged', 'Will negates (harmless, object)', 'yes (harmless, object)', 'Choose one creature type (and subtype, if applicable) from the ranger’s favored enemy list. When you cast this spell, the targeted spear hums with destructive energy and functions as a +1 spear against creatures of the selected type.', 'see text', NULL, true, false),
  ('hurricane_blast', 'Hurricane Blast', 'evocation', NULL, 'air', 3, 'both', 'druid 3, sorcerer/wizard 4', '1 standard action', 'personal', 'you', '5-ft.-radius burst/2 levels (maximum 25-ft.-radius burst)', NULL, '1 round', 'Reflex negates', 'no', 'This spell creates a severe blast of air (approximately 50 mph) that originates from you, affecting all creatures in the burst.', NULL, NULL, false, false),
  ('hydraulic_push', 'Hydraulic Push', 'evocation', NULL, 'water', 1, 'both', 'bloodrager 1, druid 1, magus 1, shaman 1, sorcerer/wizard 1; Subdomain rivers 1; Bloodline aquatic 1; Elemental School water 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'none', 'yes', 'You call forth a quick blast of water that knocks over and soaks one creature or square. You can use this blast of water to make a bull rush against any one creature or object. Your CMB for this bull rush is equal to your caster level plus your Intelligence, Wisdom, or Charisma modifier, whichever is highest. This bull rush does not provoke an attack of opportunity. Hydraulic push extinguishes any normal fires on a creature, object, or in a single 5-foot square which it is targeted against. Magical fires are unaffected.', NULL, NULL, false, false),
  ('hydraulic_torrent', 'Hydraulic Torrent', 'evocation', NULL, 'water', 3, 'both', 'bloodrager 3, druid 3, magus 3, sorcerer/wizard 3; Elemental School water 3', '1 standard action', '60 ft.', NULL, '60-ft. line', NULL, 'instantaneous', 'none', 'yes', 'You call forth a powerful stream of water that batters all creatures and obstacles in its path until it strikes something it cannot push past. Against creatures and movable objects this stream acts as a bull rush. You can bull rush creatures of any size, not just those one size larger than your own. Make a combat maneuver check and apply its results to each creature within the area. Your CMB for this bull rush is equal to your caster level plus your Intelligence, Wisdom, or Charisma modifier, whichever is highest. This bull rush does not provoke an attack of opportunity.', NULL, NULL, false, false),
  ('hydrophobia', 'Hydrophobia', 'necromancy', NULL, 'emotion, fear, mind-affecting', 2, 'both', 'bard 2, cleric 3, druid 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft.-radius burst', NULL, '1 round/level', 'Will negates', 'yes', 'Targets in the area must succeed at a Will save or become deathly afraid of drowning. If the target is swimming or otherwise submerged in water, it must spend all of its efforts attempting to escape from the water. As long as an affected target remains in water, it takes 1d6 points of nonlethal damage each round as it thrashes about and swallows water. Even out of water, targets cannot imbibe potions or willingly interact with any fluids for the duration of this spell.', NULL, NULL, false, false),
  ('hymn_of_mercy', 'Hymn of Mercy', 'enchantment', 'compulsion', 'good, mind-affecting', 5, 'both', 'bard 5, cleric 5', '1 standard action', '30 ft.', NULL, '30-ft.-radius burst centered on you', NULL, '1 round/level (D)', 'Will negates', 'yes', 'This spell functions like touch of mercy, except as noted above.', NULL, NULL, false, false),
  ('hymn_of_peace', 'Hymn of Peace', 'abjuration', NULL, 'good', 6, 'both', 'bard 6, cleric 7', '1 standard action', '40 ft.', NULL, '40-ft.-radius burst centered on you', NULL, '1 round/level (D)', 'Will negates', 'yes', 'Each time a subject of this spell attempts to attack another creature or object, or otherwise perform an aggressive or damaging action toward a creature or object, it must attempt a Will save. If the save succeeds, the subject can attack normally. If the save fails, the subject cannot follow through with the attack and loses that part of its action. Creatures not taking violent actions are unaffected by this spell.', NULL, NULL, false, false),
  ('hypercognition', 'Hypercognition', 'divination', NULL, NULL, 2, 'arcane', 'alchemist 3, bard 3, medium 2, psychic 2, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'You rapidly catalog and collate all available data on a person, place, thing, or event, calling to mind scraps of memory and assembling clues in a logical and systematic order.', NULL, NULL, false, false),
  ('hypnotic_pattern', 'Hypnotic Pattern', 'illusion', 'pattern', 'mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2; Subdomain stars 2; Mystery heavens 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'colorful lights in a 10-ft.-radius spread', 'Concentration + 2 rounds', 'Will negates', 'yes', 'A twisting pattern of subtle, shifting colors weaves through the air, fascinating creatures within it. Roll 2d4 and add your caster level (maximum 10) to determine the total number of HD of creatures affected. Creatures with the fewest HD are affected first; and, among creatures with equal HD, those who are closest to the spell’s point of origin are affected first. HD that are not sufficient to affect a creature are wasted. Affected creatures become fascinated by the pattern of colors. Sightless creatures are not affected.', 'a stick of incense or a crystal rod', NULL, false, false),
  ('hypnotism', 'Hypnotism', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, 'several living creatures, no two of which may be more than 30 ft. apart', NULL, '2d4 rounds (D)', 'Will negates', 'yes', 'Your gestures and droning incantation fascinate nearby creatures, causing them to stop and stare blankly at you. In addition, you can use their rapt attention to make your suggestions and requests seem more plausible. Roll 2d4 to see how many total HD of creatures you affect. Creatures with fewer HD are affected before creatures with more HD. Only creatures that can see or hear you are affected, but they do not need to understand you to be fascinated.', NULL, NULL, false, false),
  ('ice_armor', 'Ice Armor', 'transmutation', NULL, 'cold, water', 1, 'divine', 'cleric/oracle 1, druid 1', '1 minute', '0 ft.; see text', NULL, NULL, 'a suit of armor made of ice', '1 hour/level or until destroyed', 'none', 'no', 'You create a suit of armor made of ice. While cold to the touch, it does not harm the wearer, especially if worn over normal clothing (though it can hasten the effects of exposure in cold environments). It offers the same protection as a breastplate, except it has hardness 0 and 30 hit points. If the intended wearer is immersed in water when you cast this spell, you may form the armor around the wearer (who may be you); otherwise the wearer must don the armor normally. Attacks against the wearer that create heat or fire degrade the armor, reducing its armor bonus by 1 for every 5 points of fire damage the wearer takes; when the armor’s bonus to AC reaches 0, the armor is destroyed and the spell ends. Because the ice is slightly buoyant, the wearer gains a +2 circumstance bonus on Swim checks, except when swimming downward. Druids can wear ice armor without penalty.', NULL, '5 gallons of water', false, false),
  ('ice_body', 'Ice Body', 'transmutation', NULL, 'cold', 7, 'both', 'shaman 7, sorcerer/wizard 7, witch 7; Mystery winter 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Your form transmutes into living ice, granting you several abilities. You gain the cold subtype and damage reduction 5/magic. You are immune to ability score damage, blindness, critical hits, deafness, disease, drowning, electricity, poison, stunning, and all spells or attacks that affect your physiology or respiration, because you have no physiology or respiration while this spell is in effect. You cannot drink (and thus can’t use potions) or play wind instruments.', NULL, NULL, false, false),
  ('ice_crystal_teleport', 'Ice Crystal Teleport', 'conjuration', 'teleportation', 'cold', 5, 'arcane', 'sorcerer/ wizard 6, summoner 5, unchained summoner 6, witch 6', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '1d4 rounds and instantaneous', 'Will negates', 'yes', 'This spell functions as teleport, except you use it to teleport yourself or one other creature to a safe location you specify (the target can bring along objects as long as their weight doesn’t exceed the target’s heavy load). You can only send the target to a location with which you are very familiar. The target is first trapped in ice (hardness 0, 3 hit points per inch of thickness, 1 inch thick per caster level) for 1d4 rounds, during which time it is paralyzed, aware but unable to take any physical actions, and begins to fade away as the teleportation aspect takes effect. At the end of the 1d4 rounds, the target teleports to the specified location, and the ice’s hit points drop to 0 and it quickly melts away. If the ice is destroyed before the target teleports, the spell ends and the teleport doesn’t occur.', NULL, NULL, false, false),
  ('ice_slick', 'Ice Slick', 'evocation', NULL, 'cold', 2, 'both', 'druid 2, magus 2, ranger 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '5-ft.-radius burst', NULL, 'instantaneous (see text)', 'Reflex partial (see text)', 'see text', 'You create a blast of intense cold, coating all solid surfaces in the area with a thin coating of ice.', NULL, NULL, false, false),
  ('ice_spears', 'Ice Spears', 'conjuration', NULL, 'cold', 3, 'both', 'druid 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5ft./2 levels)', NULL, NULL, '1 ice spear/4 levels', 'instantaneous', 'Reflex half and see below', 'no', 'Upon casting this spell, one or more giant spears of ice lance up out of the ground. Each stalagmite-like icicle affects a 5-foot square and tapers to a height of 10 feet. You may cause a number of ice spears equal to one spear for every four caster levels you possess to burst from the ground. A creature that occupies a square from which a spear extends (or that is within 10 feet of the ground below) takes 2d6 points of piercing damage and 2d6 points of cold damage per square—creatures that take up more than one square can be hit by multiple spears if the caster is high enough level. The explosive growth can also trip foes. When the spears erupt from the ground, they make a combat maneuver check against any targets that take damage from the spears, with a total bonus equal to your caster level plus your Intelligence, Wisdom, or Charisma modifier, whichever is highest. Each additional ice spear beyond the first that strikes a single foe grants a +10 bonus to this CMB check. If the check succeeds, the ice spears knock the foe prone. A successful Reflex save halves the damage and prevents the trip attempt.', 'a small stalagmite-shaped crystal', NULL, false, false),
  ('ice_storm', 'Ice Storm', 'evocation', NULL, 'cold', 4, 'both', 'bloodrager 4, druid 4, magus 4, shaman 4, sorcerer/wizard 4, witch 4; Domain water 5, weather 5; Elemental School water 4; Mystery apocalypse 4, winter 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cylinder (20-ft. radius, 40 ft. high)', NULL, '1 round/level (D)', 'none', 'yes', 'Great magical hailstones pound down upon casting this spell, dealing 3d6 points of bludgeoning damage and 2d6 points of cold damage to every creature in the area. This damage only occurs once, when the spell is cast. For the remaining duration of the spell, heavy snow and sleet rains down in the area. Creatures inside this area take a -4 penalty on Perception skill checks and the entire area is treated as difficult terrain. At the end of the duration, the snow and hail disappear, leaving no after-effects (other than the damage dealt).', 'dust and water', NULL, true, false),
  ('icicle_dagger', 'Icicle Dagger', 'conjuration', 'creation', 'cold', 1, 'arcane', 'bloodrager 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', '1 standard action', '0 ft.', NULL, NULL, 'one icicle', '1 minute/level', 'none', 'no', 'You create a masterwork dagger out of ice. The dagger deals 1 point of cold damage in addition to normal dagger damage. If the dagger leaves your hand for more than 1 round, it melts and the spell ends. At 6th level, the dagger functions as a +1 frost dagger. At 11th level, it gains the returning property when thrown, melting away and reforming in your hand just before your next turn.', NULL, NULL, false, false),
  ('icy_prison', 'Icy Prison', 'evocation', NULL, 'cold', 5, 'arcane', 'sorcerer/wizard 5; Mystery winter 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 minute/level; see text', 'Reflex partial', 'yes', 'You trap the target in solid ice 1 inch thick per caster level. If the creature fails its save, it is helpless, but can still breathe (the ice blocks line of effect to the target). If the target makes its save, it gains the entangled condition but can otherwise act normally. Whether or not the target saves, it takes 1 point of cold damage per caster level each round it is helpless or entangled in the ice. The ice has hardness 0 and 3 hit points per inch of thickness; if broken, the creature is freed. A creature can break the ice as a full-round action with a successful Strength check (DC 15 + your caster level).', NULL, NULL, false, false),
  ('id_insinuation_i', 'Id Insinuation I', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'psychic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'concentration + 1 round', 'Will negates', 'yes', 'By invading the mind of a creature with your psychic presence, You can isolate parts of its mind, preventing the target from functioning in a coherent manner. The target is confused as long as you concentrate on it plus 1 additional round. A successful Will save negates this effect.', NULL, NULL, false, false),
  ('identifier_s_eye', 'Identifier’s Eye', 'divination', NULL, NULL, 2, 'arcane', 'alchemist 2, bard 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '3 rounds + 1 round/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell infuses a spark of magical energy into the veins of the target, allowing it to feel the presence of magic the way one might feel the thrum of vibrations in the air. For the spell’s duration, the target gains the benefits of the spell detect magic and also gains a +5 enhancement bonus on Spellcraft checks to identify the properties and command words of magic items.', 'a wine-stained pearl', NULL, false, false),
  ('identify', 'Identify', 'divination', NULL, NULL, 1, 'arcane', 'alchemist 1, bard 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1; Domain magic 1; Bloodline arcane 1; Mystery lore 1', '1 standard action', '60 ft.', NULL, 'cone-shaped emanation', NULL, '3 rounds/level (D)', NULL, NULL, 'This spell functions as detect magic, except that it gives you a +10 enhancement bonus on Spellcraft checks made to identify the properties and command words of magic items in your possession. This spell does not allow you to identify artifacts.', 'wine stirred with an owl’s feather', NULL, false, false),
  ('ignoble_form', 'Ignoble Form', 'transmutation', 'polymorph', NULL, 2, 'both', 'alchemist 2, antipaladin 2, bard 2, druid 3, medium 2, ranger 2, sorcerer/ wizard 4, witch 4', '1 standard action', 'touch', 'one drow', NULL, NULL, '24 hours', 'Fort negates (harmless)', 'no', 'The target takes on the form of a half-elf from the surface world. Its skin, hair, and eyes change to match a specific human ethnicity. You can even change the target’s facial features or produce light facial hair or stubble. The target loses its darkvision, light blindness, and light sensitivity traits, if it normally has them. The target gains low-light vision; a +3 racial bonus on a single Craft, Knowledge, Perform, or Profession skill of its choice; and both a +4 bonus on Bluff checks and a +10 bonus on Disguise checks to pass itself off as a half-elf.', 'a half-elf ear', NULL, false, false),
  ('ill_omen', 'Ill Omen', 'enchantment', 'compulsion', 'curse, mind-affecting', 1, 'arcane', 'psychic 1,witch 1, mesmerist 1; Bloodline harrow 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level or until discharged', 'none', 'yes', 'You afflict the target with bad luck. On the next d20 roll the target makes, it must roll twice and take the less favorable result. For every five caster levels you have, the target must roll twice on an additional d20 roll (to a maximum of five rolls at 20th level).', 'hair from a black cat', NULL, false, false),
  ('illusion_of_calm', 'Illusion of Calm', 'illusion', 'figment', NULL, 1, 'arcane', 'alchemist 1, magus 1, psychic 1, sorcerer/wizard 1', '1 standard action Component V, S', 'personal', 'you', NULL, NULL, '1 minute/level', 'Will disbelieve (on hit; see below)', 'no', 'When casting this spell, you create an illusory double that takes the same space of you. That double makes it look like you are standing still, even when you are not. While under the effects of this spell, you do not provoke attacks of opportunity when you cast a spell, make a ranged attack with a thrown weapon, or move out of your first square during a move action. It does not hide ranged attacks made with any type of projectile weapon.', NULL, NULL, false, false),
  ('illusion_of_treachery', 'Illusion of Treachery', 'illusion', 'figment', NULL, 3, 'both', 'antipaladin 3, magus 4, mesmerist 3, occultist 4, psychic 4, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will disbelief', 'yes', 'You create an illusion that takes the same space as a foe and mimics its movements perfectly. Whenever you cast a spell or throw a weapon, the illusion ceases mimicking the target’s actions just long enough to make it look like the target cast the spell or threw the weapon simultaneously with you, such that witnesses who can see both you and the target can’t tell with certainty who truly cast the spell or threw the weapon. Witnesses who can see only the target see it as the only apparent source.', NULL, 'a tiny marionette', false, false),
  ('illusory_crowd', 'Illusory Crowd', 'illusion', 'figment', NULL, 1, 'both', 'bard 1, shaman 1, witch 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one 10-ft. cube of illusory people', '1 minute/level (D)', 'Will disbelief (if interacted with)', 'no', 'This spell creates an illusion of a stationary group of people milling about. They can be of any humanoid race or ethnicity you are familiar with, and they speak a language of your choice that you know. To anyone not paying close attention, their conversations sound perfectly normal but are in fact repetitive and essentially meaningless. The crowd appears to be a group of typical citizens, and cannot duplicate any specific group, guild, or military squad.', 'a shirt button', NULL, false, false),
  ('illusory_hoard', 'Illusory Hoard', 'illusion )', 'phantasm', 'mind-affecting', 4, 'arcane', 'bard 4, sorcerer/wizard 5', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell forces the target to believe that nothing in its hoard is missing or has been disturbed.', 'an item from the hoard, see below', NULL, false, false),
  ('illusory_maze', 'Illusory Maze', 'illusion', 'figment', NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius spread', NULL, '1 round/level', 'Will disbelief (if interacted with)', 'yes', 'This spell creates the illusion of a translucent, ever-changing maze of glass in the target area. Creatures in the area who believe the maze to be real cannot move more than 5 feet continuously in any one direction and can’t move diagonally, forcing them to take a circuitous route to their destination.', NULL, NULL, false, false),
  ('illusory_poison', 'Illusory Poison', 'illusion', 'phantasm', 'mind-affecting', 3, 'arcane', 'sorcerer/wizard 3', '1 standard action', 'touch', 'weapon touched', NULL, NULL, '1 minute/level or until discharged (see text)', 'Will disbelief, then Fortitude (see text); Spell resistance yes', NULL, 'You create a phantasm of an oily green phantasmal poison on the target weapon.', NULL, NULL, false, false),
  ('illusory_script', 'Illusory Script', 'illusion', 'phantasm', 'mind-affecting', 3, 'arcane', 'bard 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3', '1 minute per page', 'touch', 'one touched object weighing no more than 10 lbs.', NULL, NULL, 'one day/level (D)', 'Will negates; see text', 'yes', 'You write instructions or other information on parchment, paper, or any suitable writing material. The illusory script appears to be some form of foreign or magical writing. Only the person (or people) designated by you at the time of the casting can read the writing; it’s unintelligible to any other character.', 'lead-based ink worth 50 gp', NULL, false, true),
  ('illusory_wall', 'Illusory Wall', 'illusion', 'figment', NULL, 4, 'arcane', 'sorcerer/wizard 4; Subdomain ambush 5; Mystery streets 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'image 1 ft. by 10 ft. by 10 ft.', 'permanent', 'Will disbelief (if interacted with)', 'no', 'This spell creates the illusion of a wall, floor, ceiling, or similar surface. It appears absolutely real when viewed, but physical objects can pass through it without difficulty. When the spell is used to hide pits, traps, or normal doors, any detection abilities that do not require sight work normally. Touch or a probing search reveals the true nature of the surface, though such measures do not cause the illusion to disappear. Although the caster can see through his illusory wall, other creatures cannot, even if they succeed at their Will save (but they do learn that it is not real).', NULL, NULL, false, false),
  ('imbue_army_special_ability', 'Imbue Army Special Ability', 'evocation', NULL, NULL, 9, 'divine', 'cleric 9', '10 minutes', '1 hex', 'one army', NULL, NULL, '1 battle', 'none or Will negates (harmless)', 'yes', 'You imbue the target with an army special ability possessed by the army’s commander.', NULL, 'a silver mirror worth 100 gp', false, true),
  ('imbue_hex', 'Imbue Hex', 'evocation', NULL, NULL, 5, 'both', 'shaman 5, witch 5', '10 minutes', 'touch', 'creature touched; see text', NULL, NULL, 'permanent or until discharged', 'Will negates (harmless)', 'yes', 'You transfer a single hex you know to the target, and give that target the ability to use the hex. The transferred hex’s variable characteristics function according to your level, not the level of the recipient. Only a creature with Intelligence and Wisdom scores of at least 9 can receive this effect. To use this hex, the target must be able to speak and move freely. Once it uses the hex, the spell ends (though any effects of the hex still last for the full duration). You can transfer only a hex—not a major or grand hex—with this ability.', 'a hag’s whisker', NULL, true, false),
  ('imbue_with_addiction', 'Imbue With Addiction', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, mesmerist 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'one living creature', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'The target immediately becomes addicted to the drug used as the material component during the casting of the spell. If the target was ever addicted to the drug at any point in the past, it takes a –4 penalty on its saving throw.', 'a dose of an addictive drug or substance', NULL, false, false),
  ('imbue_with_aura', 'Imbue with Aura', 'transmutation', NULL, NULL, 2, 'divine', 'cleric/oracle 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (see text)', 'yes', 'You infuse another creature with your divine aura, causing the target to radiate an aura identical to your own clerical aura. The target’s actual alignment is not changed, but spells like detect evil or detect good detect only the aura, not the creature’s actual alignment. For the duration of this spell, effects influenced by the target’s alignment function according to the imposed aura, not the creature’s actual aura. When the spell ends, the target’s aura returns to normal, and alignment-affecting magic affects it according to its actual alignment.', NULL, NULL, true, false),
  ('imbue_with_elemental_might', 'Imbue with Elemental Might', 'evocation', NULL, 'see text', 2, 'both', 'bloodrager 2, cleric 2, magus 2, shaman 2, sorcerer/wizard 2', '1 standard action', NULL, NULL, NULL, NULL, '24 hours or until discharged (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions like imbue with spell ability, except you transfer the use of your elemental assault ability to the target. The target must have an Intelligence score of at least 5 to use the ability. The imbued elemental assault functions exactly like yours, except the ability’s duration is based on the target’s level or Hit Dice. Once you cast this spell, you cannot use your elemental assault ability until the duration of the spell is over.', NULL, NULL, false, false),
  ('imbue_with_flight', 'Imbue with Flight', 'transmutation', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4', '1 standard action', 'touch', 'object touched', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You grant a touched Large or smaller object the ability to fly at a speed of 40 feet with average maneuverability. It can ascend at half speed and descend at double speed. The targeted object flies as you direct it, using your Fly skill for any difficult maneuvers. You must be within close range (25 ft. + 5 ft./2 levels) of the object to direct it, and moving it requires a move action. If not directed, the object hovers in place (no Fly check required). The maximum weight of the object and anything carried by it is 500 pounds per caster level (maximum 10,000 pounds).', 'handful of down', NULL, false, false),
  ('imbue_with_spell_ability', 'Imbue with Spell Ability', 'evocation', NULL, NULL, 4, 'divine', 'cleric/oracle 4, shaman 4; Domain community 4, magic 4', '10 minutes', 'touch', 'creature touched; see text', NULL, NULL, 'permanent until discharged (D)', 'Will negates (harmless)', 'yes (harmless)', 'You transfer some of your currently prepared spells, and the ability to cast them, to another creature. Only a creature with an Intelligence score of at least 5 and a Wisdom score of at least 9 can receive this boon. Only cleric spells from the schools of abjuration, divination, and conjuration (healing) can be transferred. The number and level of spells that the subject can be granted depends on its Hit Dice; even multiple castings of imbue with spell ability can’t exceed this limit.', NULL, NULL, true, false),
  ('impart_mind', 'Impart Mind', 'transmutation', NULL, NULL, 5, 'both', 'cleric 6, magus 5, sorcerer/wizard 6', '2 rounds', 'touch', 'permanent nonintelligent magic item touched', NULL, NULL, '1 hour/level', 'none', 'no', 'This spell grants the target magic item temporary intelligence by siphoning off a tiny portion of your own mind to infuse the object. Only permanent magic items may be enhanced by this spell—one-use items and charged items cannot be affected by impart mind. Intelligent magic items cannot be affected by impart mind.', 'diamond dust worth at least 1,000 gp', NULL, false, true),
  ('impede_speech', 'Impede Speech', 'necromancy', NULL, NULL, 2, 'arcane', 'bard 2, sorcerer/wizard 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 min./level', 'Will negates', 'yes', 'This minor curse interferes with the target’s ability to speak. On a failed save, the target has diﬃculty stringing words together. Only with great concentration can he communicate intelligibly. Speaking in combat becomes a move-equivalent action rather than a free action. If the target attempts to cast a spell with a verbal component, he has a 50% chance of making an error and losing the spell. Even if he can successfully cast a spell, doing so takes 1 round if the spell’s normal casting time is less than 1 round. If the spell’s casting time is usually 1 round or longer, its casting time doubles (up until the end of impede speech). Impede speech cannot be dispelled, but break enchantment, limited wish, miracle, remove curse, or wish can end it prematurely.', NULL, NULL, false, false),
  ('impenetrable_veil', 'Impenetrable Veil', 'abjuration', NULL, NULL, 6, 'arcane', 'bard 6, mesmerist 6, psychic 9, sorcerer/wizard 9, spiritualist 6, witch 9', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'You enchant the target so it is nearly impossible to detect by both magical and mundane means, granting it the following benefits. The target gains a bonus on Stealth checks equal to half your caster level, and can use Stealth to hide from all creatures attempting to perceive it, even when it lacks concealment or cover. It can attempt a Stealth check to avoid detection from creatures using blindsight, blindsense, or any ability that functions as either (such as lifesense or tremorsense). Furthermore, the target leaves no trail and cannot be tracked unless it chooses to leave a trail. If a creature attempts to discern the target’s presence or location using divination magic (including magic items with a divination aura such as a crystal ball), that creature must succeed at a caster level check with a DC equal to the target’s Stealth bonus to discern any information about the target, and on a failed check cannot do so for the spell’s duration.', 'dust from the Dimension of Dreams worth 1,250 gp', NULL, false, true),
  ('implant_false_reading', 'Implant False Reading', 'illusion', 'glamer', NULL, 2, 'arcane', 'mesmerist 2, occultist 2, psychic 2', '1 minute', 'touch', 'object touched', NULL, NULL, '1 day/level', 'none; see text', 'no', 'You implant a false psychometric reading into an object, imbuing the item with misleading information that might be learned from the object reading spell or through the psychometry occult skill unlock. This information might fool enemies, create a false history, or pass on secret messages through objects to psychically attuned allies. You can implant any information you wish that could be implanted by the charge object spell, as well as up to one piece of information per 3 levels that could be attained using psychometry or the object reading spell. You can detail this information in any way you see fit, either making up a previous owner and circumstances involving the object from whole cloth, or attempting to emulate the biographical information and fictional accounts of a specific individual’s experience with the object.', NULL, NULL, false, false),
  ('implant_urge', 'Implant Urge', 'enchantment', 'compulsion', 'mind-affecting', 1, 'arcane', 'bard 1, medium 1, mesmerist 1, sorcerer/wizard 1, spiritualist 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 hour/level', 'Will partial', 'yes', 'You make the target unconsciously desire a goal you define when you cast this spell. The DC of any Diplomacy check to ask the target to act in a way that it believes will lead it toward that goal decreases by 5. The target takes a –2 penalty on saving throws against mind-affecting effects that compel it to act in a way that it believes will lead it toward that goal.', NULL, NULL, false, false),
  ('implanted_projection', 'Implanted Projection', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'mesmerist 3, psychic 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'Yes', 'This spell functions as telempathic projection, except its mood-altering effects remain dormant in the target’s mind. Upon casting this spell, the caster designates a command word or phrase, of which the target retains no memory. The next creature to speak the command word or phrase to the target triggers the implanted telempathic projection, treating the speaker as the original spellcaster.', NULL, NULL, false, false),
  ('implosion', 'Implosion', 'evocation', NULL, NULL, 9, 'arcane', 'cleric/oracle 9; Domain destruction, erosion 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one corporeal creature/round', NULL, NULL, 'concentration (up to 1 round per 2 levels)', 'Fortitude negates', 'yes', 'This spell causes a destructive resonance in a corporeal creature’s body. Each round you concentrate (including the first), you can cause one creature to collapse in on itself, inflicting 10 points of damage per caster level. If you break concentration, the spell immediately ends, though any implosions that have already happened remain in effect. You can target a particular creature only once with each casting of the spell. Implosion has no effect on creatures in gaseous form or on incorporeal creatures.', NULL, NULL, false, false),
  ('impossible_angles', 'Impossible Angles', 'illusion', 'figment', NULL, 3, 'arcane', 'medium 3, mesmerist 4, occultist 4, psychic 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'contiguous area up to one 5-foot cube/caster level (S)', NULL, '1 minute/level', 'Will negates', 'yes', 'You cause the surrounding area to appear to distort. The angles and corners of the area subtly twist and contort, creating unnatural and impossible shapes. Any creature entering the area must succeed at a Will save or become disoriented. Disoriented characters treat the area as difficult terrain and are sickened. In addition, whenever a disoriented creature uses an action to move (including taking a 5-foot step if it can do so in difficult terrain), roll 1d8 to see which direction it moves, in a similar manner to determining where a splash weapon lands on a miss. On a 1, the creature moves in its intended direction, with 2 through 8 rotating around the creature’s starting square in a clockwise direction. Only the creature’s first 5 feet of movement each round are affected in this way—it can move normally for any remaining movement, either from the same action or from later actions, as the creature acclimatizes to the distortion. An affected creature can attempt a new Will save each round to end the disoriented effect. A creature that leaves the area and re-enters must attempt the saving throw again, even if it succeeded at its initial save.', 'a melted prism', NULL, false, false),
  ('imprisonment', 'Imprisonment', 'abjuration', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Mystery godclaw 9, outer rifts 9', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will negates; see text', 'yes', 'When you cast imprisonment and touch a creature, it is entombed in a state of suspended animation (see the temporal stasis spell) in a small sphere far beneath the surface of the ground. The subject remains there unless a freedom spell is cast at the locale where the imprisonment took place. Magical search by a crystal ball, a locate object spell, or some other similar divination does not reveal the fact that a creature is imprisoned, but discern location does. A wish or miracle spell will not free the recipient, but will reveal where it is entombed. If you know the target’s name and some facts about its life, the target takes a -4 penalty on its save.', NULL, NULL, false, false),
  ('improve_trap', 'Improve Trap', 'transmutation', NULL, NULL, 2, 'both', 'antipaladin 2, druid 3, inquisitor 2, ranger 2, sorcerer/wizard 3, witch 3; Subdomain trap 3', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one trap', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'When this spell is cast upon a trap, it improves one specific element of the trap chosen at the time of casting. The caster can improve the trap in any of the following ways (each one raises the trap’s CR by +1).', NULL, NULL, false, false),
  ('incendiary_cloud', 'Incendiary Cloud', 'conjuration', 'creation', 'fire', 8, 'arcane', 'sorcerer/wizard 8, summoner 6; Domain fire 8; Elemental School fire 8; Mystery apocalypse 8, flame 8', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', NULL, '1 round/level (D)', NULL, NULL, 'An incendiary cloud spell creates a cloud of roiling smoke shot through with white-hot embers. The smoke obscures all sight as a fog cloud does. In addition, the white-hot embers within the cloud deal 6d6 points of fire damage to everything within the cloud on your turn each round. All targets can make Reflex saves each round to take half damage.', NULL, NULL, false, false),
  ('incendiary_runes', 'Incendiary Runes', 'abjuration', NULL, 'fire', 1, 'arcane', 'occultist 1, sorcerer/wizard 1 Saving Throw Reflex partial; Spell Resistance yes', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as explosive runes, except it creates a small surge of flames rather than an explosion of force. The runes automatically deal 1d6 points of fire damage to any creatures and objects in adjacent squares, and those creatures and objects catch fire unless they succeed at Reflex saves.', NULL, NULL, false, false),
  ('incessant_buzzing', 'Incessant Buzzing', 'illusion', 'figment', NULL, 1, 'both', 'antipaladin 1, bard 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'medium (100 ft. +10 ft./level)', NULL, NULL, '10-ft.-diameter sphere', '1 round/level', 'Will negates', 'yes', 'You summon an illusory swarm of angry wasps that fills a 10-foot-diameter sphere. You can summon it so that it shares an area with other creatures, and you can move it up to 40 feet each round as a move action. Creatures caught inside the swarm’s area of effect cannot use skills that require patience or concentration. Additionally, spellcasters within the area must succeed at a caster level check (DC = 20′ + level of spell to be cast) in order to cast spells. On a failed caster level check, the spell is lost. While the buzzing is unpleasant, it is not so loud as to drown out other noises or make communication difficult.', 'insect wing', NULL, true, false),
  ('incorporeal_chains', 'Incorporeal Chains', 'evocation', NULL, 'force', 5, 'arcane', 'psychic 6, spiritualist 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one incorporeal creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, 'concentration', 'none', 'yes', 'You summon ghostly chains to bind incorporeal creatures. The chains’ CMB is equal to your caster level + your Intelligence modifier. Roll only once for the entire spell effect and apply the result to all targeted incorporeal creatures.', NULL, NULL, false, false),
  ('infernal_challenger', 'Infernal Challenger', 'conjuration  ; see text', 'calling', 'lawful', 3, 'both', 'cleric 3, sorcerer/wizard 3, summoner 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one called bearded devil and testing ground; see text', '1 minute/level', 'none', 'no', 'This spell summons a bearded devil, causing it to appear where you designate. The area within a 50-foot radius of where the devil appears is ringed with a smoldering, red glow. This area is the testing ground. To successfully cast this spell, no creature other than the devil’s challenger (see below) can be within this area while the spell is being cast.', NULL, NULL, true, false),
  ('infernal_healing', 'Infernal Healing', 'conjuration', 'healing', 'evil', 1, 'both', 'cleric/oracle 1, magus 1, sorcerer/wizard 1, summoner 1, witch 1', '1 round', 'touch', 'creature touched', NULL, NULL, '1 minute', 'Will negates (harmless)', 'yes (harmless)', 'You anoint a wounded creature with devil’s blood or unholy water, giving it fast healing 1. This ability cannot repair damage caused by silver weapons, good-aligned weapons, or spells or effects with the good descriptor. The target detects as an evil creature for the duration of the spell and can sense the evil of the magic, though this has no long-term effect on the target’s alignment.', '1 drop of devil blood or 1 dose of unholy water', NULL, false, false),
  ('inflict_critical_wounds', 'Inflict Critical Wounds', 'necromancy', NULL, NULL, 4, 'divine', 'cleric/oracle 4, inquisitor 4, shaman 4, witch 5; Domain destruction 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like inflict light wounds, except that you deal 4d8 points of damage + 1 point per caster level (maximum +20).', NULL, NULL, false, false),
  ('inflict_light_wounds', 'Inflict Light Wounds', 'necromancy', NULL, NULL, 1, 'both', 'antipaladin 1, cleric/oracle 1, inquisitor 1, shaman 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will half', 'yes', 'When laying your hand upon a creature, you channel negative energy that deals 1d8 points of damage + 1 point per caster level (maximum +5).', NULL, NULL, false, false),
  ('inflict_moderate_wounds', 'Inflict Moderate Wounds', 'necromancy', NULL, NULL, 2, 'both', 'antipaladin 3, cleric/oracle 2, inquisitor 2, shaman 2, witch 2', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like inflict light wounds, except that you deal 2d8 points of damage + 1 point per caster level (maximum +10).', NULL, NULL, false, false),
  ('inflict_pain', 'Inflict Pain', 'enchantment', NULL, 'mind-affecting, pain', 2, 'both', 'antipaladin 2, inquisitor 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 3, spiritualist 2, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will partial; see text', 'yes', 'You telepathically wrack the target’s mind and body with agonizing pain that imposes a –4 penalty on attack rolls, skill checks, and ability checks. A successful Will save reduces the duration to 1 round.', NULL, NULL, false, false),
  ('inflict_serious_wounds', 'Inflict Serious Wounds', 'necromancy', NULL, NULL, 3, 'both', 'antipaladin 4, cleric/oracle 3, inquisitor 3, shaman 3, witch 4', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like inflict light wounds, except that you deal 3d8 points of damage + 1 point per caster level (maximum +15).', NULL, NULL, false, false),
  ('influence_wild_magic', 'Influence Wild Magic', 'abjuration', NULL, NULL, 2, 'both', 'bard 2, cleric 2, druid 2, medium 2, mesmerist 2, ranger 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', 'personal', 'you', NULL, '20-foot-radius burst of stabilizing magic centered on you', '10 minutes/level', 'none (harmless)', 'no (harmless)', 'This spell creates an area of stabilizing magical energy that emanates from you. Any creature within this area that fails a concentration check to cast a spell normally in an area of wild magic rolls twice to determine the wild magic effect and choose its preferred result.', NULL, NULL, false, false),
  ('infuse_robot', 'Infuse Robot', 'transmutation', NULL, NULL, 7, 'both', 'cleric 7, druid 7, sorcerer/wizard 7, witch 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one robot', NULL, NULL, '10 minutes/level (D)', 'Will negates', 'yes', 'If the targeted robot fails its Will saving throw, it transforms into a magical construct made of wood, stone, flesh, or bone. The robot’s statistics and abilities do not change, although it is now a magical construct rather than a technological one. It loses the robot subtype, but does not lose its Intelligence score (if any). You can issue mental commands to the infused robot as long as it stays within range of the spell; issuing commands in this manner is a free action for you. When the spell’s duration runs out, the robot transforms back to normal but is staggered for 1d4 rounds.', NULL, NULL, false, false),
  ('infuse_self', 'Infuse Self', 'transmutation', 'polymorph', NULL, 3, 'arcane', 'alchemist 3, bard 3, bloodrager 3, magus 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'When you cast this spell, you assume the form of a native outsider from the following list: aasimar, aphorite, duskwalker, fetchling, ganzi, ifrit, oread, shabti, suli, sylph, tiefling, or undine. You gain a +2 size bonus to one physical ability score of your choice. If the race has resistance to one or more energy types, you gain energy resistance 5 to your choice of one of those types. If the race gains a racial bonus on saving throws or skills, you gain those bonuses. If the race has darkvision or low-light vision, you gain those qualities.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('inheritor_s_smite', 'Inheritor’s Smite', 'transmutation', NULL, NULL, 2, 'divine', 'cleric/oracle 2, inquisitor 2, paladin 2', '1 swift action', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'You channel the power of righteousness into your weapon arm, allowing you to strike with great force. Your next melee attack (if made before the end of your next turn) gains a +5 sacred bonus on the attack roll. If the attack hits, you may immediately attempt a bull rush combat maneuver (with a +5 sacred bonus on your combat maneuver check) against the target without provoking an attack of opportunity; if your combat maneuver check exceeds the defender’s CMD by more than 5, you do not need to move with the target to push it back more than 5 feet.', NULL, NULL, true, false),
  ('inhibiting_patterns', 'Inhibiting Patterns', 'illusion', 'pattern', 'mind-affecting', 3, 'arcane', 'bard 3, psychic 4, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one cylinder (10-ft. radius, 40-ft. high)/3 levels', 'concentration +1 round/level (D)', 'Will negates', 'yes', 'You create one or more vibrant pillars of kaleidoscopic color that rise out from the ground.', 'a sprinkle of ground glass', NULL, false, false),
  ('inner_focus', 'Inner Focus', 'illusion', 'glamer', NULL, 1, 'divine', 'adept 2, antipaladin 1, cleric 2, druid 2, inquisitor 2, paladin 1, ranger 1', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level', 'none (harmless)', 'no', 'For the duration of this spell, you may ignore any divine focus components of your spells, allowing you to cast such spells without holding or revealing your holy or unholy symbol.', NULL, NULL, true, false),
  ('innocence', 'Innocence', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You surround yourself with an aura of innocence and trustworthiness. You gain a +10 competence bonus on Bluff skill checks to convince others of your innocence. They find it difficult to believe you capable of any wrongdoing. This bonus does not apply to other uses of the Bluff skill, such as feinting in combat, creating a diversion to hide, or communicating secret messages via innuendo, nor does it apply to any use of the skill to convince anyone of anything other than your complete innocence and blamelessness.', NULL, NULL, false, false),
  ('innocuous_shape', 'Innocuous Shape', 'transmutation', 'polymorph', NULL, 4, 'both', 'alchemist 4, psychic 4, shaman 4, sorcerer/wizard 4, witch 4', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell transforms a creature into a Medium or smaller animal or humanoid of no more than 1 Hit Die. If you use this spell to cause the target to take on the form of an animal, the spell functions as beast shape II. If the form is that of a humanoid, the spell can function as alter self, youthful appearance, or both, such that you can transform a creature into a generic, youthful humanoid of any type.', 'a handful of dandelion seeds', NULL, false, false),
  ('insanity', 'Insanity', 'enchantment', 'compulsion', 'mind-affecting', 7, 'arcane', 'sorcerer/wizard 7, witch 7; Domain charm 7, madness 7; Subdomain dark tapestry 7; Bloodline accursed 7, div 7; Mystery dark tapestry 7, outer rifts 7', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'The affected creature suffers from a continuous confusion effect, as the spell.', NULL, NULL, false, false),
  ('insect_plague', 'Insect Plague', 'conjuration', 'summoning', NULL, 4, 'both', 'cleric/oracle 5, druid 5, shaman 5, summoner 4, unchained summoner 5; Bloodline div 5; Mystery apocalypse 5', '1 round', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'one swarm of wasps per three levels, each of which must be adjacent to at least one other swarm', '1 min./level', 'none', 'no', 'You summon a number of swarms of wasps (one per three levels, to a maximum of six swarms at 18th level). The swarms must be summoned so that each one is adjacent to at least one other swarm (that is, the swarms must fill one contiguous area). You may summon the wasp swarms so that they share the area of other creatures. Each swarm attacks any creatures occupying its area. The swarms are stationary after being summoned, and won’t pursue creatures that flee.', NULL, NULL, true, false),
  ('insect_scouts', 'Insect Scouts', 'divination', NULL, NULL, 2, 'both', 'antipaladin 4, bard 4, druid 2, inquisitor 3, psychic 4, ranger 2, shaman 2, sorcerer/wizard 3, summoner 3, witch 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one insect scout/4 levels', '1d6 hours, plus 1 hour/level; see text', 'none', 'no', 'This spell summons one or more vermin to investigate a single location or building you can see. Your scouts must spend 1d6 hours investigating the target location, but need no oversight. When done, they return unerringly to you with their findings, traveling up to 1 mile per caster level you have to rejoin their master. Each insect’s size is Fine. Each insect has 1 hit point, AC 20 (+2 Dexterity, +8 size), a movement speed of 5 feet, a climb speed of 5 feet, and a fly speed of 20 feet (perfect maneuverability). The insects use your saving throw bonuses, have a total Perception skill bonus equal to 5 + 1/2 your caster level, and can’t attack. Because of their incredibly small size and magical nature, they can attempt Stealth checks to avoid being noticed even if they lack a source of cover or concealment, and they have a total Stealth skill bonus equal to 18 + 1/2 your caster level.', 'a drop of honey', NULL, false, false),
  ('insect_spies', 'Insect Spies', 'divination', NULL, NULL, 3, 'both', 'druid 3, ranger 3, sorcerer/wizard 4, summoner 3, witch 4', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'up to one insect spy/4 levels', '10 minutes/level (D)', 'none', 'no', 'You summon one or more glossy black beetles, which have a measure of intelligence and make for excellent spies. When they are in your presence, the insects obey your mental commands, and you can issue orders to any number of them as a single standard action, provided that you issue the same orders to each one. In order to issue different orders to different insects, you must spend a separate standard action for each set of orders. An insect in physical contact with you can answer simple questions about what it has observed, at a rate of one question per round. It can relate only what it perceived with its senses, and can’t repeat speech. It has difficulty making subjective judgments, and questions that demand such reasoning are unlikely to yield a clear answer.', 'a drop of honey', NULL, false, false),
  ('inspiring_recovery', 'Inspiring Recovery', 'conjuration', 'healing', 'mind-affecting', 4, 'divine', 'cleric/oracle 6, hunter 4, inquisitor 6, paladin 4, ranger 4, warpriest 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one target creature and all its allies within 60 feet; see text', NULL, NULL, 'instantaneous and 1 minute', 'Will half (harmless)', 'yes (harmless)', 'You can heal a creature, harm an undead creature, or call upon a very recently dead creature to fight beyond death’s reach. The target creature regains 1d8 hit points per 2 caster levels (maximum 10d8).', NULL, NULL, true, false),
  ('instant_armor', 'Instant Armor', 'conjuration', 'creation', 'force', 2, 'both', 'cleric/oracle 2, paladin 2, psychic 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You instantly wrap your body in a suit of armor made from opaque force. At your option, the armor can be decorated with your religion’s holy symbol in a prominent place, such as upon the breastplate or helm. While it exists, this armor replaces any garments or other sort of armor worn, magical as well as mundane. You lose access to, and all benefits from, armor replaced by this spell until the spell ends and the instant armor disappears.', NULL, NULL, true, false),
  ('instant_clot', 'Instant Clot', 'conjuration', 'healing', NULL, 1, 'both', 'alchemist 1, bard 1, cleric 1, druid 1, inquisitor 1, paladin 1, ranger 1, shaman 1, witch 1', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 round/level (D)', 'none (harmless)', 'yes (harmless)', 'Bleed effects on the target immediately end when this spell is cast, and no blood flows out when the target is damaged by a slashing or piercing weapon. The target takes the full amount of damage from attacks, but because the wounds produce no blood, they do not attract creatures with the ability to sense blood, such as sharks. If the target suffers another bleed effect while this spell is in effect, the bleed effect ends and the spell is immediately dismissed.', NULL, NULL, false, false),
  ('instant_enemy', 'Instant Enemy', 'enchantment', NULL, NULL, 3, 'divine', 'ranger 3', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'none', 'no', 'With this spell you designate the target as your favored enemy for the remainder of its duration. Select one of your favored enemy types. For the duration of the spell, you treat the target as if it were that type of favored enemy for all purposes.', NULL, NULL, false, false),
  ('instant_fake', 'Instant Fake', 'illusion', 'figment', NULL, 3, 'both', 'bard 3, inquisitor 3, magus 4, mesmerist 3, occultist 3, ranger 3, sorcerer/wizard 4', '1 standard action', '1 object touched', 'one object weighing no more than 1 lb./level', NULL, NULL, '1 minute/level', 'Will disbelief (if interacted with)', 'no', 'You create an illusory duplicate of the target item. If you hold the charge on this spell, you can deliver it while touching an object you steal with Sleight of Hand or a steal combat maneuver; in this case, the illusion phases into existence exactly as you remove the genuine article, allowing you to instantaneously replace a protected or guarded item with no change in appearance, weight, or other factors.', 'a piece of costume jewelry', NULL, false, false),
  ('instant_portrait', 'Instant Portrait', 'conjuration', 'creation', NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1, summoner 1, witch 1', '1 standard action', 'touch', NULL, NULL, 'a monochromatic illustration up to 1 square foot in area', 'instantaneous', 'none', 'no', 'You touch a surface and produce a painted portrait of either yourself or a creature you can see without needing to attempt a Craft (painting) check. The surface to be affected must be relatively flat, such as a piece of paper or a wall. The image can be any color of your choice, but is monochromatic. While it is of too poor a quality to sell, it is otherwise accurate enough to recognize the subject or to serve as a target for the enter image spell. The portrait reflects your perception of the creature depicted, including any disguises, magical or mundane, that the subject is wearing at the time of the painting’s creation.', NULL, NULL, false, false),
  ('instant_restoration', 'Instant Restoration', 'conjuration', 'healing', NULL, 4, 'both', 'cleric 4, druid 4, shaman 4, summoner 4, witch 4', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one summoned creature you control', NULL, NULL, '1 round/level (D)', 'none', 'no', 'Instant restoration channels planar energy into a summoned creature. This spell can be cast as an immediate action when a summoned creature you control drops to 0 or fewer hit points.', NULL, NULL, true, false),
  ('instant_suffocation', 'Instant Suffocation', 'necromancy', NULL, 'death', 9, 'arcane', NULL, '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fortitude partial', 'yes', 'This spell functions like slay living, and kills by immediate suffocation. Creatures that do not need to breathe are immune to this spell. The target is considered to have taken a dose of keif for the purpose of addiction and withdrawal effects.', NULL, NULL, false, false),
  ('instant_summons', 'Instant Summons', 'conjuration', 'summoning', NULL, 7, 'arcane', 'sorcerer/wizard 7, witch 7; Domain artifice 8, rune 7', '1 standard action', 'see text', 'one object weighing 10 lbs. or less whose longest dimension is 6 ft. or less', NULL, NULL, 'permanent until discharged', 'none', 'no', 'You call some nonliving item directly to your hand from virtually any location.', 'sapphire worth 1,000 gp', NULL, false, true),
  ('instant_weapon', 'Instant Weapon', 'conjuration', 'creation', 'force', 2, 'both', 'bard 2, bloodrager 2, cleric 2, inquisitor 2, magus 2, sorcerer/wizard 2', NULL, '0 ft.', NULL, NULL, 'melee weapon of opaque force', '1 minute/level', NULL, NULL, 'You create a melee weapon sized appropriately for you from opaque force.', NULL, NULL, false, false),
  ('instigate_psychic_duel', 'Instigate Psychic Duel', 'illusion )', 'phantasm', 'mind-affecting', 2, 'arcane', 'medium 2, mesmerist 2, occultist 2, psychic 2, spiritualist 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You begin a psychic duel with a creature. This psychic duel takes place on a binary mindscape that includes only two minds: yours and the target’s. This spell ends and both minds return to their respective bodies if one of you drops below 0 hit points or if both of you agree to end the psychic duel (a free action that you can perform even if it isn’t your turn).', NULL, NULL, false, false),
  ('instrument_of_agony', 'Instrument of Agony', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 2, inquisitor 2; Subdomain kyton (evil, law) 2', '1 standard action', 'touch', 'weapon touched', NULL, NULL, '1 minutes/level', 'Will negates (harmless, object), see text', 'yes (harmless, object), see text', 'You cause a weapon to exude a palpable aura of divine fury. While wielding this weapon, a creature gains a +2 morale bonus on Intimidate checks. When an attack made using the targeted weapon hits, the wielder can spend a free action to discharge the effect to inflict agony on the creature the weapon hit. If that creature has spell resistance, it applies against this effect. If the creature fails a Will save, it is nauseated for 1d4+1 rounds. If it succeeds at the saving throw, the creature is instead sickened for 1 round. The sickened condition created by the instrument is a mind-affecting effect.', NULL, NULL, false, false),
  ('intellect_fortress_i', 'Intellect Fortress I', 'abjuration', NULL, NULL, 4, 'arcane', 'psychic 4', '1 immediate action', '20 ft.', NULL, '20-ft.-radius emanation centered on you', NULL, '1 round', 'none', 'yes (harmless)', 'Using the power of pure logic, you disrupt mental attacks. Intellect fortress I suppresses all effects with the emotion and fear descriptors for its duration.', NULL, NULL, false, false),
  ('intensify_psyche', 'Intensify Psyche', 'enchantment', NULL, 'emotion, mind-affecting', 1, 'both', 'arcanist 2, bard 1, cleric/oracle 2, medium 2, mesmerist 1, psychic 2, skald 1, sorcerer/wizard 2, spiritualist 2, warpriest 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'one creature', '1 minute/level', 'Will negates', 'yes', 'A sense of euphoria suffuses the target, amplifying all sensations, good or bad.', NULL, NULL, false, false),
  ('interplanetary_teleport', 'Interplanetary Teleport', 'conjuration', 'teleportation', NULL, 9, 'both', 'cleric/oracle 9, sorcerer/wizard 9; Domain void 9; Mystery dark tapestry 9', '1 standard action', 'personal and touch', 'you and touched objects or other touched willing creatures', NULL, NULL, 'instantaneous', 'none and Will negates (object)', 'no and yes (object)', 'This spell functions as teleport, except there is truly no range limit and you do not need to have seen your destination, though you must have a solid grasp of which world you wish to travel to (“the third planet from the sun” is an acceptable destination, but “a habitable world near that bright star” is not). If you have a specific location on a planet in mind, you arrive there without a chance of failure; otherwise you arrive at a location that would not immediately be life-threatening. If no such safe landing zone exists on the world, such as someone attempting to travel into the sun without the proper precautions in place, the spell simply fails.', NULL, NULL, false, false),
  ('interposing_hand', 'Interposing Hand', 'evocation', NULL, 'force', 5, 'arcane', 'magus 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft. hand', '1 round/level (D)', 'none', 'yes', 'Interposing hand creates a Large magic hand that appears between you and one opponent. This floating, disembodied hand then moves to remain between the two of you, regardless of where you move or how the opponent tries to get around it, providing cover (+4 AC) for you against that opponent. Nothing can fool the hand–it sticks with the selected opponent in spite of darkness, invisibility, polymorphing, or any other attempt at hiding or disguise. The hand does not pursue an opponent, however.', NULL, 'a soft glove', false, false),
  ('interrogation', 'Interrogation', 'necromancy', NULL, 'evil, pain', 1, 'both', 'inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 round', 'touch', 'living creature touched', NULL, NULL, '1 minute/level', 'Fortitude negates', 'yes', 'You question the target, backed up by the threat of magical pain. You may ask one question per two caster levels. The target can either answer the question or take 1d4 points of damage plus your Wisdom bonus. The target is not compelled to answer truthfully, but the threat of pain gives it a –4 penalty on Bluff checks to convince you when it is lying.', NULL, NULL, false, false),
  ('inveigle_monster', 'Inveigle Monster', 'enchantment', 'charm', 'mind-affecting', 5, 'arcane', 'bard 5, mesmerist 5, psychic 6, sorcerer/wizard 7, witch 7', NULL, NULL, 'one living creature', NULL, NULL, '1 day/level', NULL, NULL, 'This spell functions as inveigle person except as noted above.', NULL, NULL, false, false),
  ('inveigle_person', 'Inveigle Person', 'enchantment', 'charm', 'mind-affecting', 3, 'arcane', 'bard 3, mesmerist 3, psychic 3, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You cause the target to become extremely amiable. The target treats all other living creatures as if it were friendly toward them. Any overtly hostile or harmful act toward the target by any living creature ends the spell.', 'a drop of alcohol', NULL, false, false),
  ('investigative_mind', 'Investigative Mind', 'enchantment', 'compulsion', 'mind-affecting', 2, 'arcane', 'alchemist 2, bard 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '10 minutes/level or until discharged', NULL, NULL, 'Your mind is able to correlate information effectively. When attempting an Appraise, Knowledge, Linguistics, or Spellcraft check, you can roll twice and take the higher result. If you have an ability that allows you to roll twice, you cannot use that ability and this benefit on the same roll.', NULL, NULL, false, false),
  ('invigorate', 'Invigorate', 'illusion', NULL, 'figment', 1, 'arcane', 'bard 1, psychic 1', '1 standard action', 'touch', NULL, NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell banishes feelings of weariness. For the duration, the subject takes no penalties from the fatigued or exhausted conditions. The effect of invigorate is merely an illusion, however, not a substitute for actual rest or respite. When the spell ends, the subject takes 1d6 points of nonlethal damage, along with the return of the original condition(s). A creature can be under the effects of only one invigorate spell at a time; if it is cast a second time on that creature, the first immediately ends.', NULL, NULL, false, false),
  ('invigorating_poison', 'Invigorating Poison', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, cleric 2, druid 2, shaman 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Fort negates (harmless)', 'yes (harmless)', 'The body of the target creature gains a metabolic response that allows it to benefit from normally deadly toxins. When a poison would cause ability damage to the target creature, the target instead gains a +4 alchemical bonus to that ability score. The spell then immediately ends, but the bonus lasts for a number of minutes equal to the amount of ability damage the poison would have caused. If the poison would deal more than one type of ability damage, each bonus has a separate duration.', 'an apple seed', NULL, true, false),
  ('invigorating_repose', 'Invigorating Repose', 'conjuration', 'healing', NULL, 9, 'arcane', 'cleric/oracle 5 (Magrim)', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour or until discharged', NULL, NULL, 'This spell enhances your spells that bring the dead back to life. If you cast raise dead, the target creature is restored to full hit points. If you cast breath of life, that spell can revive a dead target as long as you cast it within a number of rounds equal to half your caster level, and the healing effect is treated as if the spell were empowered with the Empower Spell feat. Casting any of these spells discharges the invigorating repose spell.', NULL, NULL, true, false),
  ('invisibility', 'Invisibility', 'illusion', 'glamer', NULL, 2, 'both', 'alchemist 2, antipaladin 2, bard 2, inquisitor 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 2, summoner/unchained summoner 2; Domain trickery 2; Bloodline arcane 2, djinni 2; Elemental School void 2; Mystery shadow 2', '1 standard action', 'personal or touch', 'you or a creature or object weighing no more than 100 lbs./level', NULL, NULL, '1 min./level (D)', 'Will negates (harmless) or Will negates (harmless, object)', 'yes (harmless) or yes (harmless, object)', 'The creature or object touched becomes invisible. If the recipient is a creature carrying gear, that vanishes, too. If you cast the spell on someone else, neither you nor your allies can see the subject, unless you can normally see invisible things or you employ magic to do so.', 'an eyelash encased in gum arabic', NULL, true, false),
  ('invisibility_alarm', 'Invisibility Alarm', 'abjuration', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, inquisitor 1, psychic 1, ranger 1, sorcerer/wizard 1 Duration 10 minutes/level', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as alarm, except it is triggered only by invisible creatures entering or leaving the warded area. The spell has a different mental alarm depending on whether the invisible creature is entering or leaving the area. This spell does not aid you in sensing or pinpointing the location of an invisible creature within the spell’s area.', NULL, NULL, false, false),
  ('invisibility_bubble', 'Invisibility Bubble', 'illusion', 'glamer', NULL, 2, 'both', 'alchemist 2, antipaladin 2, arcanist 2, bard 2, inquisitor 2, investigator 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, skald 2, sorcerer 2, spiritualist 2, summoner 2, unchained summoner 2, wizard 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'A glamered bubble surrounds the target’s space, rendering her completely invisible underwater by hiding both the target and any water she displaces. Because of the bubble’s size limit, this spell works only on Medium or smaller targets. Other objects and creatures within the bubble’s space are also invisible while they stay in the space, which could reveal the spell’s existence to a canny observer who notices fish disappearing into the bubble and reappearing on the other side. Creatures inside the bubble can see each other, which allows foes who can pinpoint the bubble’s location (such as dragons) to stick their heads into the bubble in order to see the target. Any creature on the inside of the bubble that takes any action that would break invisibility pops the bubble and ends the spell early. On land, the bubble is clearly visible, acting much as invisibility does in the water. Unlike with invisibility, the inside of the bubble blocks light from escaping the bubble, meaning that light sources inside the bubble don’t illuminate past its edges, but also don’t reveal a telltale glow.', 'needle from a sea urchin', NULL, false, false),
  ('invisibility_purge', 'Invisibility Purge', 'evocation', NULL, NULL, 3, 'divine', 'cleric/oracle 3, inquisitor 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'You surround yourself with a sphere of power with a radius of 5 feet per caster level that negates all forms of invisibility.', NULL, NULL, false, false),
  ('invisibility_sphere', 'Invisibility Sphere', 'illusion', 'glamer', NULL, 3, 'arcane', 'bard 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3, unchained summoner 3', NULL, NULL, NULL, '10-ft.-radius emanation around the creature', NULL, NULL, NULL, NULL, 'This spell functions like invisibility, except that this spell confers invisibility upon all creatures within 10 feet of the recipient at the time the spell is cast. The center of the effect is mobile with the recipient.', NULL, NULL, false, false),
  ('invoke_deity', 'Invoke Deity', 'transmutation', NULL, 'see text', 4, 'both', 'antipaladin 4, cleric 6, inquisitor 6, medium 4, occultist 6, paladin 4, ranger 4, witch 6', '1 round', 'personal', 'you', NULL, NULL, '10 minutes/level', NULL, NULL, 'By holding aloft a holy symbol and calling your deity’s name, you take on an aspect of that divinity. When you cast this spell, choose a domain offered by your deity. You gain that domain’s benefits from the list below, along with the listed physical changes; abilities that allow a saving throw use this spell’s DC. At any point during the duration of this spell, you can change which domain benefit you gain by concentrating for 1 round—this provokes attacks of opportunity and reduces the remaining duration of the spell by 10 minutes. If you have less than 10 minutes of the spell’s duration remaining, you cannot change the selected domain in this way. If you change your domain, all ongoing effects from your previously chosen domain end.', 'incense worth 1,000 gp', 'a bejeweled holy symbol of your patron deity worth 2,500 gp', false, true),
  ('invoke_primal_power', 'Invoke Primal Power', 'transmutation', NULL, NULL, 5, 'divine', 'druid 5', '1 swift action', 'personal', 'you', NULL, NULL, '1 round/level', 'none', 'no', 'This spell must be cast as you activate wild shape to assume the form of an animal of at least Large size. When you assume the animal form, it takes on many of the primal characteristics of the savage, prehistoric creatures that dwell in the Realm of the Mammoth Lords. When this spell’s duration expires, you return to your natural form automatically-in effect, you shorten the duration of that use of wild shape to the duration of this spell when you cast invoke primal power.', NULL, NULL, false, false),
  ('iron_body', 'Iron Body', 'transmutation', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8; Subdomain metal 8; Elemental School earth 8, metal 8; Mystery ascetic 9, metal 9', '1 standard action', 'personal', 'you', NULL, NULL, '1 min./level (D)', NULL, NULL, 'This spell transforms your body into living iron, which grants you several powerful resistances and abilities. You gain damage reduction 15/adamantine. You are immune to blindness, critical hits, ability score damage, deafness, disease, drowning, electricity, poison, stunning, and all spells or attacks that affect your physiology or respiration, because you have no physiology or respiration while this spell is in effect. You take only half damage from acid and fire. However, you also become vulnerable to all special attacks that affect iron golems.', 'a piece of iron from an iron golem, a hero’s armor, or a war machine', NULL, true, false),
  ('iron_spine', 'Iron Spine', 'transmutation', NULL, NULL, 3, 'both', 'arcanist 3, cleric/oracle 4, magus 3, sorcerer/wizard 3, warpriest 4, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round/level', 'none', 'yes', 'You launch an ingot of iron at the target.', 'cold iron ingot', NULL, true, false),
  ('iron_stake', 'Iron Stake', 'conjuration', 'creation', NULL, 2, 'both', 'cleric 3, druid 3, inquisitor 2, ranger 2, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous or 1 round/level; see text', 'Fortitude partial', 'no', 'This spell creates a 1-foot-long spike of cold iron that you fling at your target as a ranged touch attack. the stake is treated as a magic and cold iron weapon for the purpose of overcoming damage reduction, and deals 1d6 points of piercing damage for every 2 caster levels you have (maximum 10d6 at 20th level).', 'a pinch of iron filings', NULL, false, false),
  ('ironbeard', 'Ironbeard', 'transmutation', NULL, NULL, 1, 'both', 'antipaladin 1, cleric 1, magus 1, paladin 1, ranger 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'This spell causes a brushy beard of stiff iron to erupt from the face of a willing target. The ironbeard grants a +1 armor bonus to AC, and this bonus stacks with any armor worn by the creature. The ironbeard may also be used as a weapon equivalent to cold iron armor spikes. The ironbeard makes it difficult to speak, so any spellcasting with a verbal component has a 20% spell failure chance.', NULL, NULL, false, false),
  ('ironskin', 'Ironskin', 'transmutation', NULL, 'earth', 2, 'both', 'alchemist 2, antipaladin 2, bloodrager 2, cleric 2, druid 2, paladin 2, psychic 2, ranger 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D; see text)', NULL, NULL, 'Your skin hardens and takes on the color and texture of rough iron.', NULL, NULL, true, false),
  ('ironwood', 'Ironwood', 'transmutation', NULL, NULL, 6, 'arcane', 'druid 6; Mystery wood 6', '1 minute/lb. created', '0 ft.', NULL, NULL, 'an ironwood object weighing up to 5 lbs./level', '1 day/level (D)', 'none', 'no', 'Ironwood is a magical substance created by druids from normal wood. While remaining natural wood in almost every way, ironwood is as strong, heavy, and resistant to fire as steel. Spells that affect metal or iron do not function on ironwood. Spells that affect wood do affect ironwood, although ironwood does not burn. Using this spell with wood shape or a wood-related Craft check, you can fashion wooden items that function as steel items. Thus, wooden plate armor and wooden swords can be created that are as durable as their normal steel counterparts. These items are freely usable by druids.', NULL, 'wood to be transformed', false, false),
  ('irradiate', 'Irradiate', 'conjuration', 'creation', NULL, 3, 'both', 'cleric 3, druid 4, magus 3, sorcerer/wizard 3, summoner 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'special (see below)', 'instantaneous', 'Fortitude partial (see below)', 'no', 'The spell’s area of effect floods with dangerous radiation. The strength of the radiation you create depends on your caster level, as detailed below. The central irradiated area is always a 10-foot-radius spread that expands normally per the rules for radiation areas of effect. Creatures within the area are exposed to the radiation only once; the radiation does not linger in the area. The save to resist the radiation effects is set by the spell, not the standard save DC for radiation.', NULL, NULL, false, false),
  ('irregular_size', 'Irregular Size', 'transmutation', NULL, 'curse', 2, 'both', 'antipaladin 3, bloodrager 4, cleric 3, medium 2, mesmerist 3, occultist 3, shaman 3, sorcerer/wizard 4, spiritualist 4, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Fort negates', 'yes', 'You curse a creature so one set of its limbs (typically its arms, legs, or wings) shrivels in size.', NULL, NULL, false, false),
  ('irresistible_dance', 'Irresistible Dance', 'enchantment', 'compulsion', 'mind-affecting', 6, 'both', 'bard 6, shaman 8, sorcerer/wizard 8, witch 8; Subdomain revelry 8; Bloodline fey 8; Mystery whimsy 8', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1d4+1 rounds', 'Will partial', 'yes', 'The subject feels an undeniable urge to dance and begins doing so, complete with foot shuffling and tapping. The spell effect makes it impossible for the subject to do anything other than caper and prance in place. The effect imposes a -4 penalty to Armor Class and a -10 penalty on Reflex saves, and it negates any Armor Class bonus granted by a shield the target holds. The dancing subject provokes attacks of opportunity each round on its turn. A successful Will save reduces the duration of this effect to 1 round.', NULL, NULL, false, false),
  ('isolate', 'Isolate', 'illusion', 'glamer', NULL, 3, 'both', 'antipaladin 3, bard 3, inquisitor 3, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level (D)', 'Will partial', 'yes', 'You cause the target to become invisible and silent, but only to his allies.', NULL, NULL, false, false),
  ('itching_curse', 'Itching Curse', 'necromancy', NULL, 'curse', 1, 'both', 'antipaladin 1, bard 1, druid 1, inquisitor 1, occultist 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature with 5 HD or fewer', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'You curse the target with a distracting, unbearable itch. Unless the target scratches as a move action, it takes a –1 penalty on attack rolls, saving throws, skill checks, and ability checks.', NULL, NULL, false, false),
  ('ja_noi_aspect', 'Ja Noi Aspect', 'transmutation', 'polymorph', NULL, 3, 'both', 'alchemist 3, bloodrager 3, druid 3, magus 3, ranger 3, sorcerer/wizard 3', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You gain some of the appearance and qualities of the ja noi, oni who take hobgoblin form. Your skin turns a fiery red color and you gain fast healing 3, although this ability cannot repair damage caused by acid or fire. You can dismiss this spell as an immediate action when you fail a Will saving throw; if you do, you can reroll your saving throw, but you must take the second result.', NULL, NULL, true, false),
  ('janni_s_jaunt', 'Janni’s Jaunt', 'conjuration', 'teleportation', NULL, 3, 'both', 'cleric 4, medium 3, psychic 4, shaman 6, sorcerer/wizard 6, summoner 5, witch 6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as per plane shift, but with the following exceptions.', NULL, NULL, false, false),
  ('jealous_rage', 'Jealous Rage', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'both', 'antipaladin 2, bard 2, bloodrager 2, mesmerist 2, psychic 3, shaman 3, spiritualist 2, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 minute/level (D)', 'Will negates', 'no', 'You fill the target with a sense of entitled self-importance, making the subject unable to bear the indignity of another creature getting something that it doesn’t have. Whenever an ally of the target receives a harmless spell or spell-like ability, beneficial supernatural effect, or assisting action (including the aid another action, first aid using the Heal skill, etc.) that doesn’t also include the target, the target is driven into a murderous rage against either the producer of that effect or the nearest creature that benefited from that effect, whichever is closer. The target must attack that creature on its next turn. Any ability that deals lethal damage is considered an attack for this purpose. Once the target deals lethal damage to the object of his jealous rage, the compulsion to attack that creature ends.', NULL, NULL, false, false),
  ('jester_s_jaunt', 'Jester’s Jaunt', 'conjuration', 'teleportation', NULL, 3, 'arcane', 'bard 3', '1 standard action', 'touch', NULL, NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You teleport the target to a space you can see within 30 feet of the target. The destination must be on solid ground, and the teleportation cannot end in a space that is by nature hazardous to the creature you are teleporting.', NULL, NULL, false, false),
  ('jitterbugs', 'Jitterbugs', 'illusion', 'figment', 'mind-affecting', 1, 'arcane', 'bard 1, mesmerist 1, psychic 2, sorcerer/wizard 2', '1 standard action', 'short (25 ft. +5 ft. 2/levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You cause the target to perceive itself as being covered in creeping, crawling, stinging bugs. This causes the target to become jittery and unable to stay still, forcing it to constantly move and twitch. The target takes a –4 penalty on all Dexterity checks and Dexterity-based skill checks, and cannot take the delay, ready, or total defense actions.', NULL, NULL, false, false),
  ('jolting_portent', 'Jolting Portent', 'evocation  Level cleric 7', 'electricity', NULL, 9, 'arcane', NULL, '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 round/level (D) see text', 'Fortitude negates (see text)', 'yes', 'The creature you designate is surrounded by a glowing red aura of vengeful fate. Once per round when the target makes an attack or casts a spell, it must succeed at a Fortitude saving throw with a DC = 10 + 1/2 caster level + Charisma (in the case of oracles) or Wisdom (in the case of clerics). If the target fails the saving throw, it takes 4d6 + your Charisma modifier (in the case of oracles) or Wisdom modifier (in the case of clerics) electricity damage. It takes no damage on a successful saving throw. You can dismiss this spell as an immediate action when its subject confirms a critical hit to negate the critical hit and daze the creature for 1 round. The attack still hits its target and deals normal damage. The effects of the daze occur after the attack.', NULL, NULL, true, false),
  ('joyful_rapture', 'Joyful Rapture', 'conjuration', 'healing', 'emotion', 5, 'both', 'bard 5, cleric/oracle 6, sorcerer/wizard 7', '1 standard action', '60 ft.', NULL, 'all allies and opponents within a 60-ft.-radius burst centered on you', NULL, 'instantaneous', 'no', 'yes', 'Your inspired words overwhelm others with transcendental bliss. All allies within the area of effect are freed from any harmful emotion effects. The spell also cures 1d4 points of Intelligence, Wisdom, or Charisma damage (your choice) to all allies in the area.', NULL, NULL, false, false),
  ('judgment_light', 'Judgment Light', 'evocation', NULL, 'light', 4, 'divine', 'inquisitor 4', '1 standard action', 'personal', NULL, '30-ft.-radius burst', NULL, 'instantaneous, see text', 'see text', 'yes', 'An inquisitor may only cast this spell while she has a judgment active. When she does cast this spell, it causes one or more of the following effects based on the inquisitor’s active judgments.', NULL, NULL, false, false),
  ('judgment_undone', 'Judgment Undone', 'necromancy', NULL, NULL, 9, 'both', 'cleric 9, psychic 9, shaman 9', '10 minutes', 'touch', 'one willing petitioner', NULL, NULL, 'instantaneous', 'none', 'no', 'This powerful, elaborate, and risky spell returns a willing petitioner to its mortal life. This spell must be cast on the plane to which the petitioner was sent, and the petitioner must be present for the entire casting.', 'diamonds worth 50,000 gp', 'see text', false, true),
  ('jump', 'Jump', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bloodrager 1, druid 1, magus 1, psychic 1, ranger 1, sorcerer/wizard 1, summoner/unchained summoner 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min./level (D)', 'Will negates (harmless)', 'yes', 'The subject gets a +10 enhancement bonus on Acrobatics checks made to attempt high jumps or long jumps. The enhancement bonus increases to +20 at caster level 5th, and to +30 (the maximum) at caster level 9th.', 'a grasshopper’s hind leg', NULL, false, false),
  ('jungle_mind', 'Jungle Mind', 'divination', 'scrying', NULL, 4, 'divine', 'druid 5, oracle 5, ranger 4', '1 minute', 'personal', 'you', NULL, NULL, '10 minutes/level', 'Will negates (see text)', 'no', 'You merge your mind into the jungle’s social hierarchy, mystically establishing yourself as a master of wild beasts and an apex predator. You attain knowledge about the general animal population in a radius of 1 mile as commune with nature, and you then select one type of animal (such as birds, cats, snakes, or fish). For the duration of the spell, you can sense the location, movement, and size of creatures of this type in the area, though you can’t discern species or individual identity. In addition, you improve the starting attitude of animals of the chosen type by one step for the duration of the spell.', NULL, NULL, true, false),
  ('jury_rig', 'Jury-Rig', 'transmutation', NULL, NULL, 1, 'arcane', 'bard 1, magus 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', '1 standard action', 'touch', 'one broken object of up to 2 lbs./level', NULL, NULL, '1 round/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'When you cast this spell, a spectral force binds a broken weapon together, relieving the broken condition for a short time. While under the effects of this spell, an item with the broken condition suffers no adverse effects from that condition, and is treated as if it is not broken. The object regains no hit points, and damage can still destroy the object.', 'a pinch of tree resin', NULL, false, false),
  ('karmic_blessing', 'Karmic Blessing', 'divination', NULL, 'good', 1, 'both', 'cleric 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'The target treats one skill of your choice as a class skill.', NULL, NULL, false, false),
  ('keen_edge', 'Keen Edge', 'transmutation', NULL, NULL, 3, 'both', 'bloodrager 3, inquisitor 3, magus 3, sorcerer/wizard 3; Subdomain murder 3; Elemental School metal 3; Mystery metal 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 min./level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'This spell makes a weapon magically keen, improving its ability to deal telling blows. This transmutation doubles the threat range of the weapon. A threat range of 20 becomes 19-20, a threat range of 19-20 becomes 17-20, and a threat range of 18-20 becomes 15-20. The spell can be cast only on piercing or slashing weapons. If cast on arrows or crossbow bolts, the keen edge on a particular projectile ends after one use, whether or not the missile strikes its intended target. Treat shuriken as arrows, rather than as thrown weapons, for the purpose of this spell.', NULL, NULL, false, false),
  ('keen_senses', 'Keen Senses', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, druid 1, ranger 1; Elemental School void 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The subject gains a +2 competence bonus on Perception checks and gains low-light vision. Subjects that have low-light vision double the distance they can see under the effects of this spell.', 'a hawk‘s feather', NULL, true, false),
  ('keep_watch', 'Keep Watch', 'enchantment', NULL, NULL, 1, 'both', 'inquisitor 1, magus 1, paladin 1, ranger 1, sorcerer/wizard 1', NULL, 'touch', 'one creature touched/2 levels', NULL, NULL, '8 hours or less; see text', 'Will negates (harmless)', 'yes (harmless)', 'This spell enables the subjects to stand watch or keep vigil throughout the night without any ill effects.', NULL, NULL, false, false),
  ('keif_addiction', 'Keif Addiction', 'necromancy', NULL, NULL, 5, 'arcane', 'sahir-afiyun 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 day/level or until discharged (D)', 'none', 'yes', 'This spell functions like geas/quest, except the only allowed command is “use keif or refined keif.”', 'a dose of keif', NULL, false, false),
  ('keif_vigor', 'Keif Vigor', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, bloodrager 1, cleric 1, druid 1, magus 1, medium 1, psychic 1, shaman 1, sorcerer/wizard 1, summoner 1', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 round/level; see text', 'Will negates', 'yes', 'The target gains a +2 enhancement bonus to its Strength. Once per round as a free action, the target can choose to increase the enhancement bonus by 2 for 1 round; if it does so, it takes 1d6 points of nonlethal damage and the spell’s duration decreases by 1 additional round. For every 5 caster levels you have, the target can choose to increase the enhancement bonus by an additional 2, taking an additional 1d6 points of nonlethal damage and decreasing the duration by 1 additional round per increase to the Strength bonus, to a maximum enhancement bonus of +10 and 4d6 points of nonlethal damage at caster level 15th. The subject can’t spend more rounds than remain in the duration. When the spell ends, the subject becomes fatigued.', 'a dose of keif worth 15 gp', NULL, false, true),
  ('keyhole', 'Keyhole', 'transmutation', NULL, NULL, 1, 'both', 'cleric/oracle 1, sorcerer/wizard 1, witch 1', '1 round', 'touch', 'one touched door or portal', NULL, NULL, '1 minute/level', 'special (see text)', 'no', 'By touching a single door, gate, or other portal, you create a keyhole where none existed before or double the size of an existing keyhole. A conjured keyhole allows you to peer through the door, though the limited perspective imposes a –10 penalty on Perception checks to spot anything beyond. It also allows a sealed door to be locked or picked if it could not be before. Locking or unlocking such a door requires a successful Disable Device check with a DC equal to the barrier’s break DC + 10. Enlarging an existing keyhole allows viewers to peer through to whatever lies beyond, even if the preexisting keyhole did not allow it, and it reduces the Disable Device DC to open or lock the door by 5.', NULL, NULL, true, false),
  ('ki_arrow', 'Ki Arrow', 'conjuration', NULL, NULL, 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', '1 arrow touched', NULL, NULL, 'instantaneous', 'Fortitude (object)', 'yes (object)', 'You imbue an arrow with your power and throw it at a target up to 100 feet away. Make a ranged attack roll. If it hits, the target takes damage from the arrow as if you had hit it with a single unarmed strike (including your Strength bonus).', NULL, NULL, false, false),
  ('ki_leech', 'Ki Leech', 'necromancy', NULL, 'evil', 3, 'both', 'cleric/oracle 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You place your spirit in a receptive state so when you confirm a critical hit against a living enemy or reduce a living enemy to 0 or fewer hit points, you can steal some of that creature’s ki. This replenishes 1 point of ki as long as you have at least 1 ki point in your ki pool. This does not allow you to exceed your ki pool’s maximum. This ability does not stack with similar abilities (such as the steal ki ability of the hungry ghost monk). This spell has no effect if you do not have a ki pool.', NULL, NULL, false, false),
  ('ki_shout', 'Ki Shout', 'evocation', NULL, 'sonic', 5, 'arcane', 'bard 5, sorcerer/wizard 7', '1 standard action', 'close (25 ft + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'instantaneous', 'Fortitude partial (see text)', 'yes', 'With a guttural bark, you unleash a sudden blast of sonic energy that strikes your opponent. The target takes 1d6 points of sonic damage per level (maximum 20d6) and is stunned for 1 round; a successful Fortitude save reduces the damage by half and negates the stun.', NULL, NULL, false, false),
  ('kinetic_reverberation', 'Kinetic Reverberation', 'transmutation', NULL, NULL, 2, 'arcane', 'alchemist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Fort negates (object)', 'yes (object)', 'This spell converts the momentum and force from melee attacks made against the target of the spell, reflecting them back upon the attacker’s weapon. After making a successful melee attack against the target, an attacker must make a Fortitude saving throw for the weapon used. If the weapon fails the save, it takes damage equal to the damage rolled against the target. Creatures using natural attacks or unarmed strikes are unaffected by this spell.', 'rubber tree sap', NULL, false, false),
  ('king_s_castle', 'King’s Castle', 'conjuration', 'teleportation', NULL, 4, 'divine', 'paladin 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'This spell allows you to switch places with an ally. When you cast this spell, choose a single ally within range. You teleport to your ally’s space while your ally teleports to your former space.', NULL, NULL, true, false),
  ('kiss_of_the_first_world', 'Kiss of the First World', 'transmutation', NULL, NULL, 4, 'both', 'bard 4, druid 4', '1 standard action', 'touch', NULL, 'living or undead creature touched', NULL, '1 round/level', 'Will negates', 'yes', 'This spell infuses a living creature with a surge of positive energy, filling the target with the raw energies of life. The exact effects of this spell vary, depending on the nature of the creature touched. Constructs are immune to the effects of this spell.', 'diamond dust worth 100 gp', NULL, false, true),
  ('knell_of_the_depths', 'Knell of the Depths', 'conjuration', NULL, 'curse, water', 2, 'both', 'druid 3, magus 2, shaman 3, sorcerer/wizard 3, summoner 3, witch 2', '1 round', 'touch', 'one creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You invest a target with cursed elemental energy, causing nearby bodies of water to roil when the target draw nears and tendrils of water to drag it deeper under the waves.', NULL, NULL, false, false),
  ('knight_s_calling', 'Knight’s Calling', 'enchantment', 'compulsion', 'mind-affecting', 1, 'divine', 'paladin 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round', 'Will negates', 'yes', 'You compel an enemy to come and fight you. On its turn, the target moves its speed toward you, avoiding any other dangers along its path (including any movement that would provoke attacks of opportunity). The target may do nothing but move on its turn. If the target ends its move adjacent to you, you can make an attack of opportunity against the target.', NULL, NULL, true, false),
  ('knock', 'Knock', 'transmutation', NULL, NULL, 2, 'both', 'inquisitor 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one door, box, or chest with an area of up to 10 sq. ft./level', NULL, NULL, 'instantaneous; see text', 'none', 'no', 'Knock opens stuck, barred, or locked doors, as well as those subject to hold portal or arcane lock. When you complete the casting of this spell, make a caster level check against the DC of the lock (see table at right) with a +10 bonus. If successful, knock opens up to two means of closure. This spell opens secret doors, as well as locked or trick-opening boxes or chests. It also loosens welds, shackles, or chains (provided they serve to hold something shut). If used to open an arcane locked door, the spell does not remove the arcane lock but simply suspends its functioning for 10 minutes. In all other cases, the door does not relock itself or become stuck again on its own. Knock does not raise barred gates or similar impediments (such as a portcullis), nor does it affect ropes, vines, and the like. The effect is limited by the area. Each casting can undo as many as two means of preventing access.', NULL, NULL, false, false),
  ('know_direction', 'Know Direction', 'divination', NULL, NULL, 0, 'both', 'bard 0, druid 0, psychic 0, shaman 0', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'When you cast this spell, you instantly know the direction of north from your current position. The spell is effective in any environment in which “north” exists, but it may not work in extraplanar settings. Your knowledge of north is correct at the moment of casting, but you can get lost again within moments if you don’t find some external reference point to help you keep track of direction.', NULL, NULL, false, false),
  ('know_peerage', 'Know Peerage', 'divination', NULL, 'mind-affecting', 1, 'both', 'bard 1, cleric 2, inquisitor 2, medium 1, mesmerist 2, occultist 2, paladin 1, psychic 2, sorcerer/wizard 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates (harmless)', 'yes (harmless)', 'You impart your knowledge of nobility and peerage to the target, allowing her to recognize members of noble households, differentiate one set of heraldry from another, and otherwise identify who’s who at a royal gala or other noteworthy social event. The target is able to identify noble individuals, noble family names, and noble crests, signets, heraldry, and other symbols. The target treats her number of ranks in Knowledge (nobility) as though it were equal to your number of ranks in Knowledge (nobility), to a maximum of 5 ranks and a minimum of 0. If the target’s number of ranks is greater than yours, she uses her own number of ranks instead. In addition, if the target’s new total skill bonus on Knowledge (nobility) checks is at least +0, she automatically succeeds on all Knowledge (nobility) checks with a DC of 10 or lower.', 'thread from a tabard or livery', NULL, false, false),
  ('know_the_enemy', 'Know the Enemy', 'divination', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1, ranger 1; Domain [subdomain] Community [education]', '1 minute', 'personal', 'you', NULL, NULL, 'instantaneous', 'none', 'no', 'You commune with the divine, reflecting on one type of creature you encountered in the last day. You may make a Knowledge check regarding that creature type with a +10 insight bonus.', NULL, NULL, true, false),
  ('lament_of_summer_s_last_breath', 'Lament of Summer’s Last Breath', 'abjuration', NULL, 'fire, good', 2, 'both', 'bard 2, ranger 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft. radius spread centered on a creature, object, or point in space', NULL, '1 round/level', 'Will negates (see text)', 'yes', 'You wrap the target in a mantle of summery air, within which the ambient temperature never falls below 70 degrees Fahrenheit.', NULL, NULL, false, false),
  ('languid_bomb_admixture', 'Languid Bomb Admixture', 'enchantment', 'compulsion', 'mind-affecting', 5, 'arcane', 'alchemist 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'Will negates (special, see below)', 'yes', 'Upon drinking an extract created with this formula, you make a significant change to your magical reserve that modifies the nature of all bombs you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can only have one admixture effect (formulae with the words “bomb admixture” in their titles) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and the those of the new one become active.', NULL, NULL, false, false),
  ('languid_venom', 'Languid Venom', 'necromancy', NULL, 'poison', 2, 'both', 'alchemist 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one dose of poison or one venomous creature', NULL, NULL, 'permanent until discharged (D)', 'Fort negates', 'yes', 'You greatly extend the time it takes for the poison you touch to take effect, giving that poison an onset time up to 1 hour per caster level. (You touch the poison’s container, so you don’t risk exposing yourself to a contact poison.) The target doesn’t attempt a saving throw when initially exposed to the languid venom, but instead saves at the end of the poison’s onset time.', 'herbs used in antitoxins worth 25 gp', NULL, false, true),
  ('lash_of_the_astradaemon', 'Lash of the Astradaemon', 'necromancy', NULL, 'evil', 5, 'both', 'cleric 6, magus 5, sorcerer/wizard 6, witch 6', '1 standard action', 'personal', NULL, NULL, NULL, 'instantaneous', 'Fort negates (see text)', 'yes', 'You draw on the essence of astradaemons to cause one of your hands to elongate and sprout fearsome translucent claws that radiate a cold phosphorescence. You gain one claw attack, which is a primary natural attack that deals 1d6 points of slashing damage on a hit (1d4 for a Small spellcaster) and forces the creature struck to succeed at a Fortitude save against the spell (spell resistance applies) to resist gaining 1 negative level.', NULL, NULL, false, false),
  ('lay_of_the_land', 'Lay of the Land', 'divination', NULL, NULL, 2, 'both', 'cleric 2, bard 2, druid 2, ranger 2, witch 2', '1 minute', 'personal', 'you', NULL, NULL, '1 day', 'none', 'yes', 'In a flash of recognition, you learn about the geography of your surroundings within a radius of 1 mile per 2 caster levels (minimum 1 mile). This instant familiarity grants you an insight bonus equal to your caster level (maximum +5) on Knowledge (geography) checks and Survival checks to avoid getting lost so long as you remain in the affected area.', 'a piece of soil from the land to be memorized', NULL, false, false),
  ('lead_anchor', 'Lead Anchor', 'evocation', NULL, NULL, 2, 'both', 'alchemist 2, bard 2, druid 2, hunter 2, investigator 2, medium 2, occultist 2, psychic 2, ranger 2, shaman 2, skald 2, witch 2', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level', 'Will negates', 'yes', 'The target’s buoyancy becomes and stays swiftly sinking, regardless of how dense the target and its gear are. Among other effects, the target can walk on the bottom, but she also needs to succeed at a DC 20 Swim check to swim towards the surface and to stay above the bottom. This makes lead anchor a useful spell both for exploring the sea floor and for drowning an air-breathing foe in the water.', 'a bag of air', NULL, true, false),
  ('lead_blades', 'Lead Blades', 'transmutation', NULL, NULL, 1, 'arcane', 'ranger 1; Mystery metal 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Lead blades increases the momentum and density of your melee weapons just as they strike a foe. All melee weapons you are carrying when the spell is cast deal damage as if one size category larger than they actually are. For instance, a Medium longsword normally deals 1d8 points of damage, but it would instead deal 2d6 points of damage if benefiting from lead blades (see table below). Only you can benefit from this spell. If anyone else uses one of your weapons to make an attack it deals damage as normal for its size.', NULL, NULL, false, false),
  ('lead_plating', 'Lead Plating', 'conjuration', 'creation', NULL, 2, 'both', 'alchemist 3, cleric 2, druid 2, ranger 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'a creature or object weighing up to 100 lbs./level', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You enclose the target in a thin sheath of lead. This doesn’t restrict the target’s movement or functionality, but protects it from the effects of radiation and prevents the penetration of many divination spells. The lead doesn’t coat the target’s equipment.', NULL, 'an ounce of lead', false, false),
  ('leashed_shackles', 'Leashed Shackles', 'evocation', NULL, 'force', 4, 'both', 'inquisitor 4, sorcerer/wizard 6', '1 standard action', 'medium (100 ft. +10 ft./level)', 'one creature', NULL, NULL, '1 minute/level', 'Reflex negates', 'yes', 'You create shackles of force that attach to the target’s limbs. You designate an object or location within 30 feet of the target for the shackles to anchor themselves to; this must be the ground, a wall, or a sturdy structure for the anchoring to occur. The target is entangled, and cannot move more than 30 feet from the anchor point of the spell. The shackle itself cannot be attacked (though it can be dispelled), but if the object or area it is attached to is broken, the target is free to move away (though it is still entangled).', NULL, NULL, false, false),
  ('legend_lore', 'Legend Lore', 'divination', NULL, NULL, 4, 'both', 'bard 4, inquisitor 6, sorcerer/wizard 6, witch 6; Domain knowledge 7; Bloodline harrow 6; Elemental School void 6; Mystery ascetic 6, lore 4', 'see text', 'personal', 'you', NULL, NULL, 'see text', NULL, NULL, 'Legend lore brings to your mind legends about an important person, place, or thing. If the person or thing is at hand, or if you are in the place in question, the casting time is only 1d4 x 10 minutes. If you have only detailed information on the person, place, or thing, the casting time is 1d10 days, and the resulting lore is less complete and specific (though it often provides enough information to help you find the person, place, or thing, thus allowing a better legend lore result next time). If you know only rumors, the casting time is 2d6 weeks, and the resulting lore is vague and incomplete (though it often directs you to more detailed information, thus allowing a better legend lore result next time).', 'incense worth 250 gp', 'four pieces of ivory worth 50 gp each', false, true),
  ('legendary_proportions', 'Legendary Proportions', 'transmutation', NULL, NULL, 6, 'both', 'alchemist 6, druid 7, shaman 7, sorcerer/wizard 7, witch 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 creature (see text)', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'no', 'You call upon the primordial power of ancient megafauna to boost the size of your target. Because of its connection to living creatures of the distant past, the spell does not function on outsiders, undead, and summoned creatures. Your target grows to legendary proportions, increasing in size by one category. The creature’s height doubles and its weight increases by a factor of 8. The target gains a +6 size bonus to its Strength score and a +4 size bonus to its Constitution score. It gains a +6 size bonus to its natural armor, and DR 10/adamantine. Its carrying capacity changes to reflect its new size. The creature’s equipment and weapons, if any, also increase in size. Any enlarged item that leaves the creature’s possession returns to its original size (though thrown weapons and ammunition deal damage at their enlarged size before returning to their true proportions).', 'a dinosaur bone and powdered amber worth at least 200 gp', NULL, false, true),
  ('lend_judgment', 'Lend Judgment', 'divination', NULL, NULL, 1, 'divine', 'inquisitor 1', '1 standard action', 'touch', 'one ally', NULL, NULL, '1 round/level', 'Will negates (harmless)', 'yes (harmless)', 'You create a conduit of divine knowledge and outrage between you and an ally. That ally gains the benefit of one of your active judgments (as do you). If you cannot use a judgment (for example, if you are not in combat, are frightened or unconscious, and so on) or change judgments, the ally loses the benefit of the judgment. If you have multiple judgments active, the ally gains only one, chosen when you cast this spell.', NULL, NULL, true, false),
  ('leshy_swarm', 'Leshy Swarm', 'conjuration', 'summoning', NULL, 3, 'both', 'bard 3, druid 3, sorcerer/wizard 3, summoner 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '10-ft.-square swarm of leshys', '1 round/level', 'none', 'no', 'You call out to nearby nature spirits and grant them temporary plant bodies.', 'a bundle of seeds', NULL, true, false),
  ('levitate', 'Levitate', 'transmutation', NULL, NULL, 2, 'both', 'alchemist 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, shaman 2, sorcerer/wizard 2, spiritualist 2, summoner/unchained summoner 2, witch 2; Domain void 2; Elemental School air 2', '1 standard action', 'personal or close (25 ft. + 5 ft./2 levels)', 'you or one willing creature or one object (total weight up to 100 lbs./level)', NULL, NULL, '1 min./level (D)', 'none', 'no', 'Levitate allows you to move yourself, another creature, or an object up and down as you wish. A creature must be willing to be levitated, and an object must be unattended or possessed by a willing creature. You can mentally direct the recipient to move up or down as much as 20 feet each round; doing so is a move action. You cannot move the recipient horizontally, but the recipient could clamber along the face of a cliff, for example, or push against a ceiling to move laterally (generally at half its base land speed).', NULL, 'a leather loop or golden wire bent into a cup shape', false, false),
  ('liberating_command', 'Liberating Command', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 1, druid 1, paladin 1, psychic 1, ranger 1, sorcerer/wizard 1', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'If the target is bound, grappled, or otherwise restrained, he may make an Escape Artist check to escape as an immediate action. He gains a competence bonus on this check equal to twice your caster level (maximum +20). This spell has no effect if the target could not get free by using the Escape Artist skill (for example, if he were under the effects of a hold person spell or paralyzed by Strength damage).', NULL, NULL, false, false),
  ('life_blast', 'Life Blast', 'necromancy', NULL, NULL, 3, 'divine', 'druid 4, ranger 3, shaman 4', '1 standard action', '150 ft.', NULL, '150-ft. line', NULL, 'instantaneous', 'Will half', 'yes', 'This spell must be cast in an area with vegetation or it has no effect. When you cast this spell, you draw the life force from the surrounding land and hurl it at your enemies, dealing 1d6 points of positive energy damage per caster level (to a maximum of 12d6 at 12th level) to any undead creatures in the spell’s area.', 'a dead leaf', NULL, false, false),
  ('life_bubble', 'Life Bubble', 'abjuration', NULL, NULL, 3, 'both', 'cleric/oracle 5, druid 4, ranger 3, sorcerer/wizard 5', '1 standard action', 'touch', NULL, NULL, NULL, '2 hours/level; see text', 'Will negates (harmless)', 'yes (harmless)', 'You surround the touched creatures with a constant and moveable 1-inch shell of tolerable living conditions. This shell enables the subjects to breathe freely, even underwater or in a vacuum, as well as making them immune to harmful gases and vapors, including inhaled diseases and poisons and spells like cloudkill and stinking cloud. In addition, the shell protects subjects from extremes of temperature (per endure elements) as well as extremes of pressure.', 'a bit of eggshell', NULL, true, false),
  ('life_channel', 'Life Channel', 'transmutation', NULL, NULL, 2, 'divine', 'cleric 2', '1 standard action', 'touch', 'one touched creature with negative energy affinity', NULL, NULL, '1 minute/level', 'Fort negates (harmless)', 'yes (harmless)', 'When cast on a creature with negative energy affinity, the target is able to convert channeled positive energy into temporary hit points. When subject to an effect that heals hit points only to living creatures (such as cure light wounds or channel positive energy), the target gains a number of temporary hit points equal to half the number of hit points that the positive energy would normally heal. These temporary hit points go away at the end of this spell’s duration.', NULL, NULL, false, false),
  ('life_conduit', 'Life Conduit', 'conjuration', 'healing', NULL, 1, 'arcane', 'summoner/unchained summoner 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'You utilize life conduit to share hit points with your eidolon. While this spell is active, you can spend a swift action to transfer 1d6 hit points between you and your eidolon, either taking damage yourself and healing your eidolon or healing yourself and damaging your eidolon. If your eidolon moves farther than 50 feet from you, this spell ends.', NULL, NULL, false, false),
  ('life_current', 'Life Current', 'conjuration', 'healing', 'water', 3, 'divine', 'cleric/oracle 3, druid 3, hunter 3, oracle 3, paladin 3, ranger 3, shaman 3, warpriest 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'current or portion of current', NULL, '1 round', 'Will half', 'yes', 'You infuse the current with positive energy. At the start of their turn when the current moves them, living creatures in the current’s area heal 1d6 hit points per 10 feet of the current’s speed (maximum 6d6). Undead creatures in the current instead take an equal amount of damage.', NULL, NULL, true, false),
  ('life_of_crime', 'Life of Crime', 'enchantment', 'compulsion', 'curse, mind-affecting', 4, 'both', 'antipaladin 4, bard 6, mesmerist 6, psychic 8, sorcerer/wizard 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You unleash the basest instincts of iniquity in the target and cause them to become his overriding reason for being. The target neither gains nor provides benefit from teamwork feats or the aid another action and can’t willingly accept harmless magical effects from others.', 'a black mask', NULL, false, false),
  ('life_pact', 'Life Pact', 'necromancy', NULL, NULL, 2, 'both', 'cleric/oracle 2, psychic 2, shaman 2, sorcerer/wizard 2, spiritualist 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes', 'You bind the life forces of the targets into a mystical pact. If any target is reduced to fewer than 0 hit points, that target automatically triggers the power of the pact. The triggering target drains 1 hit point from all other targets who have at least 1 hit point and are within 30 feet of the triggering target; these hit points are applied to the triggering target as magical healing. This healing can prevent the triggering creature from dying, if the attack would cause the target’s to have an amount of negative hit points equal to its Constitution score. This healing cannot raise the triggering creature above 1 hit point; any excess hit points drained from other targets are wasted.', NULL, NULL, true, false),
  ('life_shield', 'Life Shield', 'conjuration', 'healing', NULL, 2, 'divine', 'cleric 3, druid 3, paladin 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level or until discharged', NULL, NULL, 'You surround yourself with a positive energy field that damages undead opponents. Each time an undead creature damages you with a melee attack, that creature takes an amount of positive energy damage equal to half the damage it dealt to you. This damage is calculated after applying your damage reduction, resistances, and other defenses. Once this spell has dealt 5 points of damage per caster level (maximum 50), it is discharged.', NULL, NULL, true, false),
  ('light', 'Light', 'evocation', NULL, 'light', 0, 'both', 'bard 0, cleric/oracle 0, druid 0, inquisitor 0, magus 0, psychic 0, shaman 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0; Elemental School wood 0', '1 standard action', 'touch', 'object touched', NULL, NULL, '10 min./level', 'none', 'no', 'This spell causes a touched object to glow like a torch, shedding normal light in a 20-foot radius from the point touched, and increasing the light level for an additional 20 feet by one step, up to normal light (darkness becomes dim light, and dim light becomes normal light). In an area of normal or bright light, this spell has no effect. The effect is immobile, but it can be cast on a movable object.', 'a firefly', NULL, true, false),
  ('light_lance', 'Light Lance', 'evocation', NULL, 'good, light', 2, 'divine', 'paladin 2', '1 standard action', 'personal', NULL, NULL, 'lance of light', '1 round + 1 round/level (D)', NULL, NULL, 'You create a glorious beam of brilliant radiance that acts as a +1 holy lance suitable for your size. You must have a free hand when casting the spell and, once you call the lance into being, you cannot switch it to another hand or put it down without prematurely ending the spell. As a standard action while holding a light lance, you can choose not to make an attack and instead hold the lance aloft as a beacon of light and truth, creating an area of bright light with a radius of 90 feet. If you choose to do this for one or more additional rounds the lance also casts a spear of brilliant light up into the sky that grows progressively more visible as it continues to climb toward the heavens. Under cover of night or other darkness, if nothing obstructs the beam, it becomes visible for an additional 2 miles during each round in which you continue to aim your lance skyward (2 miles in the second round, 4 miles in the third round, and so on).', NULL, NULL, false, false),
  ('light_prison', 'Light Prison', 'evocation', NULL, 'light', 2, 'both', 'bard 2, cleric/oracle 2, inquisitor 2, magus 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/2 levels', NULL, NULL, '1 round/level (D)', 'Reflex negates', 'yes', 'Rays of light burst forth from your outstretched hand, encircling each target’s space with a cage of light. If a target fails its Reflex save, it becomes enclosed in the light prison. A creature enclosed in a light prison can attack, cast spells, and otherwise act normally as long as it stays within the light prison. However, if a creature passes through the walls of a light prison enclosing it, it takes 1d6 points of damage and is blinded for 1 round. Creatures do not receive saves to negate these effects. Once a creature passes through the walls of a light prison surrounding it, the effect ends for that creature.', NULL, NULL, false, false),
  ('lighten_object', 'Lighten Object', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, cleric/oracle 1, magus 1, sorcerer/wizard 1, summoner 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 object of up to 1 cubic ft./level', NULL, NULL, '1 minute/level', 'Will negates (object)', 'yes (object)', 'The target’s weight decreases by half. If this spell is cast on armor, the armor’s armor check penalty decreases by 1, though its categorization as light, medium, or heavy does not change.', 'goose down', NULL, false, false),
  ('lightfingers', 'Lightfingers', 'transmutation', NULL, NULL, 1, 'arcane', 'psychic 1, spiritualist 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'none', 'yes', 'A flutter of subtle, telekinetic force causes your target to drop a single non-magical carried item weighing no more than 1 pound per caster level, such as a coin purse, a key ring, or a loose object in its pocket. The target must succeed at a Perception check against the spell’s save DC to notice the dropped item. You select what item the target drops as long as you can see both your target and the item you wish to affect. This use of the spell can’t cause a target to lose a held item or anything it is wearing, including jewelry.', NULL, NULL, false, false),
  ('lightning_arc', 'Lightning Arc', 'evocation', NULL, 'electricity', 5, 'arcane', 'sorcerer/wizard 5; Elemental School metal 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, 'instantaneous', 'Reflex half', 'yes (see text)', 'You generate an arc of lightning between two targets. The lightning deals 1d6 points of electricity damage per caster level (maximum 15d6) to both targets and any creatures in a line connecting them. The spell fails if there is no line of effect between the targets. Lightning arc sets fire to combustibles and damages objects in its path. It can melt metals that have a low melting point, such as lead, gold, copper, silver, or bronze.', 'fur and two glass figurines', NULL, false, false),
  ('lightning_bolt', 'Lightning Bolt', 'evocation', NULL, 'electricity', 3, 'arcane', 'bloodrager 3, magus 3, sorcerer/wizard 3, witch 3; Elemental School air 3, metal 3', '1 standard action', '120 ft.', NULL, '120-ft. line', NULL, 'instantaneous', 'Reflex half', 'yes', 'You release a powerful stroke of electrical energy that deals 1d6 points of electricity damage per caster level (maximum 10d6) to each creature within its area. The bolt begins at your fingertips.', 'fur and a glass rod', NULL, false, false),
  ('lightning_conductor', 'Lightning Conductor', 'transmutation', NULL, 'air', 2, 'both', 'bloodrager 2, druid 3, magus 3, sorcerer/wizard 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'You become capable of absorbing electricity with your body.', 'a miniature metal rod', NULL, true, false),
  ('lightning_lash_bomb_admixture', 'Lightning Lash Bomb Admixture', 'evocation', NULL, 'electricity', 3, 'arcane', 'alchemist 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'special, see below', 'special, see below', 'Upon drinking an extract created with this formula, you make a significant change to your magical reserve that modifies the nature of all bombs you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can only have one admixture effect (formulae with the word “bomb admixture” in its title) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and those of the new one become active.', NULL, NULL, false, false),
  ('lily_pad_stride', 'Lily Pad Stride', 'transmutation', NULL, NULL, 3, 'divine', 'druid 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'trail of lily pads behind you', '10 minutes/level (D); see text', 'none', 'no', 'Your every footstep creates aquatic plants capable of supporting your weight and that of any creature of your size or smaller that is following you. These lily pads only appear when you cross water or other liquids which do not immediately destroy plants. You can walk across these liquid surfaces without any fear of stumbling (though if knocked prone, dragged under, or otherwise pulled off your feet you still sink in the liquid). For the duration of the spell, any creature of your size or smaller can attempt to follow you by making a DC 10 Acrobatics check every round. Each such check allows it to move at half its normal land speed. If the creature takes a -5 penalty on its check it can move at its normal speed.', 'a frog’s leg', NULL, false, false),
  ('limited_wish', 'Limited Wish', 'universal', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7; Subdomain construct 7', '1 standard action', 'see text', NULL, 'see text', NULL, 'see text', 'none, see text', 'yes', 'A limited wish lets you create nearly any type of effect. For example, a limited wish can do any of the following things.', 'diamond worth 1,500 gp', NULL, false, true),
  ('limp_lash', 'Limp Lash', 'necromancy', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', '20 ft.', '1 creature', NULL, NULL, 'special (see below)', 'none', 'yes', 'You create a dark whip-shaped field of energy that wraps around an enemy’s neck, leaving everything except his head paralyzed until you let go of the whip or it is destroyed.', 'a dead wasp', NULL, false, false),
  ('line_in_the_sand', 'Line In The Sand', 'abjuration', NULL, NULL, 1, 'arcane', 'bloodrager 1, magus 1, sorcerer/wizard 1', '1 standard action', '5 ft.', NULL, '5-ft. burst centered on you', NULL, '1 round/level', 'none', 'no', 'You create a glowing crimson line around the area. Against creatures in the area, you can attempt a number of additional attacks of opportunity per round equal to your spellcasting ability score modifier (Intelligence for magi and wizards, Charisma for bloodragers and sorcerers), although this does not allow you to make more than one attack against a creature per action that provokes.', NULL, NULL, false, false),
  ('linebreaker', 'Linebreaker', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, inquisitor 1, magus 1, paladin 1, ranger 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You gain a +20 foot bonus to your base speed when charging and a +2 bonus on combat maneuver checks made to bull rush or overrun.', NULL, NULL, false, false),
  ('linked_legacy', 'Linked Legacy', 'divination', NULL, NULL, 1, 'both', 'bard 1, medium 1, mesmerist 1, occultist 1, psychic 1, shaman 1, sorcerer/wizard 1, witch 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '10 minutes/level', 'none', 'yes', 'This spell helps build community and ensure a shared vision for the future. When any of the affected creatures succeeds at a Knowledge check to answer a question within its field of study or identify a monster and its special powers or vulnerabilities, as a free action the affected creature can share any information gained automatically with all targets of the spell. If any of the targets move out of the spell’s range, the spell ceases to function for all of them until they are all within close range of you again.', NULL, NULL, false, false),
  ('lipstitch', 'Lipstitch', 'necromancy', NULL, NULL, 2, 'arcane', 'sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'A rare spell without verbal components, lipstitch sews the target’s lips tightly together if it fails a saving throw, such that no clear speech, bite attacks, spellcasting, or use of command words is possible. The target takes 1d6 points of damage as the stitches weave through flesh. The victim can still make enough noise to be heard at a distance with a DC 10 Perception check.', 'a bone needle and sinew thread', NULL, false, false),
  ('liquefy', 'Liquefy', 'transmutation', NULL, NULL, 3, 'both', 'alchemist 3, bard 3, druid 4, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 object weighing up to 1 pound/level', NULL, NULL, '1 round/level (D)', 'Fort negates (object)', 'no', 'The object you target becomes a liquid version of itself and drips or runs like a thin oil until it pools on any flat surface. If the item has magical or alchemical properties, they become inert for the duration of the spell. If you are holding the item when you cast this spell, you can drain it into the bottle used as focus for the spell. Items with hit point damage or the broken condition regain 5 hit points/caster level if drained into a bottle in this way. The duration of temporary effects (such as applied poison or greater magic weapon) passes normally and may expire while the object is in liquid form. The liquid is clearly unsafe to drink, but if, for some reason, a creature does drink the liquid and the spell ends, the creature takes 3d6 points of damage, and brings up the solid version of the item as a standard action in a coughing fit.', 'a specially prepared glass bottle', NULL, false, false),
  ('litany_of_admonition', 'Litany of Admonition', 'necromancy', NULL, 'language-dependent', 3, 'divine', 'antipaladin 3, inquisitor 4, paladin 3', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Fort negates', 'yes', 'You point out your target’s faults and failures, staggering the target for 1 round. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_defense', 'Litany of Defense', 'transmutation', NULL, NULL, 2, 'divine', 'antipaladin 2, inquisitor 2, paladin 2', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', 'no', 'yes', 'Invoking this litany strengthens your defenses. Any enhancement bonus your armor has is doubled and you are immune to fear. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_dependability', 'Litany of Dependability', 'enchantment', 'compulsion', 'lawful', 3, 'divine', 'inquisitor 4, paladin 3', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'By uttering this litany, you cause one creature to take the average result of its next attack roll, saving throw, skill check, or ability check. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_duty', 'Litany of Duty', 'abjuration', NULL, 'lawful', 1, 'divine', 'inquisitor 2, paladin 1', '1 immediate action', 'personal', NULL, NULL, NULL, 'instantaneous', NULL, NULL, 'You repeat a mantra or phrase that reminds you of your duty. You can immediately reroll a failed saving throw against a spell that would force you to take an action against your will, and you gain a +2 bonus against enchantment effects for 1 round. You can use this spell to reroll only a saving throw that you failed within the past round. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_eloquence', 'Litany of Eloquence', 'enchantment', 'charm', 'language-dependent, mind-affecting', 2, 'divine', 'antipaladin 2, inquisitor 3, paladin 2', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'no', 'yes', 'Your litany is a fascinating diatribe of grace, causing your target to do nothing but listen. The target is fascinated. As usual, obvious danger prevents fascination and potential danger grants a save.', NULL, NULL, true, false),
  ('litany_of_entanglement', 'Litany of Entanglement', 'conjuration', 'calling', 'language-dependent', 2, 'divine', 'antipaladin 2, inquisitor 3, paladin 2', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'Your litany conjures chains of energy that lash upward from the ground and hamper the target’s movement. The target is entangled. This spell has no effect on flying creatures, or creatures not standing upon solid ground. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_escape', 'Litany of Escape', 'conjuration', 'teleportation', 'language-dependent', 3, 'divine', 'antipaladin 3, inquisitor 4, paladin 3', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one willing creature that is grappled', NULL, NULL, 'instantaneous', 'no', 'yes', 'With a powerful prayer, you call upon the servants of your god to whisk a friend out of a grapple. The target loses the grappled and pinned conditions and is teleported 10 feet. If there is no available space for the target to teleport to, the spell fails.', NULL, NULL, true, false),
  ('litany_of_madness', 'Litany of Madness', 'enchantment', 'charm', 'language-dependent, mind-affecting', 4, 'divine', 'antipaladin 4, inquisitor 6; Mystery lunar 6', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 or more rounds (see below)', 'no, see below', 'yes', 'This litany is a sermon of madness. The target is confused. At the start of each of its turns, it can make a Will saving throw against the confused effect (DC of the spell). If the target fails the save, it continues to be confused. If it makes the save, the effect ends.', NULL, NULL, true, false),
  ('litany_of_order', 'Litany of Order', 'evocation', NULL, 'lawful, language-dependent', 2, 'divine', 'inquisitor 3, paladin 2', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'By shouting a forceful litany of strictures, you make a chaotic creature more susceptible to the attacks of lawful creatures. If the target is chaotic, it takes double the normal damage from attacks made by creatures that have a lawful aura from a class feature or by creatures that have the lawful subtype. If the target also has the chaotic subtype, when it is hit with attacks made by creatures with a lawful aura, it is also sickened for 1 round. If this spell targets a nonchaotic creature (or one that lacks the chaotic subtype), it has no effect and the spell is wasted. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_righteousness', 'Litany of Righteousness', 'evocation', NULL, 'good, language-dependent', 2, 'divine', 'inquisitor 3, paladin 2', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'Calling down a litany of anathema, you make an evil more susceptible to the attacks of good creatures. If the target is evil, it takes double damage from attacks made by creatures with a good aura (from a class feature or as a creature with the good subtype). If the target also has the evil subtype; when it is hit with attacks made by creatures with a good aura, it is also dazzled for 1d4 rounds. If this spell targets a nonevil creature (or one that lacks the evil subtype), it has no effect, and the spell is wasted.', NULL, NULL, true, false),
  ('litany_of_sight', 'Litany of Sight', 'divination', NULL, NULL, 3, 'divine', 'antipaladin 3, inquisitor 4, paladin 3', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', 'no', 'yes', 'This litany reveals the unseen to you. You can see invisible creatures and objects within 30 feet. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_sloth', 'Litany of Sloth', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 1, 'divine', 'antipaladin 1, inquisitor 1, paladin 1', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'With a litany against the wages of sloth, you slow the target’s defenses. The target cannot make attacks of opportunity or cast spells defensively.', NULL, NULL, true, false),
  ('litany_of_the_red_crusader', 'Litany of the Red Crusader', 'necromancy', NULL, NULL, 1, 'divine', 'antipaladin 1, inquisitor 2, paladin 1', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Fort negates', 'yes', 'Followers of Arazni have made use of this litany since her days as a crusader and herald. Each time the target creature takes piercing or slashing damage, it takes 1 point of bleed damage; this bleed damage stacks with itself. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_thunder', 'Litany of Thunder', 'evocation', NULL, 'language-dependent, sonic', 4, 'divine', 'antipaladin 4, inquisitor 5, paladin 4', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Fort negates', 'yes', 'You call down a thunderous boom upon your enemy. The target becomes deafened until the condition is removed, and is confused for 1 round. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_truth', 'Litany of Truth', 'divination', NULL, 'language-dependent', 4, 'divine', 'inquisitor 6, paladin 4', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'With a tirade against deceit, you strip the target of any illusions cloaking it. Any illusion spells or effects affecting the target are suppressed for the spell’s duration. In addition, the target can’t benefit from concealment.', NULL, NULL, true, false),
  ('litany_of_vengeance', 'Litany of Vengeance', 'transmutation', NULL, 'language-dependent', 4, 'divine', 'antipaladin 4, inquisitor 5, paladin 4', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'no', 'yes', 'This litany causes your enemy to feel the pain of blows more sharply. Anyone who hits the target with an attack gains a +5 sacred or profane bonus (depending on the alignment of the caster) to that attack’s damage. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_warding', 'Litany of Warding', 'transmutation', NULL, NULL, 2, 'divine', 'antipaladin 2, inquisitor 3, paladin 2', '1 swift action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'With this litany, you become more aware of your opponents. You can make two additional attacks of opportunity this round. Furthermore, you gain a +2 sacred bonus to AC against attacks of opportunity. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('litany_of_weakness', 'Litany of Weakness', 'necromancy', NULL, 'language-dependent', 1, 'divine', 'antipaladin 1, inquisitor 1', '1 swift action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'no', 'yes', 'Your litany proclaims your target weak, sapping its strength. The target is fatigued for 1 round. While subject to this spell, the target cannot be the target of another spell that has the word “litany” in the title.', NULL, NULL, true, false),
  ('liveoak', 'Liveoak', 'transmutation', NULL, NULL, 6, 'divine', 'druid 6, shaman 7; Elemental School wood 7', '10 minutes', 'touch', 'tree touched', NULL, NULL, '1 day/level (D)', 'none', 'no', 'This spell turns an oak tree into a protector or guardian. The spell can only be cast on a single tree at a time; while liveoak is in effect, you can’t cast it again on another tree. Liveoak must be cast on a healthy, Huge oak. A triggering phrase of up to one word per caster level is placed on the targeted oak. The liveoak spell triggers the tree into animating as a treant.', NULL, NULL, false, false),
  ('loathsome_veil', 'Loathsome Veil', 'illusion', 'pattern', 'mind-affecting', 3, 'arcane', 'mesmerist 3, psychic 3, sorcerer/ wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'transparent pattern 40 ft. long, 20 ft. high', 'concentration + 1 round/level (D)', 'Will negates', 'yes', 'This spell creates a transparent veil of shifting, multicolored strands of light that form into endlessly varied and alien patterns. One side of the veil, chosen by you at the time of casting, is harmless. The other side twists and turns into impossible shapes, affecting any creature with 60 feet who views the veil. The veil affects a maximum of 24 Hit Dice of creatures. Creatures with the fewest HD are affected first. Among creatures with equal HD, those who are closest to the spell are affected first. The effect is according to the creature’s HD.', 'a tangle of multicolored threads', NULL, false, false),
  ('locate_creature', 'Locate Creature', 'divination', NULL, NULL, 3, 'arcane', 'bard 4, sorcerer/wizard 4, summoner 3, unchained summoner 4, witch 4; Subdomain exploration 4', NULL, NULL, NULL, NULL, NULL, '10 min./level', NULL, NULL, 'This spell functions like locate object, except this spell locates a known creature. You slowly turn and sense when you are facing in the direction of the creature to be located, provided it is within range. You also know in which direction the creature is moving, if any.', NULL, NULL, false, false),
  ('locate_gate', 'Locate Gate', 'divination', NULL, NULL, 5, 'both', 'bard 5, cleric 5, occultist 5, psychic 5, sorcerer/wizard 5, summoner 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'circle centered on you with a radius of 400 ft. + 40 ft./level', NULL, '1 minute/level', 'none', 'no', 'You sense the direction of the nearest teleportation circle (permanent or with a remaining duration), gate spell, or other effect which magically connects two different locations (for example, an active magic item, a creature’s special ability, or unique adventure location). Locate gate detects only spells or effects with a permanent or ongoing duration, not instantaneous effects like dimension door or teleport.', NULL, NULL, true, false),
  ('locate_object', 'Locate Object', 'divination', NULL, NULL, 2, 'both', 'bard 2, cleric/oracle 3, inquisitor 3, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2, spiritualist 3, witch 3; Domain travel 2; Subdomain thievery 3; Mystery lore 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'circle, centered on you, with a radius of 400 ft. + 40 ft./level', NULL, '1 min./level', 'none', 'no', 'You sense the direction of a well-known or clearly visualized object. You can search for general items, in which case you locate the nearest of its kind if more than one is within range. Attempting to find a certain item requires a specific and accurate mental image; if the image is not close enough to the actual object, the spell fails. You cannot specify a unique item unless you have observed that particular item firsthand (not through divination).', NULL, NULL, true, false),
  ('locate_portal', 'Locate Portal', 'divination', NULL, NULL, 1, 'both', 'bard 2, cleric 2, druid 2, psychic 2, ranger 1, shaman 2, sorcerer/wizard 2, summoner 2, witch 2', '1 standard action', '1 mile/level', NULL, 'circle, centered on you, with a radius of 1 mile/level', NULL, 'concentration, up to 1 minute/level', NULL, NULL, 'When this spell is active, you feel a mental pull in the direction of any active or operable portal leading to another plane within range of the spell. If multiple portals are present, you are pulled only to the nearest one. If moving causes you to become closer to a different portal, you become drawn to that one instead. The spell gives you the direction of the portal only, not a route. Once you are within 10 feet of the portal, you no longer feel the pull, only the portal’s presence. The spell does not pinpoint or otherwise reveal hidden portals, nor does it do anything to aid in opening or operating them.', NULL, NULL, false, false),
  ('locate_weakness', 'Locate Weakness', 'divination', NULL, NULL, 2, 'both', 'bloodrager 3, inquisitor 3, magus 3, occultist 3, psychic 3, ranger 2, sorcerer/wizard 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You can sense your foes’ weak points, granting you greater damage with critical hits. Whenever you score a critical hit, roll the attack’s damage dice (but not extra or precision damage dice) twice and take the highest result.', 'a pickled predator’s eye', NULL, true, false),
  ('lock_gaze', 'Lock Gaze', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'bard 1, inquisitor 1, magus 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You compel the target to look at you and only you for the spell’s duration or until the spell is discharged. While staring at you, the target is considered to be averting its eyes from every creature but you, granting creatures other than you concealment against the target’s attacks. If the target willingly leaves your line of sight, it is blinded for 1 round and the spell ends. If you willingly leave the target’s line of sight or become unconscious or dead, the spell creature suffers no ill effects. Blind creatures and creatures immune to gaze attacks are immune to this spell.', NULL, NULL, false, false),
  ('lockjaw', 'Lockjaw', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, ranger 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level', 'Fortitude negates (harmless)', 'yes (harmless)', 'You give a creature the ability to use one of its natural attacks to firmly attach itself to an opponent. Choose one of the creature’s natural attacks (usually a claw or bite attack). The creature gains the grab ability with that natural attack, including the +4 bonus on combat maneuver checks to start or maintain a grapple. A creature with multiple natural attacks can strike at its grappled opponent with its other natural attacks, but cannot attack any other creature.', 'sticky tree gum', NULL, false, false),
  ('locksight', 'Locksight', 'divination', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, bard 1, inquisitor 1, sorcerer/wizard 1', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'The target can observe for 1 full round a lock that he is aware of (or object that includes a lock, such as a chest or door) that is within 60 feet to automatically determine whether it is open, closed, or jammed.', 'a small key', NULL, true, false),
  ('long_arm', 'Long Arm', 'transmutation', NULL, NULL, 1, 'arcane', 'alchemist 1, bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'Your arms temporarily grow in length, increasing your reach with those limbs by 5 feet.', NULL, NULL, false, false),
  ('longshot', 'Longshot', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, antipaladin 1, inquisitor 1, magus 1, paladin 1, psychic 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'This spell reduces the effect of range, granting a +10-foot bonus to the range increment of any weapon used by the subject.', 'a piece of fletching', NULL, true, false),
  ('longstrider', 'Longstrider', 'transmutation', NULL, NULL, 1, 'divine', 'druid 1, ranger 1; Domain travel 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 hour/level (D)', NULL, NULL, 'This spell gives you a +10 foot enhancement bonus to your base speed. It has no effect on other modes of movement, such as burrow, climb, fly, or swim.', 'a pinch of dirt', NULL, false, false),
  ('lose_the_trail', 'Lose the Trail', 'illusion', 'glamer', NULL, 1, 'both', 'antipaladin 2, ranger 1, sorcerer/wizard 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The target or targets of this spell can obscure their tracks when fleeing from a pursuer. This increases the DC of any Survival checks made to track the spell’s targets by 2 per level of the caster.', NULL, NULL, false, false),
  ('lost_legacy', 'Lost Legacy', 'enchantment', NULL, 'curse, mind-affecting', 6, 'both', 'bard 6, cleric 7, inquisitor 6, occultist 6, psychic 7, sorcerer/wizard 7, witch 6', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'permanent', 'Will negates', 'yes', 'You inflict a powerful curse on a touched creature that causes others to quickly forget positive aspects of their interactions with the target. The target cannot attempt a Diplomacy (or wild empathy or similar ability) check to improve the attitude of other creatures. Any creature that normally has an attitude of friendly or helpful toward the target must succeed at a Will save at the spell’s normal saving throw DC each time it interacts with the target, or its attitude becomes indifferent. Once this curse is removed, creatures coming back into contact with the target regain their pleasant memories of it. If their attitudes toward the target have not been reduced from indifferent, their original attitudes are restored.', NULL, NULL, true, false),
  ('lost_locale_samsaran', 'Lost Locale (Samsaran)', 'enchantment', 'compulsion', 'mind-affecting', 9, 'arcane', 'psychic 9, sorcerer/wizard 9', '24 hours', '1 mile/level', NULL, 'one 1-mile cube/level', NULL, NULL, NULL, NULL, 'This spell functions as lost passage (see below), except that it affects a larger area.', NULL, NULL, false, false),
  ('lost_passage_samsaran', 'Lost Passage (Samsaran)', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'bard 4, mesmerist 3, psychic 4, sorcerer/wizard 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'one 30-ft. cube/level (S)', NULL, '2 hours/level (D)', 'Will partial', 'yes', 'Creatures in the area of this spell are subject to a subtle enchantment that confounds their senses of direction, interferes with recognizing landmarks, and causes them to misjudge distances and angles. Creatures that enter the area must succeed at a new Survival check to avoid becoming lost immediately, whether or not they succeed at their saving throws. Those that fail the save take a penalty on such Survival checks equal to double your caster level, treat all squares they enter as difficult terrain for as long as they are in the area and for 1 hour per caster level thereafter, lose the benefit of all effects that allow them to ignore difficult terrain, and take a –4 penalty to Dexterity.', NULL, NULL, false, false),
  ('lover_s_vengeance', 'Lover’s Vengeance', 'enchantment', 'compulsion', 'mind-affecting', 3, 'both', 'bard 3, cleric/oracle 3, shaman 3, sorcerer/wizard 3, witch 3', '1 minute', 'touch', 'creature touched', NULL, NULL, 'up to 1 day/level (D) or until discharged', 'Will negates (harmless)', 'yes (harmless)', 'You inspire yourself or a lover to a vengeful rage against a chosen enemy, who must be a creature that has wronged you in some way.', 'a piece of jewelry worth at least 100 gp', NULL, false, true),
  ('lucky_number', 'Lucky Number', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, cleric 1, druid 1, inquisitor 1, paladin 1, sorcerer/wizard 1, summoner 1, witch 1', '1 standard action', 'touch', 'one willing creature', NULL, NULL, '24 hours or until discharged', 'none', 'no', 'The Path of Numbers', NULL, NULL, false, false),
  ('lullaby', 'Lullaby', 'enchantment', 'compulsion', 'mind-affecting', 0, 'arcane', 'bard 0, psychic 0', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, 'living creatures within a 10-ft.-radius burst', NULL, 'concentration + 1 round/level (D)', 'Will negates', 'yes', 'Any creature within the area that fails a Will save becomes drowsy and inattentive, taking a -5 penalty on Perception checks and a -2 penalty on Will saves against sleep effects while the lullaby is in effect. Lullaby lasts for as long as the caster concentrates, plus up to 1 round per caster level thereafter.', NULL, NULL, false, false),
  ('lunar_veil', 'Lunar Veil', 'illusion', 'shadow', 'darkness, shadow', 7, 'both', 'cleric/oracle 7, sorcerer/wizard 7, witch 7; Mystery lunar 7', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, '120-ft.-radius emanation', NULL, '10 minute/level', 'Will negates, see text', 'no', 'You conjure a tremendous area of shadow to obscure moonlight within the area, creating something akin to a lunar eclipse. The light level is lowered by two steps (though unlike deeper darkness, areas of normal light or dimmer become normal darkness rather than supernaturally dark). Lycanthropes in the area must make a Will save every round or revert to their humanoid forms. In addition, lycanthropes attempting to assume animal or hybrid form within the affected area take a –5 penalty on Constitution checks to do so.', NULL, NULL, false, false),
  ('mad_hallucination', 'Mad Hallucination', 'illusion', 'phantasm', NULL, 2, 'arcane', 'bard 2, mesmerist 2, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (20 ft.)', 'one humanoid creature', NULL, NULL, '5 minute/level (maximum 1 hour)', 'Will negates', 'yes', 'This spell induces a hallucinogenic reality in the mind of your target. Surfaces seem to swim, and movement constantly distracts the eye. The target takes a –2 penalty on Will saving throws, caster level checks, Intelligence-based skill checks, and Wisdom-based skill checks.', NULL, NULL, false, false),
  ('mad_monkeys', 'Mad Monkeys', 'conjuration', 'summoning', NULL, 3, 'both', 'bard 3, druid 3, sorcerer/wizard 3, summoner/unchained summoner 3', '1 round', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'swarm of monkeys', '1 round/level', 'none', 'no', 'You summon a swarm of screeching, mischievous monkeys. The swarm understands and obeys your commands and has the statistics of a monkey swarm. Creatures failing a saving throw against the mad monkeys’ distraction attack are deafened for 1 minute as well as nauseated. The monkeys attempt one disarm or steal combat maneuver each turn as a free action against any creature that begins its turn in the swarm, using your caster level plus your casting ability score bonus (Intelligence for wizards; Wisdom for druids and oracles; Charisma for bards, sorcerers, and summoners) for its CMB. Recovering an item from the monkeys requires a successful disarm or steal attempt against that CMB +10. An object stolen by the monkeys takes swarm damage each round the swarm is in possession of the object.', NULL, NULL, true, false),
  ('mad_sultan_s_melody', 'Mad Sultan’s Melody', 'enchantment', 'compulsion', 'mind-affecting, sonic', 3, 'arcane', 'bard 3, mesmerist 4, occultist 4, psychic 4, sorcerer/wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature/2 levels, no two of which may be more than 30 ft. apart (see text)', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You imitate the mad cacophony created by the awful beings associated with the Outer God, Azathoth. This spell targets only creatures with the ooze type, creatures with the amorphous special ability, and non-bipedal creatures with a special association with the Outer Gods. This music draws the targets’ attention to the caster, as per the fascinate bardic performance. It affects mindless creatures despite the mindless quality typically granting immunity to mind-affecting effects, though it doesn’t ignore any other immunity to mind-affecting effects the creature might have. The caster doesn’t have to maintain the effect each round—the music continues for the duration of the spell. Creatures fascinated by mad sultan’s melody become immune to any other casting of the spell for 24 hours after the spell ends, and the spell ends if the fascination breaks on any of its targets for any reason (such as an attack).', NULL, 'masterwork flute, pipe, or string instrument', false, false),
  ('maddening_oubliette', 'Maddening Oubliette', 'conjuration', 'teleportation', NULL, 7, 'both', 'cleric/oracle 7, sorcerer/wizard 7, witch 7', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'special; see text', 'Will negates; see text', 'yes', 'The target is transported to a dark and dank prison in some unspecified horrific demiplane, where tentacles writhe around, clawed fingers grab at the creature (though they deal no damage), and harsh, whispering voices speak blasphemies and maddening secrets. At the end of each round within this terrifying oubliette, the target can attempt a Will saving throw in order to escape the prison. The saving throw has a penalty equal to the number of rounds the target has spent in the oubliette (minimum –1 and maximum –5). If the target succeeds at its saving throw, it returns to its former space. If that space is occupied or otherwise unavailable, the target is shunted to the nearest available space. When the target returns from the oubliette, it is confused for a number of rounds equal to the number of rounds of imprisonment (minimum 1), unless it was confined in the oubliette for 10 or more rounds, in which case the target is affected as if it were subject to an insanity spell instead.', 'the powdered bones of a creature that died in prison', NULL, false, false),
  ('mage_armor', 'Mage Armor', 'conjuration', 'creation', 'force', 1, 'arcane', 'bloodrager 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1; Bloodline draconic 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level (D)', 'Will negates (harmless)', 'no', 'An invisible but tangible field of force surrounds the subject of a mage armor spell, providing a +4 armor bonus to AC.', NULL, 'a piece of cured leather', false, false),
  ('mage_hand', 'Mage Hand', 'transmutation', NULL, NULL, 0, 'arcane', 'bard 0, magus 0, psychic 0, sorcerer/wizard 0, summoner/unchained summoner 0', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one non-magical, unattended object weighing up to 5 lbs.', NULL, NULL, 'concentration', 'none', 'no', 'You point your finger at an object and can lift it and move it at will from a distance. As a move action, you can propel the object as far as 15 feet in any direction, though the spell ends if the distance between you and the object ever exceeds the spell’s range.', NULL, NULL, false, false),
  ('mage_s_crawl_space', 'Mage’s Crawl Space', 'transmutation', NULL, NULL, 2, 'both', 'arcanist 2, bard 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'personal', NULL, NULL, '5-foot sphere centered on yourself', '1 hour/level (D)', 'none', 'no', 'When you cast this spell, you merge with an adjacent natural stone surface, forming a 5-foot pocket within. If the stone surface does not have enough volume to safely contain a 5-foot sphere of empty space, the spell fails. When created, there is sufficient air within the pocket for up to one Medium creature to survive for the spell’s duration, including one additional Tiny or smaller creature, such as a familiar. At the end of the spell’s duration, you are immediately expelled into the nearest available open space adjacent to the surface you merged with.', 'a piece of clay', NULL, false, false),
  ('mage_s_decree', 'Mage’s Decree', 'evocation', NULL, NULL, 5, 'both', 'bard 5, cleric 6, inquisitor 5, mesmerist 5, psychic 6, sorcerer/wizard 6, summoner 5, witch 6', '1 standard action', 'up to 1 mile/level; see text', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'You speak a short message (up to 25 words), and it is immediately transmitted to each target, who hear it as clearly as if you were standing next to them. By default, the spell targets every creature with an Intelligence score of 3 or greater that is within the spell’s range, but at your discretion, you can choose to restrict the spell to certain creatures, causing it to either only deliver its message to creatures meeting a certain criteria, or to deliver it to all creatures except those meeting that criteria.', NULL, 'a brass cone or trumpet', false, false),
  ('mage_s_disjunction', 'Mage’s Disjunction', 'abjuration', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Domain magic 9; Elemental School void 9; Mystery spellscar 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'all magical effects and magic items within a 40-ft.-radius burst, or one magic item (see text)', NULL, '1 minute/level', 'Will negates (object)', 'no', 'All magical effects and magic items within the radius of the spell, except for those that you carry or touch, are disjoined. That is, spells and spell-like effects are unraveled and destroyed completely (ending the effect as a dispel magic spell does), and each permanent magic item must make a successful Will save or be turned into a normal item for the duration of this spell. An item in a creature’s possession uses its own Will save bonus or its possessor’s Will save bonus, whichever is higher. If an item’s saving throw results in a natural 1 on the die, the item is destroyed instead of being suppressed.', NULL, NULL, false, false),
  ('mage_s_faithful_hound', 'Mage’s Faithful Hound', 'conjuration', 'creation', NULL, 4, 'arcane', 'sorcerer/wizard 5, summoner 4, unchained summoner 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'phantom watchdog', '1 hour/caster level or until discharged, then 1 round/caster level; see text', 'none', 'no', 'You conjure up a phantom watchdog that is invisible to everyone but yourself. It then guards the area where it was conjured (it does not move). The hound immediately starts barking loudly if any Small or larger creature approaches within 30 feet of it. (Those within 30 feet of the hound when it is conjured may move about in the area, but if they leave and return, they activate the barking.) The hound sees invisible and ethereal creatures. It does not react to figments, but it does react to shadow illusions.', 'a tiny silver whistle, a piece of bone, and a thread', NULL, false, false),
  ('mage_s_lucubration', 'Mage’s Lucubration', 'transmutation', NULL, NULL, 6, 'arcane', 'wizard 6; Elemental School void 6', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You instantly prepare any one spell of 5th level or lower that you have used during the past 24 hours. The spell must have been actually cast during that period. The chosen spell is stored in your mind as through prepared in the normal fashion.', NULL, NULL, false, false),
  ('mage_s_magnificent_enclosure', 'Mage’s Magnificent Enclosure', 'abjuration', 'force', NULL, 9, 'arcane', 'sorcerer/wizard 9', '1 standard action', 'touch', NULL, 'immobile 10-ft.-radius emanation', NULL, '1 round/level (D)', 'none', 'see text', 'You call into being around you an invisible barrier of force within which magic cannot persist.', 'a sphere of glass worth 100 gp and an iron nail, with which you pierce the glass on casting', NULL, false, true),
  ('mage_s_magnificent_mansion', 'Mage’s Magnificent Mansion', 'conjuration', 'creation', NULL, 8, 'arcane', 'sorcerer/wizard 7; Mystery streets 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'extra-dimensional mansion, up to three 10-ft. cubes/level (S)', '2 hours/level (D)', 'none', 'no', 'You conjure up an extra-dimensional dwelling that has a single entrance on the plane from which the spell was cast. The entry point looks like a faint shimmering in the air that is 4 feet wide and 8 feet high. Only those you designate may enter the mansion, and the portal is shut and made invisible behind you when you enter. You may open it again from your own side at will. Once observers have passed beyond the entrance, they are in a magnificent foyer with numerous chambers beyond. The atmosphere is clean, fresh, and warm.', NULL, 'a miniature ivory door, a piece of polished marble, and a silver spoon, each worth 5 gp', false, true),
  ('mage_s_perusal', 'Mage’s Perusal', 'divination', NULL, NULL, 1, 'both', 'bard 1, cleric 1, magus 1, sorcerer/ wizard 1', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You gain a brief but incomplete understanding of one book’s contents, equivalent to having skimmed its pages for 1 hour. This insight is not sufficient to translate unknown languages, decipher codes, or memorize text, but it does allow the caster to learn what topics the book discusses— invaluable to an adventurer who must make a snap decision when performing research or deciding whether or not to abscond with a volume. In addition, you instantly benefit from any bonuses or effects the book would normally grant to anyone who reads it for 1 hour.', NULL, NULL, false, false),
  ('mage_s_private_sanctum', 'Mage’s Private Sanctum', 'abjuration', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, '30-ft. cube/level (S)', NULL, '24 hours (D)', 'none', 'no', 'This spell ensures privacy. Anyone looking into the area from outside sees only a dark, foggy mass. Darkvision cannot penetrate it. No sounds, no matter how loud, can escape the area, so nobody can eavesdrop from outside. Those inside can see out normally.', 'a sheet of lead, a piece of glass, a wad of cotton, and powdered chrysolite', NULL, false, false),
  ('mage_s_sword', 'Mage’s Sword', 'evocation', NULL, 'force', 7, 'arcane', 'sorcerer/wizard 7', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one sword', '1 round/level (D)', 'none', 'yes', 'This spell brings into being a shimmering, sword-like plane of force. The sword strikes at any opponent within its range, as you desire, starting in the round that you cast the spell. The sword attacks its designated target once each round on your turn. Its attack bonus is equal to your caster level + your Intelligence bonus or your Charisma bonus (for wizards or sorcerers, respectively) with an additional +3 enhancement bonus. As a force effect, it can strike ethereal and incorporeal creatures. It deals 4d6+3 points of force damage, with a threat range of 19–20 and a critical multiplier of ×2.', NULL, 'a miniature platinum sword worth 250 gp', false, true),
  ('magic_army', 'Magic Army', 'transmutation', NULL, NULL, 7, 'both', 'shaman 8, sorcerer/wizard 7', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, '1 hour/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You imbue all manufactured weapons carried by allies within range with magic, granting each weapon a +1 enhancement bonus on attack rolls and damage rolls per 5 caster levels (maximum +4).', NULL, NULL, true, false),
  ('magic_aura', 'Magic Aura', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1; Subdomain arcane 1', '1 standard action', 'touch', 'one touched object weighing up to 5 lbs./level', NULL, NULL, '1 day/level (D)', 'none; see text', 'no', 'You alter an item’s aura so that it registers to detect spells (and spells with similar capabilities) as though it were non-magical, or a magic item of a kind you specify, or the subject of a spell you specify. If the object bearing magic aura has identify cast on it or is similarly examined, the examiner recognizes that the aura is false and detects the object’s actual qualities if he succeeds on a Will save. Otherwise, he believes the aura and no amount of testing reveals what the true magic is.', NULL, 'a small square of silk that must be passed over the object that receives the aura', false, false),
  ('magic_boulder', 'Magic Boulder', 'transmutation', NULL, 'earth', 2, 'divine', 'cleric 2, druid 2 Target up to three boulders touched', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell works like magic stone, except you transmute as many as three boulders (rocks up to two size categories smaller than yourself) to use with the rock throwing ability or as siege engine ammunition. The boulder’s damage increases by one step, and the boulder gains a +1 enhancement bonus on attack and damage rolls.---', NULL, NULL, false, false),
  ('magic_circle_against_chaos', 'Magic Circle against Chaos', 'abjuration', NULL, 'lawful', 3, 'both', 'cleric/oracle 3, inquisitor 3, paladin 3, shaman 3, sorcerer/wizard 3, summoner/unchained summoner 3; Domain law 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like magic circle against evil, except that it is similar to protection from chaos instead of protection from evil, and it can imprison a non-lawful called creature.', NULL, NULL, false, false),
  ('magic_circle_against_evil', 'Magic Circle against Evil', 'abjuration', NULL, 'good', 3, 'both', 'cleric/oracle 3, inquisitor 3, paladin 3, shaman 3, sorcerer/wizard 3, summoner/unchained summoner 3; Domain good 3; Bloodline celestial 3', '1 standard action', 'touch', NULL, NULL, NULL, '10 min./level', 'Will negates (harmless)', 'no; see text', 'All creatures within the area gain the effects of a protection from evil spell, and evil summoned creatures cannot enter the area either. Creatures in the area, or who later enter the area, receive only one attempt to suppress effects that are controlling them. If successful, such effects are suppressed as long as they remain in the area. Creatures that leave the area and come back are not protected. You must overcome a creature’s Spell Resistance in order to keep it at bay (as in the third function of protection from evil), but the deflection and resistance bonuses and the protection from mental control apply regardless of enemies’ Spell Resistance.', 'a 3-ft.-diameter circle of powdered silver', NULL, true, false),
  ('magic_circle_against_good', 'Magic Circle against Good', 'abjuration', NULL, 'evil', 3, 'both', 'antipaladin 3, cleric/oracle 3, inquisitor 3, shaman 3, sorcerer/wizard 3, summoner/unchained summoner 3; Domain evil 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like magic circle against evil, except that it is similar to protection from good instead of protection from evil, and it can imprison a non-evil called creature.', NULL, NULL, false, false),
  ('magic_circle_against_law', 'Magic Circle against Law', 'abjuration', NULL, 'chaotic', 3, 'both', 'antipaladin 3, cleric/oracle 3, inquisitor 3, shaman 3, sorcerer/wizard 3, summoner/unchained summoner 3; Domain chaos 3', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like magic circle against evil, except that it is similar to protection from law instead of protection from evil, and it can imprison a non-chaotic called creature.', NULL, NULL, false, false),
  ('magic_circle_against_technology', 'Magic Circle Against Technology', 'abjuration', NULL, NULL, 4, 'both', 'cleric 4, sorcerer/wizard 4', '1 standard action', 'touch', NULL, '10-ft.-radius emanation from touched creature', NULL, '10 minute/level', 'Will negates (harmless), see text', 'no; see text', 'All creatures within the area gain the effects of a protection from technology spell. Creatures in the area, or that later enter the area, receive only one attempt to suppress technological effects that are controlling them. If a creature succeed at this save, such effects are suppressed as long as the creature remains in the area. Creatures that leave the area and then return are not protected. Robots receive a saving throw and spell resistance to avoid being kept at bay, but the deflection and resistance bonuses and the protection from mental control apply to non-technological creatures in the area even if a robot succeeds at its saving throw and is thus able to enter the area.', 'a 3-ft.-diameter circle of powdered copper', NULL, true, false),
  ('magic_fang', 'Magic Fang', 'transmutation', NULL, NULL, 1, 'both', 'druid 1, ranger 1, summoner/unchained summoner 1; Domain scalykind 1; Subdomain cannibalism 1, fur 1', '1 standard action', 'touch', 'living creature touched', NULL, NULL, '1 min./level', 'Will negates (harmless)', 'yes (harmless)', 'Magic fang gives one natural weapon or unarmed strike of the subject a +1 enhancement bonus on attack and damage rolls. The spell can affect a slam attack, fist, bite, or other natural weapon. The spell does not change an unarmed strike’s damage from nonlethal damage to lethal damage.', NULL, NULL, true, false),
  ('magic_jar', 'Magic Jar', 'necromancy', NULL, NULL, 4, 'arcane', 'alchemist 5, sorcerer/wizard 5, summoner 4, unchained summoner 5, witch 5; Mystery juju(PAP39/PZO9039) 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 hour/level or until you return to your body', 'Will negates; see text', 'yes', 'By casting magic jar, you place your soul in a gem or large crystal (known as the magic jar), leaving your body lifeless. Then you can attempt to take control of a nearby body, forcing its soul into the magic jar. You may move back to the jar (thereby returning the trapped soul to its body) and attempt to possess another body. The spell ends when you send your soul back to your own body, leaving the receptacle empty. To cast the spell, the magic jar must be within spell range and you must know where it is, though you do not need line of sight or line of effect to it. When you transfer your soul upon casting, your body is, as near as anyone can tell, dead.', NULL, 'a gem or crystal worth at least 100 gp', false, true),
  ('magic_missile', 'Magic Missile', 'evocation', NULL, 'force', 1, 'arcane', 'bloodrager 1, magus 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'instantaneous', 'none', 'yes', 'A missile of magical energy darts forth from your fingertip and strikes its target, dealing 1d4+1 points of force damage.', NULL, NULL, false, false),
  ('magic_mouth', 'Magic Mouth', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, medium 2, mesmerist 1, occultist 2, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 1; Domain magic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature or object', NULL, NULL, 'permanent until discharged', 'Will negates (object)', 'yes (object)', 'This spell imbues the chosen object or creature with an enchanted mouth that suddenly appears and speaks its message the next time a specified event occurs. The message, which must be 25 or fewer words long, can be in any language known by you and can be delivered over a period of 10 minutes. The mouth cannot utter verbal components, use command words, or activate magical effects. It does, however, move according to the words articulated; if it were placed upon a statue, the mouth of the statue would move and appear to speak. Magic mouth can also be placed upon a tree, rock, or any other object or creature.', 'a small bit of honeycomb and jade dust worth 10 gp', NULL, false, true),
  ('magic_siege_engine', 'Magic Siege Engine', 'transmutation', NULL, NULL, 2, 'both', 'antipaladin 2, cleric 2, inquisitor 2, paladin 2, sorcerer/wizard 2', '1 standard action', 'touch', 'one siege engine touched', NULL, NULL, '1 minutes/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'This spell permits an indirect fire siege engine to bombard its targets with greater accuracy, delivering more damage. The siege weapon receives a +1 enhancement bonus on targeting rolls and damage rolls. If used on a direct fire siege weapon, this spell acts a magic weapon.', NULL, NULL, true, false),
  ('magic_stone', 'Magic Stone', 'transmutation', NULL, NULL, 1, 'divine', 'cleric/oracle 1, druid 1, shaman 1; Domain earth 1; Mystery stone 1', '1 standard action', 'touch', NULL, NULL, NULL, '30 minutes or until discharged', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You transmute as many as three pebbles, which can be no larger than sling bullets, so that they strike with great force when thrown or slung. If hurled, they have a range increment of 20 feet. If slung, treat them as sling bullets (range increment 50 feet). The spell gives them a +1 enhancement bonus on attack and damage rolls. The user of the stones makes a normal ranged attack. Each stone that hits deals 1d6+1 points of damage (including the spell’s enhancement bonus), or 2d6+2 points against undead.', NULL, NULL, true, false),
  ('magic_vestment', 'Magic Vestment', 'transmutation', NULL, NULL, 3, 'divine', 'cleric/oracle 3, inquisitor 3, shaman 3; Domain nobility 3, strength 3, war 3; Mystery battle 3', '1 standard action', 'touch', 'armor or shield touched', NULL, NULL, '1 hour/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You imbue a suit of armor or a shield with an enhancement bonus of +1 per four caster levels (maximum +5 at 20th level).', NULL, NULL, true, false),
  ('magic_weapon', 'Magic Weapon', 'transmutation', NULL, NULL, 1, 'both', 'antipaladin 1, bloodrager 1, cleric/oracle 1, inquisitor 1, magus 1, paladin 1, shaman 1, sorcerer/wizard 1; Domain war 1; Elemental School metal 1', '1 standard action', 'touch', 'weapon touched', NULL, NULL, '1 min./level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'Magic weapon gives a weapon a +1 enhancement bonus on attack and damage rolls. An enhancement bonus does not stack with a masterwork weapon’s +1 bonus on attack rolls.', NULL, NULL, true, false),
  ('magical_beast_shape', 'Magical Beast Shape', 'transmutation', 'polymorph', NULL, 7, 'arcane', 'sorcerer/wizard 7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as beast shape IV except you can assume the form of only a magical beast of a size between Diminutive and Huge. If the form you assume has any of the following abilities, you gain those abilities: burrow speed 60 feet, climb speed 90 feet, fly speed 120 feet (good maneuverability), swim speed 120 feet, blindsense 60 feet, blindsight 30 feet, darkvision 90 feet, low-light vision, scent, see in darkness, tremorsense 60 feet, blood drain, blood frenzy, breath weapon (if damage, up to 12d6 points), constrict, fast healing 5, ferocity, grab, hold breath, jet, no breath, poison, pounce, powerful charge, pull, rake, rend, roar, spikes, trample, trip, and web. If the creature has immunity to poison, you gain a +8 resistance bonus on saves against poison.', NULL, NULL, false, false),
  ('magnetic_field', 'Magnetic Field', 'abjuration', NULL, NULL, 6, 'both', 'alchemist 6, cleric 7, magus 6, sorcerer/wizard 7, summoner 6, witch 7', '1 standard action', '30 ft.', NULL, '30-ft.-radius emanation', NULL, '1 round/2 levels (D)', 'Reflex negates (object; see text)', 'yes (object)', 'You create a spherical magnetic field that surrounds you to a range of 30 feet and follows you for the duration of the spell.', NULL, NULL, false, false),
  ('magnifying_chime', 'Magnifying Chime', 'transmutation', NULL, 'sonic', 6, 'arcane', 'bard 6', '10 minutes', 'touch', 'one unattended object or object in your possession', NULL, 'disruptive vibrations Target one unattended object or object in your possession', '1 round/level', 'Fortitude half (see text)', 'yes', 'You cause the touched object to vibrate and release sonic energy once per round as a loud, dangerous chime. The sound grows in strength as time passes. On your turn in the round after you cast the spell, the chime deals 1d6 points of sonic damage to all creatures and objects within 5 feet of the target. Each round after that, the damage increases by 1d6 and reaches 5 feet farther in all directions. A successful Fortitude save halves the damage for that round only.', NULL, NULL, false, false),
  ('majestic_image', 'Majestic Image', 'transmutation', NULL, NULL, 4, 'both', 'bard 4, cleric 4, medium 4, mesmerist 4, occultist 4, sorcerer/wizard 4, spiritualist 4', '1 standard action', '200 ft./level', NULL, NULL, 'transfer consciousness to an object bearing your likeness', 'concentration', 'Will negates (see text)', 'yes', 'You cast your consciousness into a single object within range that bears your likeness, as if choosing a specific image with the spell enter image. In addition to observing your surroundings, speaking, and manipulating the image you inhabit, however, you can converse with nearby creatures and use your normal social skills.', 'a drop of paint and a ball of clay', NULL, false, false),
  ('major_creation', 'Major Creation', 'conjuration', 'creation', NULL, 4, 'arcane', 'sorcerer/wizard 5, summoner/unchained summoner 4, witch 5; Domain artifice 6; Subdomain flotsam 5; Elemental School metal 5, void 5; Mystery metal 5', NULL, 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'see text', NULL, NULL, 'This spell functions like minor creation, except that you can also create an object of mineral nature: stone, crystal, metal, or the like. The duration of the created item varies with its relative hardness and rarity, as indicated on the following table.', NULL, NULL, false, false),
  ('major_image', 'Major Image', 'illusion', 'figment', NULL, 3, 'arcane', 'bard 3, magus 3, medium 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3; Subdomain imagination 3; Mystery whimsy 4', NULL, NULL, NULL, NULL, NULL, 'Concentration +3 rounds', NULL, NULL, 'This spell functions like silent image, except that sound, smell, and thermal illusions are included in the spell effect. While concentrating, you can move the image within the range.', NULL, NULL, false, false),
  ('major_phantom_object', 'Major Phantom Object', 'illusion', 'shadow', 'shadow', 5, 'arcane', 'sorcerer/wizard 5', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'illusory, unattended, non-magical object, up to 1 cu. ft./level', '10 minutes/level (D)', 'Will negates', 'yes', 'This spell functions as the major creation spell, except as noted above and the object created is a semi-real illusion. Any creature that interacts with the object may make a Will save, with success causing the object to cease to exist. A gnome casting this spell may make a Spellcraft check in place of any Craft check required to make a complex item.', NULL, NULL, false, false),
  ('make_lost', 'Make Lost', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'bard 2, druid 2, ranger 1', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature/level, no two of which can be more than 30 ft. apart', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You strip the targets of their senses of direction and recent memories of travel. They immediately forget the route they took in the last hour (but not details of encounters along the way) and become lost.', NULL, NULL, false, false),
  ('make_whole', 'Make Whole', 'transmutation', NULL, NULL, 2, 'both', 'cleric/oracle 2, occultist 2, psychic 2, sorcerer/wizard 2; Subdomain flotsam 2; Elemental School metal 2', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', 'one object of up to 10 cu. ft./level or one construct creature of any size', NULL, NULL, 'instantaneous', NULL, NULL, 'This spell functions as mending, except that it repairs 1d6 points of damage per level when cast on an object or construct creature (maximum 5d6).', NULL, NULL, false, false),
  ('malediction', 'Malediction', 'necromancy', NULL, 'curse, evil', 4, 'both', 'antipaladin 4, cleric 4, shaman 4, spiritualist 4, witch 4', '1 standard action', 'touch', '1 creature touched', NULL, NULL, '1 minute and instantaneous (see text)', 'Will negates', 'yes', 'Channeling the blasphemy of fiends into your hand, you mark your target with a brief but fundamental corruption, causing its soul to be irretrievably damned should it die within the next minute. If you are lawful evil, souls are sent to Hell. If you are neutral evil, souls are sent to Abaddon. If you are chaotic evil, souls are sent to the Abyss.', NULL, NULL, false, false),
  ('malediction_pzo9213', 'Malediction (PZO9213)', 'necromancy', NULL, 'evil', 4, 'divine', 'cleric/oracle 4', '1 standard action', 'touch', '1 creature touched', NULL, NULL, '1 minute and instantaneous (see text)', 'Will negates', 'yes', 'Channeling the blasphemy of the Pit into your hand, you mark your target with a brief but fundamental corruption, causing its soul to be irretrievably damned to Hell should it die within the next minute. Those killed while under the effect of this spell cannot be resurrected by normal means. Only a worshiper of Asmodeus (or of your deity, if you are not a worshiper of the Prince of Darkness) can return a soul damned by malediction to life. Spells like raise dead or resurrection cast by the worshipers of other deities automatically fail, though they do reveal that the target soul has met a perhaps undeserved torment in Hell. The spells miracle or wish return the victim of a malediction to life, regardless of the caster’s deity.', NULL, NULL, false, false),
  ('malfunction', 'Malfunction', 'transmutation', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4; Elemental School metal 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one construct', NULL, '1 round/level (D)', 'Fortitude negates', 'yes', 'This functions as confusion, except it only affects constructs, and instead of babbling incoherently, the construct takes no actions on its turn (but may still make attacks of opportunity).', NULL, NULL, false, false),
  ('malicious_spite', 'Malicious Spite', 'enchantment', 'compulsion', 'emotion, mind-affecting', 3, 'arcane', 'bard 3, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You invoke feelings of a driving malicious intent. The target’s malice is directed at a second individual as designated by you at the time of casting. Thereafter, the target attempts to slander, abuse, and even plot murder against the target of its spite. This loathing is not overt, and the target’s actions against the object of its spite remain subtle and indirect. The enchanted target remains within its financial and ethical means when acting against the second individual, though the malice toward this other person pushes the target to the limit of what it would do to a hated individual.', 'powdered turquoise worth 150 gp', NULL, false, true),
  ('mantle_of_calm', 'Mantle of Calm', 'enchantment', 'compulsion', 'emotion, mind-affecting', 2, 'both', 'cleric 3, inquisitor 3, mesmerist 2, paladin 3, psychic 3, shaman 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', 'none and Will negates (see text)', 'no and yes (see text)', 'You surround yourself with a mantle of calm serenity. You take a –2 penalty on attack rolls, and opponents gain a +2 bonus on saving throws against spells you cast. Any creature affected by a rage effect (barbarian’s rage, bloodrager‘s bloodrage, blood rage monster ability, rage spell, skald’s inspired rage raging song, and so on) that strikes you with a melee attack must attempt a Will saving throw, without the rage effect’s bonus to Will; failure means the rage effect ends (as if it were dispelled or the creature voluntarily ended it, as appropriate).', NULL, NULL, true, false),
  ('mantle_of_doubt', 'Mantle of Doubt', 'illusion', 'phantasm', 'emotion, fear, mind-affecting', 6, 'arcane', 'mesmerist 6, psychic 8', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You wrap your mind in phantasms of crippling doubt that assail any who dare harm you. When a creature within the mantle’s radius attacks you or attempts to affect you with a harmful effect, it must succeed at a Will save as these spectres of uncertainty force themselves into its mind. Ongoing effects trigger the mantle only if the creature consciously directs them against you. A given creature need only roll a saving throw against your mantle of doubt at most once per round. If the creature’s attack or effect against you was a psychic spell or spell-like ability, that creature’s save takes a –4 penalty. A creatures that fails its save against your mantle of doubt is affected for 1d4+1 rounds, during which time it is shaken, cannot flank, and no longer threatens creatures within its reach. In addition, it takes a –2 penalty on saves against mind-affecting effects, which stacks with the penalties for being shaken. If your mantle of doubt affects a creature that is already shaken, that creature’s fear level doesn’t increase. Instead, mounting doubts stagger the creature for 1 round and deal 1d4 points of Wisdom and Charisma damage to it.', NULL, NULL, false, false),
  ('mantle_of_the_magic_warriors', 'Mantle of the Magic Warriors', 'transmutation', NULL, 'good', 5, 'both', 'druid 5, shaman 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one good-aligned creature/3 levels', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'You weave golden masks shaped like animals around the targets’ faces, imbuing each target with an animal spirit that matches her strength of character. Each target gains one animal special ability of your choice granted by beast shape I. You can choose a different special ability for each target.', NULL, NULL, false, false),
  ('marching_chant', 'Marching Chant', 'transmutation', NULL, NULL, 2, 'both', 'bard 2, cleric 2', '1 minute', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'concentration', 'Will negates (harmless)', 'yes (harmless)', 'You invigorate your allies, who can hustle as long as you continue to sing or chant (which requires your concentration). This movement counts as a walk (not a hustle) for the purpose of accruing nonlethal damage and fatigue. You can concentrate on this spell and hustle at the same time.', NULL, NULL, false, false),
  ('marid_s_mastery', 'Marid’s Mastery', 'transmutation', NULL, 'water', 1, 'both', 'bloodrager 1, cleric 1, druid 1, ranger 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'willing creature touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'The target gains a +1 bonus on attack and damage rolls if it and its opponent are touching water. If the opponent or the target is touching the ground, the target takes a –4 penalty on attack and damage rolls.', NULL, NULL, false, false),
  ('marionette_possession', 'Marionette Possession', 'necromancy', NULL, NULL, 3, 'arcane', 'alchemist 3, mesmerist 3, psychic 3, sorcerer/wizard 3, summoner/unchained summoner 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one willing creature1', NULL, NULL, '10 minutes/level or until you return to your body', 'none2', 'yes', 'You project your soul out of your body and into the body of a willing creature. This possession is blocked by protection from evil or a similar ward. The target’s soul shares its body with you; it is helpless but can still use its senses. You and the target’s soul can communicate telepathically as if using a common language.', NULL, 'a piece of paper with the target’s name', false, false),
  ('mark_of_blood', 'Mark of Blood', 'transmutation', NULL, 'curse', 2, 'both', 'bloodrager 2, inquisitor 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute and permanent (see text)', 'Will negates', 'yes', 'You place a drop of your blood on a weapon and charge it with magic so that you transfer a small amount of your life essence to the next living creature you strike with the weapon. Thereafter, you can spend a move action to know the direction and general distance of that creature. The target can negate this effect with a successful Will save. You must strike a creature within 1 minute of casting this spell or the magic is wasted, but once the mark of blood takes effect it is permanent until dispelled or removed via an effect like remove curse.', 'a drop of your blood', NULL, false, false),
  ('mark_of_buoyancy', 'Mark of Buoyancy', 'transmutation', NULL, NULL, 3, 'both', 'arcanist 3, bard 3, cleric 3, magus 3, occultist 3, oracle 3, psychic 3, skald 3, sorcerer 3, summoner 3, unchained summoner 3, warpriest 3, wizard 3', '1 standard action', 'touch', 'touched object weighing up to 10 lbs./level', NULL, NULL, '1 hour/level (D)', 'Will negates (object)', 'yes (object)', 'You cause the touched object to become lighter than air, such that it floats if not weighted down. The object is effectively weightless and, if left unattended, will rise to a number of feet off the ground equal to twice your caster level, and then remain floating at that height. The object can be pushed, dragged, carried, or otherwise moved normally, and it can be carried by the wind if not held or secured. The object is buoyant enough that it can carry an additional weight of up to 10 pounds per caster level with it, potentially allowing it to be used to carry small objects or creatures.', NULL, NULL, false, false),
  ('mark_of_justice', 'Mark of Justice', 'necromancy', NULL, 'curse', 4, 'divine', 'cleric/oracle 5, inquisitor 5, paladin 4, witch 5; Subdomain judgment 5', '10 minutes', 'touch', 'creature touched', NULL, NULL, 'permanent; see text', 'none', 'yes', 'You mark a subject and state some behavior on the part of the subject that will activate the mark. When activated, the mark curses the subject. Typically, you designate some sort of undesirable behavior that activates the mark, but you can pick any act you please. The effect of the mark is identical with the effect of bestow curse.', NULL, NULL, true, false),
  ('mark_of_obvious_ethics', 'Mark of Obvious Ethics', 'divination', NULL, 'curse', 3, 'divine', 'cleric 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 day/level', 'Will negates', 'yes', 'You mark one creature with a glowing sigil. The target’s alignment must be opposite yours on at least one alignment axis—if you are neutral with no other alignment components, the target must have an alignment with no neutral component. Any creature that sees the target can attempt a DC 15 Knowledge (religion) check to discern the target’s alignment, even if the mark is covered. You are aware of the direction and distance to the target as long as it remains within 100 miles of you and on the same plane.', NULL, NULL, false, false),
  ('mark_of_spite', 'Mark of Spite', 'necromancy', NULL, NULL, 2, 'arcane', 'mesmerist 2, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature', NULL, NULL, '1 round/level', 'Fort negates', 'yes', 'You must succeed at a ranged touch attack to place your mark on the victim. While the mark remains, you may injure yourself as a standard action, dealing a number of points of damage equal to 1d8 plus your Strength modifier. The recipient of the mark automatically takes twice the amount of damage that you deal to yourself, bypassing any damage reduction, immunities, or resistances.', 'a drop of blood', NULL, false, false),
  ('mark_of_the_reptile_god', 'Mark of the Reptile God', 'transmutation', 'curse', NULL, 4, 'divine', 'antipaladin 4, cleric 4, inquisitor 4, oracle 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'permanent', 'Fort negates', 'yes', 'If you succeed at a ranged touch attack, you burn your handprint onto the flesh of a creature, dealing 1d6 points of acid damage.', NULL, NULL, true, false),
  ('marks_of_forbiddance', 'Marks of Forbiddance', 'abjuration', NULL, 'mind-affecting', 3, 'divine', 'paladin 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Will negates; see text', 'yes', 'Marks of Forbiddance magically brand two creatures, preventing them from committing violence against one another. When you cast this spell choose one enemy and one ally within range. Both targets become branded with the sigil of forbiddance. Until the end of the spell’s duration, in order for the two targets to attack one another, even with a targeted spell, each attacker must attempt a Will save. If the save succeeds, that target can attack the other normally.', NULL, NULL, false, false),
  ('martial_marionette', 'Martial Marionette', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'bard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'When you cast this spell, you take partial control of an opponent’s limbs, making it difficult for him to attack you. Any attacks made against you by the target of the spell take a –2 penalty due to the erratic and random motions the spell forces onto any efforts to strike you. In addition, any creature suffering the effects of this spell cannot flank you and cannot aid other opponents in flanking you.', 'a marionette’s crossbar', NULL, false, false),
  ('martial_telekinesis', 'Martial Telekinesis', 'evocation', NULL, NULL, 3, 'arcane', 'magus 4, occultist 4, psychic 3, sorcerer/wizard 4, spiritualist 4 Duration instantaneous', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'You mingle the power of your mind and body to exert force beyond your reach. This spell functions as the combat maneuver version of telekinesis, except as noted above. Alternatively, you can inflict a telekinetic unarmed strike with this spell, using your own unarmed strike damage and applying your primary spellcasting ability score modifier to the damage in place of your Strength modifier.', NULL, NULL, false, false),
  ('martyr_s_bargain', 'Martyr’s Bargain', 'transmutation', 'good', NULL, 2, 'divine', 'cleric 2, paladin 2', '1 immediate action', 'personal', 'you', NULL, NULL, '1 round/level', 'none', 'no', 'Among the faithful followers of the gods of purity martyr’s bargain represents true faith and true sacrifice.', NULL, NULL, false, false),
  ('mask_dweomer', 'Mask Dweomer', 'illusion', 'glamer', NULL, 1, 'arcane', 'occultist 1, psychic 1, witch 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 day/level (D)', 'none; see text', 'no', 'You mask and manipulate a spell’s magic aura to make it harder to detect. Select one spell effect on the target creature or object. You must have either cast this spell yourself or have perceived it by means of detect magic or arcane sight.', 'a piece of gauze', NULL, false, false),
  ('mask_from_divination', 'Mask From Divination', 'divination', NULL, NULL, 4, 'both', 'alchemist 5, bloodrager 4, magus 5, shaman 5, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '24 hours', 'Will negates (harmless, object)', 'yes (harmless, object)', 'As part of the action used to cast this spell, you place the mask used as the focus component on the target’s face, after which it adheres tightly to the target for the spell’s duration and cannot be removed by physical force. Despite lacking eyes, this mask does not impair its wearer’s vision in any way. While in effect, this spell functions like nondetection, except it also foils divination spells that attempt to gather information about the creature, even if they don’t target it specifically. In the case of divination spells that would normally reveal the wearer’s presence, such as see invisibility, the spell works, but the wearer is detected only if the caster succeeds at a caster level check. Likewise, scrying attempts that specifically target the wearer do not work at all unless the caster succeeds at a caster level check. In addition, the DCs of skill checks to learn about the wearer or identify the wearer and its strengths and weaknesses-including Diplomacy checks to gather information, Perception checks opposed by the target’s Disguise checks, and Knowledge checks-increase by 4.', 'diamond dust worth 200 gp', 'an eyeless mask', false, true),
  ('masochistic_shadow', 'Masochistic Shadow', 'necromancy', NULL, 'evil, shadow', 4, 'both', 'antipaladin 4, bloodrager 4, magus 4, occultist 4, shaman 4, sorcerer/ wizard 4, witch 4', '1 standard action', 'close (25 ft. + 5 ft./level)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates, then Reflex partial; see text', 'yes', 'You animate the target’s shadow with semi-living energies drawn from the Shadow Plane, instilling a maddening hunger for its owner’s life energy within it. If the target fails its Will save, it takes 1d4 points of Strength damage as a quasi-real shadow manifests in its space and attacks it. This shadow remains attached to the target and moves wherever the target moves.', NULL, NULL, false, false),
  ('massacre', 'Massacre', 'necromancy', NULL, 'death', 9, 'both', 'cleric 9, psychic 9, shaman 9, sorcerer/wizard 9, witch 9', '1 standard action', NULL, NULL, '60-ft. line', NULL, 'instantaneous', 'Fort negates', 'yes', 'You unleash a wave of necromantic energy that snuffs out the life force of those in its path. This wave pulses out from you in a line 5 feet wide and 30 feet long. The wave visibly rips the souls from the bodies of those it passes through, which manifest as screaming, transparent versions of the affected creatures. The wave kills every living creature of 17 or fewer HD in the line, starting with the creature closest to you, to a maximum of 1d4 HD of creatures per caster level. No creature of 18 or more HD can be affected.', 'a flask of ectoplasmic residue', NULL, false, false),
  ('master_s_escape', 'Master’s Escape', 'conjuration', 'teleportation', NULL, 3, 'both', 'cleric 4, druid 4, sorcerer/wizard 4, summoner 3, witch 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'you and one summoned creature you control', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You create an extradimensional link between yourself and one summoned creature you control that allows you to switch places. After casting master’s escape, you can teleport to your summoned creature’s space as a swift action, causing your summoned creature to teleport to your former space. If your summoned creature is reduced to 0 or fewer hit points before you can use this spell’s effect, you can teleport to a space that you can see within 30 feet as an immediate action. After using either of these effects, the spell ends. A summoner can target his eidolon with this spell.', NULL, NULL, false, false),
  ('master_s_mutation', 'Master’s Mutation', 'transmutation', 'polymorph', NULL, 5, 'both', 'druid 5, sorcerer/wizard 5, summoner 5, witch 5', '1 standard action', 'close (25 ft. + 5 ft./level)', 'you and one summoned creature you control', NULL, NULL, '1 round/level (D)', 'none', 'no', 'You can mold the ephemeral substance of the Outer Planes, mutating one summoned creature that you control to better suit your needs. Select up to two of the following abilities and grant them to the target for the spell’s duration: burrow 30 feet, climb 40 feet, constrict, darkvision 90 feet, ferocity, fly 60 feet (average maneuverability), grab, jet, low-light vision, poison, rake, scent, swim 60 feet, trample, trip, or water breathing.', NULL, NULL, false, false),
  ('masterwork_transformation', 'Masterwork Transformation', 'transmutation', NULL, NULL, 2, 'both', 'bard 2, cleric/oracle 2, druid 2, sorcerer/wizard 2, witch 2; Subdomain greed 2; Elemental School void 2', '1 hour', 'touch', 'one weapon, suit of armor, shield, tool, or skill kit touched', NULL, NULL, 'instantaneous', 'none', 'no', 'You convert a non-masterwork item into its masterwork equivalent. A normal sword becomes a masterwork sword, a suit of leather armor becomes a masterwork suit of leather armor, a set of thieves’ tools becomes masterwork thieves’ tools, and so on. If the target object has no masterwork equivalent, the spell has no effect. You can affect 50 pieces of ammunition as if they were one weapon. You decide if the object’s appearance changes to reflect this improved quality.', 'see below', NULL, false, false),
  ('matchmaker', 'Matchmaker', 'enchantment', 'charm', 'mind-affecting', 2, 'arcane', 'bard 2, mesmerist 2, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'two living creatures', NULL, NULL, '1 hour/level', 'Will partial, see text', 'yes', 'You entice the target creatures to become romantically interested in one another. Each creature saves and applies spell resistance separately. Both must be affected for the spell to have an effect. If either creatures has a prior unfriendly or hostile attitude toward the other, it receives a +4 bonus on its saving throw.', 'a rose petal', NULL, false, false),
  ('mathematical_curse', 'Mathematical Curse', 'necromancy', NULL, 'curse', 2, 'both', 'antipaladin 2, bard 2, cleric 3, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'one living creature', NULL, NULL, 'see text', 'Will negates', 'yes', 'The Path of Numbers', 'a full set of 10 fingernails', NULL, true, false),
  ('maze', 'Maze', 'conjuration', 'teleportation', NULL, 6, 'arcane', 'sorcerer/wizard 8, summoner 6, witch 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'see text', 'none', 'yes', 'You banish the subject into an extra-dimensional labyrinth. Each round on its turn, it may attempt a DC 20 Intelligence check to escape the labyrinth as a full-round action. If the subject doesn’t escape, the maze disappears after 10 minutes, freeing the subject.', NULL, NULL, false, false),
  ('maze_of_madness_and_suffering', 'Maze of Madness and Suffering', 'conjuration', 'teleportation', 'evil, mind-affecting', 9, 'arcane', 'psychic 9, sorcerer/wizard 9, witch 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'see text', 'Will partial, see below', 'yes', 'This spell works like maze, except the DC of the Intelligence check to escape is 22 and each round a creature remains in the maze a different effect occurs depending on which section of the maze it is in. Roll on the following table each time the creature attempts an Intelligence check to escape the maze to see which part of the maze it wanders through; if a creature doesn’t attempt an Intelligence check, it stays in the same section and suffers that section’s effects. Any conditions or damage taken persist for the listed duration even if the creature exits the maze before then, but conditions don’t stack with themselves.', 'an ornate puzzle box worth 1,000 gp and soaked in fresh blood', NULL, false, true),
  ('medusa_s_bane', 'Medusa’s Bane', 'abjuration', NULL, NULL, 4, 'arcane', 'sorcerer/wizard 4, witch 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'This spell causes your eyes to take on a silvery mirror-like quality, transforming your eyes into metallic-looking orbs that reflect the world you see.', 'tiny fragment of a mirror', NULL, false, false),
  ('meld_into_stone', 'Meld into Stone', 'transmutation', NULL, 'earth', 3, 'divine', 'cleric/oracle 3, druid 3, psychic 3; Mystery stone 3', '1 standard action', 'personal', 'you', NULL, NULL, '10 min./level', NULL, NULL, 'Meld into stone enables you to meld your body and possessions into a single block of stone. The stone must be large enough to accommodate your body in all three dimensions. When the casting is complete, you and not more than 100 pounds of non-living gear merge with the stone. If either condition is violated, the spell fails and is wasted.', NULL, NULL, true, false),
  ('memorize_page', 'Memorize Page', 'enchantment', NULL, 'mind-affecting', 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, witch 1', '10 minutes', 'touch', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes (harmless)', 'The target gains a perfect memory of the page you used as a focus component. The target can visualize this page as easily as looking at it in person, including minute details visible to close scrutiny by the naked eye. The memory of the page includes text and images, such as a drawing or a map. Someone unfamiliar with the language on the page (or even an illiterate person) could relay what is written simply by copying the shapes of the letters so another person can read them.', NULL, 'the page to be memorized', false, false),
  ('memory_lapse', 'Memory Lapse', 'enchantment', NULL, 'mind-affecting', 1, 'arcane', 'bard 1, sorcerer/wizard 1; Subdomain memory 2; Mystery time 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'You cause the target to forget what happened from the casting of the spell back to the beginning of its last turn. This may allow a retry on a Diplomacy, Intimidate, or opposed skill check, though only with respect to the target, not other creatures that may be present.', NULL, NULL, false, false),
  ('memory_of_function', 'Memory of Function', 'transmutation', NULL, NULL, 7, 'both', 'cleric 7, sorcerer/wizard 7', '1 standard action', 'touch', 'object or construct touched', NULL, NULL, 'instantaneous', 'Will negates', 'yes', 'Note: The text has been updated per official errata. [Source]', NULL, NULL, false, true),
  ('mending', 'Mending', 'transmutation', NULL, NULL, 0, 'both', 'bard 0, cleric/oracle 0, druid 0, psychic 0, shaman 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0; Elemental School metal 0', '10 minutes', '10 ft.', 'one object of up to 1 lb./level', NULL, NULL, 'instantaneous', NULL, NULL, 'This spell repairs damaged objects, restoring 1d4 hit points to the object. If the object has the broken condition, this condition is removed if the object is restored to at least half its original hit points. All of the pieces of an object must be present for this spell to function. Magic items can be repaired by this spell, but you must have a caster level equal to or higher than that of the object. Magic items that are destroyed (at 0 hit points or less) can be repaired with this spell, but this spell does not restore their magic abilities. This spell does not affect creatures (including constructs). This spell has no effect on objects that have been warped or otherwise transmuted, but it can still repair damage done to such items.', NULL, NULL, false, false),
  ('mental_barrier_i', 'Mental Barrier I', 'abjuration', NULL, NULL, 2, 'arcane', 'psychic 2', '1 immediate action', 'personal', 'you', NULL, NULL, '1 round', NULL, NULL, 'You put a barrier of mental energy that protects you from harm.', NULL, NULL, false, false),
  ('mental_block', 'Mental Block', 'divination', NULL, 'mind-affecting', 1, 'arcane', 'bard 2, mesmerist 1, psychic 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You lock access to the target’s procedural memories, preventing it from drawing upon its experience and expertise.', NULL, NULL, false, false),
  ('merge_with_familiar', 'Merge with Familiar', 'transmutation', NULL, NULL, 2, 'both', 'shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'touch', 'your familiar or spirit animal; see text', NULL, NULL, '1 hour/level (D)', 'Fort negates (harmless)', 'yes', 'As long as the target is at least one size category smaller than you are, it can merge harmlessly into your body while under the effect of this spell. For the duration of this spell, you and the target can separate or merge at will as a move action. While merged, your familiar or spirit animal can’t be targeted or affected by most attacks and effects, though it still suffers from ongoing effects and their durations continue. It can be the recipient of effects that originate from you.', NULL, NULL, false, false),
  ('message', 'Message', 'transmutation', NULL, 'language-dependent', 0, 'arcane', 'bard 0, psychic 0, sorcerer/wizard 0, summoner/unchained summoner 0, witch 0; Elemental School air 0', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '10 min./level', 'none', 'no', 'You can whisper messages and receive whispered replies. Those nearby can hear these messages with a DC 25 Perception check. You point your finger at each creature you want to receive the message. When you whisper, the whispered message is audible to all targeted creatures within range. Magical silence, 1 foot of stone, 1 inch of common metal (or a thin sheet of lead), or 3 feet of wood or dirt blocks the spell. The message does not have to travel in a straight line. It can circumvent a barrier if there is an open path between you and the subject, and the path’s entire length lies within the spell’s range. The creatures that receive the message can whisper a reply that you hear. The spell transmits sound, not meaning; it doesn’t transcend language barriers. To speak a message, you must mouth the words and whisper.', NULL, 'a piece of copper wire', false, false),
  ('metabolic_molting', 'Metabolic Molting', 'transmutation', NULL, NULL, 6, 'both', 'cleric 6, druid 6, shaman 6, witch 6', '10 minutes', 'touch', 'willing creature or dead body touched', NULL, NULL, 'see text', 'Will negates (harmless)', 'no', 'You encase the willing subject in a jeweled shell that has the same hardness and hit points as 5 inches of iron (hardness 10, hp 150). For 7 days, the subject enters a state of suspended animation (as per temporal stasis), during which it heals from even the most grievous wounds. Each day, the subject regains 5 hit points per Hit Die it has as well as recovering from 2 points of ability damage or ability drain from any ability score of its choice. After 7 days, the shell crumbles away and the subject emerges, its body’s severed limbs, broken bones, and ruined organs regrown (as per regenerate).', 'a valuable gemstone worth at least 250 gp', NULL, false, true),
  ('meteor_swarm', 'Meteor Swarm', 'evocation', NULL, 'fire', 9, 'arcane', 'sorcerer/wizard 9; Subdomain stars 9; Bloodline boreal 9; Elemental School fire 9, metal 9; Mystery apocalypse 9, heavens 9, volcano 9', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'four 40-ft.-radius spreads, see text', NULL, 'instantaneous', 'none or Reflex half, see text', 'yes', 'Meteor swarm is a very powerful and spectacular spell that is similar to fireball in many aspects. When you cast it, four 2-foot-diameter spheres spring from your outstretched hand and streak in straight lines to the spots you select. The meteor spheres leave a fiery trail of sparks.', NULL, NULL, false, false),
  ('meticulous_match', 'Meticulous Match', 'divination', NULL, NULL, 3, 'both', 'bard 3, inquisitor 3, occultist 3, ranger 3, sorcerer/wizard 4, witch 4', '10 minutes', 'touch', 'two objects touched', NULL, NULL, NULL, 'Fort negates (object)', 'yes (object)', 'You compare two similar items and know if they are identical to one another or not. The spell can indicate an identical match, a categorical match, or no match. For instance, blood samples are identical if they are from the same creature. They are categorical if they are from the same species. There is no match if they are from different species, or if one sample is merely stage blood.', NULL, NULL, false, false),
  ('miasmal_dread', 'Miasmal Dread', 'enchantment', 'compulsion', 'fear, mind-affecting', 2, 'both', 'antipaladin 2, bard 2, bloodrager 2, inquisitor 3', '1 standard action', '30 feet', NULL, NULL, NULL, 'instantaneous', 'none', 'no', 'A cloud of sickly green mist pours from your mouth and coalesces around creatures in the cone. Attempt a single Intimidate check to demoralize as part of casting the spell, comparing the result against the DC to Intimidate each foe within the area. You demoralize all foes whose DC you meet or exceed.', NULL, NULL, false, false),
  ('miasmal_dread_half_orc', 'Miasmal Dread (Half-Orc)', 'enchantment', 'compulsion', 'fear, mind-affecting', 2, 'both', 'antipaladin 2, bard 2, bloodrager 2, inquisitor 3, mesmerist 3', '1 standard action', '30 feet', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'none', 'no', 'A cloud of sickly green mist pours from your mouth and coalesces around creatures in the cone.', NULL, NULL, false, false),
  ('miasmatic_form', 'Miasmatic Form', 'transmutation', NULL, 'air, poison', 4, 'arcane', 'alchemist 4, sorcerer/wizard 4', NULL, NULL, NULL, NULL, NULL, '1 minute/level', 'none; see text', 'no', 'This spell functions like gaseous form, except the target’s vaporous body is dangerous to creatures that touch it. A creature can make a Fortitude save (DC 14 + your Intelligence modifier) on its turn to resist the vapors. When you cast this spell, you select one of the following options.', 'contact or inhaled poison worth 100 gp', NULL, false, true),
  ('microcosm', 'Microcosm', 'illusion )', 'phantasm', 'mind-affecting', 9, 'arcane', 'psychic 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one or more creatures', NULL, NULL, 'permanent', 'Will partial (see text)', 'yes', 'You plunge the targets’ minds into a veiled immersive mindscape of your own design. You can affect any number of creatures whose combined total Hit Dice do not exceed 30.', NULL, NULL, false, false),
  ('mighty_fist_of_the_earth', 'Mighty Fist of the Earth', 'conjuration', 'creation', 'earth', 1, 'divine', 'cleric 1, druid 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'none', 'yes', 'You create a fist-sized rock that flies toward one enemy. Make an unarmed strike attack roll against the target as if it were in your threatened area. If the attack is successful, the rock deals bludgeoning damage to the target as if you had hit the target with your unarmed strike. If you have a ki pool, as long as you have at least 1 point in your ki pool, the rock counts as a ki strike.', NULL, NULL, true, false),
  ('mighty_strength', 'Mighty Strength', 'transmutation', NULL, NULL, 4, 'divine', 'cleric/oracle 4, paladin 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'As bull’s strength, except it grants a +8 enhancement bonus to Strength.', NULL, NULL, true, false),
  ('mind_blank', 'Mind Blank', 'abjuration', NULL, NULL, 8, 'arcane', 'sorcerer/wizard 8, witch 8; Domain liberation 8, protection 8; Subdomain flowing 8, thought 8; Bloodline aberrant 8; Elemental School void 8; Mystery intrigue 8', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '24 hours', 'Will negates (harmless)', 'yes (harmless)', 'The subject is protected from all devices and spells that gather information about the target through divination magic (such as detect evil, locate creature, scry, and see invisible). This spell also grants a +8 resistance bonus on saving throws against all mind-affecting spells and effects. Mind blank even foils limited wish, miracle, and wish spells when they are used in such a way as to gain information about the target. In the case of scrying that scans an area the creature is in, such as arcane eye, the spell works but the creature simply isn’t detected. Scrying attempts that are targeted specifically at the subject do not work at all.', NULL, NULL, false, false),
  ('mind_fog', 'Mind Fog', 'enchantment', 'compulsion', 'mind-affecting', 5, 'arcane', 'bard 5, sorcerer/wizard 5, witch 5; Elemental School void 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'fog spreads in 20-ft. radius, 20 ft. high', '30 minutes and 2d6 rounds; see text', 'Will negates', 'yes', 'Mind fog produces a bank of thin mist that weakens the mental resistance of those caught in it. Creatures in the mind fog take a -10 penalty on Wisdom checks and Will saves. (A creature that successfully saves against the fog is not affected and need not make further saves even if it remains in the fog.) Affected creatures take the penalty as long as they remain in the fog and for 2d6 rounds thereafter. The fog is stationary and lasts for 30 minutes (or until dispersed by wind).', NULL, NULL, false, false),
  ('mind_maze', 'Mind Maze', 'enchantment', 'compulsion', 'mind-affecting', 3, 'both', 'bard 3, cleric 3, shaman 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one living creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'This spell causes the target to act as though it’s wandering through a maze. While under the effects of the spell, the target can’t make attacks or cast spells and must take at least one move action each round to walk in a random direction determined using the guidelines for missed splash weapons. The target must move at its maximum speed during this required movement, though additional move actions after the first can cover shorter distances. If this movement takes the target into a dangerous area, such as through a threatened square or off a ledge, the target receives a second Saving Throw to end the effect before moving into peril. Walking into a harmless obstacle, such as a wall, ends the target’s movement.', 'a chicken skull', NULL, true, false),
  ('mind_over_matter', 'Mind Over Matter', 'necromancy', NULL, NULL, 2, 'arcane', 'mesmerist 2, psychic 2, spiritualist 2', '1 standard action', 'touch', 'one creature', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'You blur the lines between mind and body, reassigning ability damage or drain your target has taken to a corresponding ability score, as per the following table.', NULL, NULL, false, false),
  ('mind_probe', 'Mind Probe', 'divination', NULL, 'mind-affecting', 3, 'arcane', 'medium 3, mesmerist 4, occultist 4, psychic 4, sorcerer/wizard 5', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'You gain access to the subject’s memories and knowledge. You can attempt to learn the answer to one question per round.', NULL, NULL, false, false),
  ('mind_swap', 'Mind Swap', 'enchantment', 'compulsion', 'mind-affecting', 3, 'arcane', 'medium 3, mesmerist 5, occultist 4, psychic 5, sorcerer/wizard 6, spiritualist 4, summoner 5, witch 6', '1 round', 'medium (100 ft. + 10 ft./level)', 'one creature', NULL, NULL, '1 hour/level (D)', 'Will negates', 'yes', 'This spell is similar to possession, except you switch minds with the target, so instead of the target’s soul sharing its body with yours and being unable to act, the target’s mind moves to your body and can control it as if you each had cast possession on the other.', NULL, NULL, false, false),
  ('mind_thrust_i', 'Mind Thrust I', 'divination', NULL, 'mind-affecting', 1, 'arcane', 'psychic 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous', 'Will half', 'yes', 'You divine the most vulnerable portions of your opponent’s mind and overload it with a glut of psychic information.', NULL, NULL, false, false),
  ('mindlink', 'Mindlink', 'divination', NULL, 'mind-affecting', 1, 'both', 'medium 1, mesmerist 1, occultist 1, psychic 1, shaman 1, sorcerer/wizard 1, spiritualist 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, 'instantaneous', 'Will negates (harmless)', 'yes', 'You link your mind to that of a touched creature to swiftly communicate a large amount of complex information in an instant. You decide what the target learns, limited to any amount of information that otherwise could be communicated in 10 minutes. This information comes in a series of visual images and emotional sensations, and isn’t language-dependent.', NULL, NULL, false, false),
  ('mindlocked_messenger', 'Mindlocked Messenger', 'enchantment', 'compulsion', 'language-dependent, mind-affecting', 2, 'both', 'bard 2, mesmerist 2, psychic 3, shaman 3, sorcerer/wizard 3, spiritualist 3, witch 3', '10 minutes', 'close (25 ft. + 5 ft./2 levels)', 'one willing living creature', NULL, NULL, 'permanent until discharged (see text)', 'Will negates (harmless)', 'yes (harmless)', 'You speak a short message (up to 10 words per caster level), implanting both it and the identity of the message’s intended recipient in the mind of a willing creature. The creature is aware of the message and who the recipient is. Any attempt to speak, write, or otherwise communicate the message to anyone other than its intended recipient causes the target to forget the message for 1d6 minutes. Attempts to read the target’s mind (such as with detect thoughts) or to force the target to reveal the message (such as with torture or magical compulsion) likewise cause temporary amnesia regarding the message.', NULL, NULL, false, false),
  ('mindscape_door', 'Mindscape Door', 'illusion )', 'phantasm', 'mind-affecting', 3, 'arcane', 'medium 3, mesmerist 3, psychic 3, sorcerer/wizard 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one illusory portal', '10 minutes/level', 'Will negates (see text)', 'no', 'You or other creatures enter into or escape from a mindscape through an imaginary doorway. This doorway takes on any form of your choosing, but can be no larger than a 5-foot cube. This spell has different effects depending on whether you are inside a mindscape when you cast it.', NULL, NULL, false, false),
  ('mindshock', 'Mindshock', 'divination', NULL, 'mind-affecting, pain', 2, 'both', 'antipaladin 2, bloodrager 2, inquisitor 2, medium 2, occultist 2, psychic 2, shaman 2, spiritualist 2, witch 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You charge yourself with violent psychic energy so attacks you make with weapons, natural weapons, and unarmed strikes cause the target to recall pain suffered in the past. Such attacks deal 1d4 points of nonlethal damage in addition to their normal damage, though creatures immune to mind-affecting or pain effects ignore this additional damage. In addition, when you confirm a critical hit, the target is confused for 1 round by the pain. Creatures immune to critical hits, mind-affecting, or pain effects ignore the confusion. Even if you confirm multiple critical hits while this spell is in effect, an individual creature can only be confused by a single casting of mindshock once.', NULL, NULL, false, false),
  ('mindwipe', 'Mindwipe', 'enchantment', 'compulsion', 'mind-affecting', 4, 'arcane', 'medium 4, mesmerist 4, occultist 4, psychic 4, sorcerer/wizard 4, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, 'instantaneous; see text', 'Will negates', 'yes', 'You erase a portion of the target’s mind and experiences, inflicting 2 temporary negative levels on the target for 1 day per caster level. If the target is a spellcaster who must choose and prepare spells in advance, each negative level imposed by mindwipe also causes the target to lose one prepared spell from her highest level of spells known for each of her spellcasting classes for which she must prepare spells. These lost spells are no longer considered known by the target until the corresponding negative levels are removed.', NULL, NULL, false, false),
  ('minor_creation', 'Minor Creation', 'conjuration', 'creation', NULL, 3, 'arcane', 'sorcerer/ wizard 4, summoner/unchained summoner 3, witch 4; Domain artifice 4; Bloodline djinni 4; Elemental School void 4, wood 4; Mystery wood 3', '1 minute', '0 ft.', NULL, NULL, 'unattended, non-magical object of nonliving plant matter, up to 1 cu. ft./level', '1 hour/level (D)', 'none', 'no', 'You create a non-magical, unattended object of nonliving vegetable matter. The volume of the item created cannot exceed 1 cubic foot per caster level. You must succeed on an appropriate Craft skill check to make a complex item.', 'a tiny piece of matter of the same sort of item you plan to create with minor creation', NULL, false, false),
  ('minor_dream', 'Minor Dream', 'illusion', 'figment', 'mind-affecting', 2, 'arcane', 'alchemist 2, bard 3, medium 2, mesmerist 3, psychic 3, sorcerer/wizard 3, witch 2', '1 minute', 'unlimited', 'you or one gnome touched', NULL, NULL, 'see text', 'none', 'yes', 'This spell functions as the dream spell, except as follows. The messenger must be yourself or a gnome touched. The message can be no longer than 20 words. If the recipient of the message is not asleep when the spell is cast, the spell automatically fails.', NULL, NULL, false, false),
  ('minor_image', 'Minor Image', 'illusion', 'figment', NULL, 2, 'arcane', 'bard 2, magus 2, medium 2, mesmerist 2, occultist 2, psychic 2, sorcerer/wizard 2; Subdomain imagination 2', NULL, NULL, NULL, NULL, NULL, 'concentration + 2 rounds', NULL, NULL, 'This spell functions like silent image, except that minor image includes some minor sounds but not understandable speech.', NULL, NULL, false, false),
  ('minor_phantom_object', 'Minor Phantom Object', 'illusion', 'shadow', 'shadow', 4, 'arcane', 'sorcerer/wizard 4', '1 minute', '0 ft.', NULL, NULL, 'illusory, unattended, non-magical object of nonliving plant matter, up to 1 cu. ft./level', '10 minutes/level (D)', 'Will negates', 'yes', 'This spell functions as the minor creation spell, except the object created is a semi-real illusion. Any creature that interacts with the object may make a Will save, with success causing the object to cease to exist. A gnome casting this spell may make a Spellcraft check in place of any Craft check required to make a complex item.', NULL, NULL, false, false)
